// ---------- v120 TURBO: memoria caliente de migraciones ----------
// Cada función *Ensure corre UNA vez por instancia del worker. Las
// instancias calientes de Cloudflare atienden miles de requests, así
// que la cirugía de esquema (CREATE/ALTER) deja de pagarse por llamada.
const _yaListo = {};

// ---------- CORS ----------
const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'POST, GET, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type',
};

// ============================================================
//  v63 — SEGURIDAD EN DOS VELOCIDADES
//  SEGURIDAD='compat' (defecto): todo sigue funcionando igual.
//  SEGURIDAD='estricta': lo sensible exige PIN o token firmado.
//  Se activa SOLO cuando las apps ya mandan PIN (ver runbook).
// ============================================================
const SEG_PREFIJOS_PRIVADOS = ['transportes/', 'bodega/', 'proyectos/', 'archivo-manual/', 'rrhh/'];
const SEG_EXT_OK = new Set(['pdf','png','jpg','jpeg','webp','gif','heic','xlsx','xls','csv','docx','doc','txt','zip']);
const SEG_MIME_POR_EXT = { pdf:'application/pdf', png:'image/png', jpg:'image/jpeg', jpeg:'image/jpeg',
  webp:'image/webp', gif:'image/gif', heic:'image/heic', xlsx:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  xls:'application/vnd.ms-excel', csv:'text/csv', docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  doc:'application/msword', txt:'text/plain', zip:'application/zip' };
function segModo(env) { return (env && env.SEGURIDAD === 'estricta') ? 'estricta' : 'compat'; }
function segEsPrivado(key) { return SEG_PREFIJOS_PRIVADOS.some(p => String(key || '').startsWith(p)); }
// ¿el contentType puede ejecutar código en el navegador? → se sirve neutro
function segMimePeligroso(ct) { return /html|svg|xml|javascript|xhtml/i.test(String(ct || '')); }
async function segPinValido(env, pin) {
  const p = String(pin || '').trim();
  if (!p) return false;
  try {
    const u = await env.DB.prepare('SELECT id FROM usuarios WHERE pin = ? AND activo = 1').bind(p).first();
    return !!u;
  } catch (e) { return false; }
}
function segSecreto(env) { return String((env && (env.FIRMA_SECRETO || env.SETUP_KEY)) || SETUP_KEY); }
async function segFirma(env, texto) {
  const enc = new TextEncoder();
  const k = await crypto.subtle.importKey('raw', enc.encode(segSecreto(env)), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const sig = await crypto.subtle.sign('HMAC', k, enc.encode(String(texto)));
  return [...new Uint8Array(sig)].map(b => b.toString(16).padStart(2, '0')).join('');
}
// token firmado para un archivo privado: t = HMAC(key|exp), e = epoch segundos
async function segTokenArchivo(env, key, expEpoch) {
  return await segFirma(env, String(key) + '|' + String(expEpoch));
}
async function segTokenValido(env, key, t, e) {
  const exp = Number(e) || 0;
  if (!t || !exp || exp * 1000 < Date.now()) return false;
  const esperado = await segTokenArchivo(env, key, exp);
  const a = String(t), b = esperado;
  if (a.length !== b.length) return false;
  let dif = 0; for (let i = 0; i < a.length; i++) dif |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return dif === 0;
}
// acción: generar un enlace firmado para un archivo privado (exige PIN válido)
async function segArchivoToken(env, body) {
  if (!await segPinValido(env, body.pin)) return j({ ok: false, error: 'PIN inválido' }, 403);
  const key = String(body.ruta || body.key || '').replace(/^\/+/, '').replace(/^archivo\//, '');
  if (!key) return j({ ok: false, error: 'Falta ruta' });
  const dias = Math.min(365, Math.max(1, Number(body.dias) || 30));
  const exp = Math.floor(Date.now() / 1000) + dias * 86400;
  const t = await segTokenArchivo(env, key, exp);
  return j({ ok: true, ruta: key, vence_dias: dias,
    url: 'https://marc-erp-espejo.mariangel.workers.dev/archivo/' + key + '?t=' + t + '&e=' + exp });
}

// ---------- Respuesta JSON ----------
function j(obj, status = 200) {
  return new Response(JSON.stringify(obj, null, 2), {
    status,
    headers: { 'content-type': 'application/json; charset=utf-8', ...cors },
  });
}

// ---------- Fecha/hora Costa Rica (UTC-6) ----------
function crParts() {
  const d = new Date(Date.now() - 6 * 3600 * 1000);
  return { fecha: d.toISOString().slice(0, 10), hora: d.toISOString().slice(11, 16), iso: new Date().toISOString() };
}

// ---------- Numeración atómica (anti-choque entre tablets) ----------
async function siguienteNumero(env, contador, prefijo) {
  const r = await env.DB
    .prepare('UPDATE contadores SET valor = valor + 1 WHERE nombre = ? RETURNING valor')
    .bind(contador).first();
  if (!r) throw new Error('Contador no encontrado: ' + contador + ' (¿corriste /setup?)');
  return prefijo + r.valor;
}

