async function permisosDeRol(env, rol) {
  const res = await env.DB.prepare('SELECT modulo, nivel FROM permisos WHERE rol = ?').bind(rol).all();
  const m = {}; (res.results || []).forEach(r => { m[r.modulo] = r.nivel; });
  return m;
}

// v37: alta idempotente de vendedores para Ventas CRM.
// Crea el rol/permiso y los usuarios que faltan; a los que ya existen (Brayan, Melanny)
