async function login(env, body) {
  const pin = String(body.pin || '').trim();
  if (!pin) return j({ ok: false, error: 'PIN vacío' });
  const u = await env.DB.prepare(
    'SELECT id,pin,nombre,apellido,email,telefono,rol,empresa FROM usuarios WHERE pin = ? AND activo = 1'
  ).bind(pin).first();
  if (!u) return j({ ok: false, error: 'PIN incorrecto' });
  const permisos = await permisosDeRol(env, u.rol);
  // Permisos individuales (por módulo) pisan a los del rol
  await puEnsure(env);
  const ovLogin = await env.DB.prepare('SELECT modulo,nivel FROM permisos_usuario WHERE usuario_id = ?').bind(u.id).all();
  (ovLogin.results || []).forEach(r => { permisos[r.modulo] = r.nivel; });
  // LLAVE MAESTRA DEL DUEÑO: dueño/admin reciben TODOS los módulos (presentes y
  // futuros) en nivel máximo, sin depender de filas en la tabla de permisos.
  if (u.rol === 'dueno' || u.rol === 'admin') {
    const BASE = ['nucleo','usuarios','proyectos','bodega','taller','compras','stock','dashboard',
      'financiero','crm','rrhh','inventarios','cotizador','cotpresion','alquileres','conteo',
      'pruebas','certificados','mantenimiento','transportes','viajes','facturacion','reportes',
      'contabilidad','conteo_ductos','pruebas_ductos'];
    BASE.forEach(m => { permisos[m] = 'admin'; });
    try {
      const mods = (await env.DB.prepare('SELECT codigo FROM modulos').all()).results || [];
      mods.forEach(m => { if (m && m.codigo) permisos[m.codigo] = 'admin'; });
    } catch (e) {}
  }
  const rolInfo = await env.DB.prepare('SELECT nombre FROM roles WHERE codigo = ?').bind(u.rol).first();
  // v20: nombre y email a nivel raíz (la app de Bodega los consume así)
  const nombreCompleto = ((u.nombre || '') + (u.apellido ? ' ' + u.apellido : '')).trim();
  return j({ ok: true, usuario: u, rol: u.rol, rolNombre: rolInfo ? rolInfo.nombre : u.rol, permisos, nombre: nombreCompleto, email: u.email || '', pin: u.pin });
}

// Compat: algunas apps llaman validarPin
async function validarPin(env, body) { return await login(env, body); }

// ¿El PIN tiene al menos "nivelMin" en "modulo"?  (dueño/admin y SETUP_KEY pasan siempre)
// v98 — La clave que de verdad manda: el secreto de Cloudflare pisa a la
// constante del código (regla de la v63). Los enlaces de administración tienen
// que usar ESTA, no la constante, o el worker se rechaza a sí mismo.
function segClaveReal(env) { return (env && env.SETUP_KEY) || SETUP_KEY; }
// Un enlace vale con el secreto o con la constante (así los enlaces viejos
// como /setup?key=marc2026 siguen sirviendo aunque haya secreto puesto).
function segClaveOk(env, k) {
  if (!k) return false;
  return k === segClaveReal(env) || k === SETUP_KEY;
}
async function tienePermiso(env, pin, key, modulo, nivelMin) {
  if (key && key === ((env && env.SETUP_KEY) || SETUP_KEY)) return true;   // v63: secreto pisa a la constante
  if (!pin) return false;
  const u = await env.DB.prepare('SELECT rol FROM usuarios WHERE pin = ? AND activo = 1').bind(String(pin)).first();
  if (!u) return false;
  if (u.rol === 'dueno' || u.rol === 'admin') return true;
  await puEnsure(env);
  const ovr = await env.DB.prepare('SELECT pu.nivel FROM permisos_usuario pu JOIN usuarios us ON us.id = pu.usuario_id WHERE us.pin = ? AND pu.modulo = ?')
    .bind(String(pin), modulo).first();
  if (ovr) return nivelOrd(ovr.nivel) >= nivelOrd(nivelMin);
  const p = await env.DB.prepare('SELECT nivel FROM permisos WHERE rol = ? AND modulo = ?').bind(u.rol, modulo).first();
  return nivelOrd(p && p.nivel) >= nivelOrd(nivelMin);
}

// ============================================================
//  PERMISOS POR USUARIO Y POR MÓDULO
//  Cada módulo puede tener su propio administrador de accesos:
//  quien tenga nivel 'admin' EN ESE MÓDULO gestiona a su gente,
//  sin tocar los demás módulos del ERP.
// ============================================================
let PU_READY = false;
async function puEnsure(env) {
  if (_yaListo.puEnsure) return; _yaListo.puEnsure = true;   // v120 ⚡ una vez por instancia
  if (PU_READY) return;
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS permisos_usuario (
    usuario_id TEXT NOT NULL, modulo TEXT NOT NULL, nivel TEXT NOT NULL,
    PRIMARY KEY (usuario_id, modulo) )`).run();
  PU_READY = true;
}
async function moduloEsAdmin(env, pin, key, modulo) {
  if (await tienePermiso(env, pin, key, modulo, 'admin')) return true;
  return await tienePermiso(env, pin, key, 'usuarios', 'admin');
}
// Lista de usuarios con su nivel efectivo en un módulo
async function usuariosModulo(env, body) {
  await puEnsure(env);
  const modulo = String(body.modulo || '');
  if (!modulo) return j({ ok: false, error: 'Falta el módulo' }, 400);
  if (!await tienePermiso(env, body.pin, body.key, 'usuarios', 'admin')) return j({ ok: false, error: 'Solo el dueño/administrador del ERP puede ver los usuarios' }, 403);
  const us = (await env.DB.prepare('SELECT id,nombre,apellido,rol FROM usuarios WHERE activo = 1 ORDER BY nombre').all()).results || [];
  const rp = (await env.DB.prepare('SELECT rol,nivel FROM permisos WHERE modulo = ?').bind(modulo).all()).results || [];
  const nivelRol = {}; rp.forEach(r => { nivelRol[r.rol] = r.nivel; });
  const ov = (await env.DB.prepare('SELECT usuario_id,nivel FROM permisos_usuario WHERE modulo = ?').bind(modulo).all()).results || [];
  const nivelOv = {}; ov.forEach(r => { nivelOv[r.usuario_id] = r.nivel; });
  const usuarios = us.map(u => {
    const total = (u.rol === 'dueno' || u.rol === 'admin');
    const base = total ? 'admin' : (nivelRol[u.rol] || 'sin');
    const o = nivelOv[u.id] || null;
    return { id: u.id, nombre: ((u.nombre || '') + ' ' + (u.apellido || '')).trim(), rol: u.rol,
      nivelRol: base, override: o, efectivo: total ? 'admin' : (o || base) };
  });
  return j({ ok: true, modulo, usuarios, niveles: NIVELES });
}
// Asigna (o quita, con nivel='rol') el permiso individual de un usuario en un módulo
async function permisoUsuarioGuardar(env, body) {
  await puEnsure(env);
  const modulo = String(body.modulo || ''), uid = String(body.usuarioId || '');
  if (!modulo || !uid) return j({ ok: false, error: 'Falta módulo o usuario' }, 400);
  if (!await tienePermiso(env, body.pin, body.key, 'usuarios', 'admin')) return j({ ok: false, error: 'Solo el dueño/administrador del ERP puede cambiar accesos' }, 403);
  const u = await env.DB.prepare('SELECT rol FROM usuarios WHERE id = ?').bind(uid).first();
  if (!u) return j({ ok: false, error: 'Usuario no encontrado' }, 404);
  if (u.rol === 'dueno' || u.rol === 'admin') return j({ ok: false, error: 'Los dueños/administradores siempre tienen acceso total' }, 400);
  const nivel = String(body.nivel || 'rol');
  if (nivel === 'rol') {
    await env.DB.prepare('DELETE FROM permisos_usuario WHERE usuario_id = ? AND modulo = ?').bind(uid, modulo).run();
  } else {
    if (!NIVELES.includes(nivel)) return j({ ok: false, error: 'Nivel inválido' }, 400);
    await env.DB.prepare(`INSERT INTO permisos_usuario (usuario_id,modulo,nivel) VALUES (?,?,?)
      ON CONFLICT(usuario_id,modulo) DO UPDATE SET nivel=excluded.nivel`).bind(uid, modulo, nivel).run();
  }
  return j({ ok: true, usuarioId: uid, modulo, nivel });
}
// Un admin de módulo puede crear un usuario nuevo (entra al ERP como
// solicitante) con nivel específico en SU módulo.
async function usuarioModuloCrear(env, body) {
  await puEnsure(env);
  const modulo = String(body.modulo || '');
  if (!modulo) return j({ ok: false, error: 'Falta el módulo' }, 400);
  if (!await tienePermiso(env, body.pin, body.key, 'usuarios', 'admin')) return j({ ok: false, error: 'Solo el dueño/administrador del ERP puede crear usuarios' }, 403);
  const nombre = String(body.nombre || '').trim();
  const pinNuevo = String(body.pinNuevo || '').trim();
  const nivel = NIVELES.includes(body.nivel) ? body.nivel : 'operar';
  if (!nombre || !pinNuevo) return j({ ok: false, error: 'Falta nombre o PIN' }, 400);
  if (!/^[0-9]{3,6}$/.test(pinNuevo)) return j({ ok: false, error: 'El PIN debe tener de 3 a 6 dígitos' }, 400);
  const existe = await env.DB.prepare('SELECT id FROM usuarios WHERE pin = ?').bind(pinNuevo).first();
  if (existe) return j({ ok: false, error: 'Ese PIN ya está en uso por otra persona' }, 400);
  const id = 'u_' + pinNuevo;
  await env.DB.prepare(`INSERT INTO usuarios (id,pin,nombre,apellido,rol,empresa,activo,creado_en) VALUES (?,?,?,?,'solicitante','',1,?)`)
    .bind(id, pinNuevo, nombre, String(body.apellido || ''), new Date().toISOString()).run();
  await env.DB.prepare(`INSERT INTO permisos_usuario (usuario_id,modulo,nivel) VALUES (?,?,?)
    ON CONFLICT(usuario_id,modulo) DO UPDATE SET nivel=excluded.nivel`).bind(id, modulo, nivel).run();
  return j({ ok: true, id, pin: pinNuevo, nivel });
}

