async function usuarioGuardar(env, body) {
  if (!await tienePermiso(env, body.adminPin, body.key, 'usuarios', 'admin')) return j({ ok: false, error: 'No autorizado' }, 403);
  const u = body.usuario || {};
  if (!u.pin || !u.rol || !u.nombre) return j({ ok: false, error: 'Falta PIN, nombre o rol' }, 400);
  const t = crParts();
  const id = u.id || ('u_' + u.pin);
  await env.DB.prepare(`INSERT INTO usuarios (id,pin,nombre,apellido,email,telefono,rol,empresa,activo,creado_en,actualizado_en)
    VALUES (?,?,?,?,?,?,?,?,?,COALESCE((SELECT creado_en FROM usuarios WHERE id=?),?),?)
    ON CONFLICT(id) DO UPDATE SET pin=excluded.pin, nombre=excluded.nombre, apellido=excluded.apellido,
      email=excluded.email, telefono=excluded.telefono, rol=excluded.rol, empresa=excluded.empresa,
      activo=excluded.activo, actualizado_en=excluded.actualizado_en`)
    .bind(id, String(u.pin), u.nombre, u.apellido || '', u.email || '', u.telefono || '', u.rol, u.empresa || '',
          (u.activo === 0 ? 0 : 1), id, t.iso, t.iso).run();
  return j({ ok: true, id });
}
async function usuarioEliminar(env, body) {
  if (!await tienePermiso(env, body.adminPin, body.key, 'usuarios', 'admin')) return j({ ok: false, error: 'No autorizado' }, 403);
  const due = await env.DB.prepare("SELECT COUNT(*) AS n FROM usuarios WHERE rol='dueno' AND activo=1").first();
  const yo = await env.DB.prepare('SELECT rol FROM usuarios WHERE id=? OR pin=?').bind(body.id || '', String(body.pin || '')).first();
  if (yo && yo.rol === 'dueno' && due && due.n <= 1) return j({ ok: false, error: 'No podés borrar el último dueño' }, 400);
  await env.DB.prepare('DELETE FROM usuarios WHERE id=? OR pin=?').bind(body.id || '', String(body.pin || '')).run();
  return j({ ok: true });
}

// Genera PIN automático (últimos dígitos de cédula) para empleados sin usuario
async function generarPines(env, body) {
  if (!await tienePermiso(env, body.adminPin, body.key, 'usuarios', 'admin')) return j({ ok: false, error: 'No autorizado' }, 403);
  const emps = (await env.DB.prepare('SELECT nombre,cedula,email,razon_social FROM empleados WHERE activo=1 ORDER BY nombre').all()).results || [];
  const ex = (await env.DB.prepare('SELECT pin,email FROM usuarios').all()).results || [];
  const usedPins = new Set(ex.map(r => String(r.pin)));
  const usedEmails = new Set(ex.map(r => (r.email || '').toLowerCase()).filter(Boolean));
  const t = crParts(); const B = []; const creados = [];
  for (const e of emps) {
    const email = (e.email || '').toLowerCase();
    if (email && usedEmails.has(email)) continue;
    const ced = String(e.cedula || '').replace(/\D/g, ''); if (!ced) continue;
    let k = 4, pin = ced.slice(-4);
    while (usedPins.has(pin) && k < ced.length) { k++; pin = ced.slice(-k); }
    if (usedPins.has(pin)) continue;
    usedPins.add(pin); if (email) usedEmails.add(email);
    B.push(env.DB.prepare(`INSERT OR IGNORE INTO usuarios (id,pin,nombre,email,rol,activo,creado_en) VALUES (?,?,?,?,'solicitante',1,?)`)
      .bind('u_' + ced, pin, e.nombre, e.email || '', t.iso));
    creados.push({ nombre: e.nombre, pin });
  }
  if (B.length) await env.DB.batch(B);
  return j({ ok: true, creados, total: creados.length });
}

// ============================================================
//  PROYECTOS (compartidos por todos los módulos)
// ============================================================
async function proyectosListar(env, body) {
  const where = []; const binds = [];
  if (!body.incluirInactivos) where.push('activo = 1');
  if (body.razonSocial) { where.push('razon_social = ?'); binds.push(body.razonSocial); }
  if (body.empresa) { where.push('empresa = ?'); binds.push(body.empresa); }
  const sql = 'SELECT codigo,nombre,razon_social,empresa,cliente,activo FROM proyectos' +
    (where.length ? ' WHERE ' + where.join(' AND ') : '') + ' ORDER BY nombre';
  const res = await env.DB.prepare(sql).bind(...binds).all();
  return j({ ok: true, proyectos: res.results || [] });
}
async function proyectoGuardar(env, body) {
  if (!await tienePermiso(env, body.adminPin, body.key, 'proyectos', 'operar')) return j({ ok: false, error: 'No autorizado' }, 403);
  const p = body.proyecto || {};
  const codigo = (p.codigo || '').trim(), razon = (p.razon_social || p.razonSocial || '').trim();
  if (!codigo || !razon) return j({ ok: false, error: 'Falta código o razón social' }, 400);
  const t = crParts();
  await env.DB.prepare(`INSERT INTO proyectos (codigo,nombre,razon_social,empresa,cliente,activo,creado_en)
    VALUES (?,?,?,?,?,?,?) ON CONFLICT(codigo,razon_social) DO UPDATE SET
      nombre=excluded.nombre, empresa=excluded.empresa, cliente=excluded.cliente, activo=excluded.activo`)
    .bind(codigo, (p.nombre || '').trim(), razon, p.empresa || '', p.cliente || '', (p.activo === 0 ? 0 : 1), t.iso).run();
  return j({ ok: true, codigo });
}
async function importarProyectos(env, body) {
  if (body.key !== SETUP_KEY) return j({ ok: false, error: 'clave' }, 403);
  const t = crParts(); const B = []; let n = 0;
  for (const f of (body.filas || [])) {
    const codigo = (f.codigo || '').trim(), razon = (f.razon_social || f.razonSocial || '').trim();
    if (!codigo || !razon) continue;
    B.push(env.DB.prepare(`INSERT INTO proyectos (codigo,nombre,razon_social,empresa,cliente,activo,creado_en)
      VALUES (?,?,?,?,?,1,?) ON CONFLICT(codigo,razon_social) DO UPDATE SET nombre=excluded.nombre, empresa=excluded.empresa, activo=1`)
      .bind(codigo, (f.nombre || '').trim(), razon, f.empresa || '', f.cliente || '', t.iso));
    n++;
  }
  for (let i = 0; i < B.length; i += 40) await env.DB.batch(B.slice(i, i + 40));
  return j({ ok: true, total: n });
}

