async function importarCatalogo(env, body) {
  if (body.key !== SETUP_KEY) return j({ ok: false, error: 'clave' }, 403);
  const B = (body.filas || [])
    .filter(f => String(f.codigo || '').trim() && String(f.razon_social || f.razonSocial || '').trim())
    .map(f => env.DB.prepare(`INSERT OR REPLACE INTO catalogo_items (codigo_erp,razon_social,descripcion,unidad,categoria,activo) VALUES (?,?,?,?,?,1)`)
      .bind(String(f.codigo).trim(), String(f.razon_social || f.razonSocial).trim(), String(f.descripcion || '').trim(), f.unidad || null, f.categoria || null));
  for (let i = 0; i < B.length; i += 40) await env.DB.batch(B.slice(i, i + 40));
  return j({ ok: true, total: B.length });
}

// ============================================================
//  R2 (archivos) + auditoría
// ============================================================
function soloBase64(s) { return !s ? '' : (s.includes(',') ? s.split(',')[1] : s); }
async function guardarArchivo(env, body) {
  if (!body.base64) return j({ ok: false, error: 'sin archivo' }, 400);
  if (!env.ARCHIVOS) return j({ ok: false, error: 'R2 no configurado (binding ARCHIVOS)' }, 400);
  if (segModo(env) === 'estricta' && !await segPinValido(env, body.pin)) return j({ ok: false, error: 'Subir archivos exige PIN' }, 403);
  const ext = String(body.nombre || 'archivo').split('.').pop().toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 6) || 'bin';
  if (!SEG_EXT_OK.has(ext)) return j({ ok: false, error: 'Tipo de archivo no permitido: .' + ext }, 400);   // v63
  const carpeta = (body.carpeta || 'general').replace(/[^a-z0-9_-]/gi, '');
  const id = (body.numero ? String(body.numero) : ('f' + Date.now())) + '-' + Math.random().toString(36).slice(2, 8);
  const ruta = carpeta + '/' + id + '.' + ext;
  try {
    const bytes = Uint8Array.from(atob(soloBase64(body.base64)), c => c.charCodeAt(0));
    await env.ARCHIVOS.put(ruta, bytes, { httpMetadata: { contentType: SEG_MIME_POR_EXT[ext] || 'application/octet-stream' } });   // v63: MIME por extensión, no el del cliente
    const base = 'https://marc-erp.late-dew-2dd9.workers.dev/archivo';   // v59: puerta del núcleo
    return j({ ok: true, url: base + '/' + ruta, ruta });
  } catch (e) { return j({ ok: false, error: e.message }, 500); }
}
// Fotos de proyectos → R2 (full + thumb en UNA sola llamada).
// Recibe dataURLs (o base64 puro) y devuelve URLs públicas.
// Si R2 no está o algo falla, devuelve ok:false → el frontend CONSERVA
// el dataURL (no se pierde la foto) y reintenta en el próximo guardado.
async function fotoSubir(env, body) {
  if (!env.ARCHIVOS) return j({ ok: false, error: 'R2 no configurado (binding ARCHIVOS)' }, 400);
  if (segModo(env) === 'estricta' && !await segPinValido(env, body.pin)) return j({ ok: false, error: 'Subir fotos exige PIN' }, 403);   // v63
  if (!body.full && !body.thumb) return j({ ok: false, error: 'sin imagen (falta full/thumb)' }, 400);
  const limpia = (s, def) => (String(s || def).replace(/[^a-zA-Z0-9_-]/g, '').slice(0, 48) || def);
  const pid = limpia(body.projectId, 'sin-proyecto');
  const fid = limpia(body.photoId, 'f' + Date.now());
  const base = 'https://marc-erp.late-dew-2dd9.workers.dev/archivo';   // v59: puerta del núcleo
  const ct = body.contentType || 'image/jpeg';
  const out = {};
  try {
    for (const tipo of ['full', 'thumb']) {
      if (!body[tipo]) continue;
      const ruta = 'proyectos/' + pid + '/' + fid + '_' + tipo + '.jpg';
      const bytes = Uint8Array.from(atob(soloBase64(body[tipo])), c => c.charCodeAt(0));
      await env.ARCHIVOS.put(ruta, bytes, { httpMetadata: { contentType: ct } });
      out[tipo + 'Url'] = base ? (base + '/' + ruta) : ('/' + ruta);
      out[tipo + 'Ruta'] = ruta;
    }
    return j({ ok: true, projectId: pid, photoId: fid, ...out });
  } catch (e) { return j({ ok: false, error: e.message }, 500); }
}

// Lee un archivo de R2 (por su binding) y lo devuelve incrustado como dataURL.
// Sirve para meter las fotos en el PDF del informe (el conversor del Apps Script
// no baja imágenes externas; las dataURL sí se incrustan).
async function r2Inline(env, body) {
  if (!env.ARCHIVOS) return j({ ok: false, error: 'R2 no configurado (binding ARCHIVOS)' }, 400);
  if (segModo(env) === 'estricta' && !await segPinValido(env, body.pin)) return j({ ok: false, error: 'Leer la bóveda exige PIN' }, 403);   // v63
  let key = String(body.ruta || body.key || '').trim();
  if (!key && body.url) {
    let u = String(body.url).trim();
    const base = (env.R2_PUBLIC_URL || '').replace(/\/$/, '');
    if (base && u.startsWith(base)) u = u.slice(base.length);
    else u = u.replace(/^https?:\/\/[^/]+/, '').replace(/^\/archivo\//, '/');   // v59
    key = u;
  }
  key = key.replace(/^\/+/, '');
  if (!key) return j({ ok: false, error: 'sin ruta/url' }, 400);
  try {
    const obj = await env.ARCHIVOS.get(key);
    if (!obj) return j({ ok: false, error: 'no encontrado: ' + key }, 404);
    const buf = new Uint8Array(await obj.arrayBuffer());
    let bin = ''; const CH = 0x8000;
    for (let i = 0; i < buf.length; i += CH) bin += String.fromCharCode.apply(null, buf.subarray(i, i + CH));
    const ct = (obj.httpMetadata && obj.httpMetadata.contentType) || 'image/jpeg';
    return j({ ok: true, dataUrl: 'data:' + ct + ';base64,' + btoa(bin), ruta: key });
  } catch (e) { return j({ ok: false, error: e.message }, 500); }
}

