async function finBancoBorrar(env, body) {
  await finEnsure(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'admin')) return j({ ok:false, error:'Exige nivel admin' }, 403);
  const usado = await env.DB.prepare(`SELECT COUNT(*) AS n FROM fin_movimientos WHERE banco_id=? OR banco_destino_id=?`)
    .bind(body.id, body.id).first();
  if (usado && usado.n > 0) { await env.DB.prepare(`UPDATE fin_bancos SET activo=0 WHERE id=?`).bind(body.id).run(); return j({ ok:true, desactivado:true }); }
  await env.DB.prepare(`DELETE FROM fin_bancos WHERE id=?`).bind(body.id).run();
  return j({ ok:true });
}
