async function finCuentaGuardar(env, body) {
  await finEnsure(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'admin')) return j({ ok:false, error:'Exige nivel admin' }, 403);
  const c = body.cuenta || {};
  if (!c.codigo || !c.nombre || !['activo','pasivo','patrimonio','ingreso','gasto'].includes(c.tipo))
    return j({ ok:false, error:'código, nombre y tipo válidos' });
  await env.DB.prepare(`INSERT INTO fin_cuentas (codigo,nombre,tipo) VALUES (?,?,?)
    ON CONFLICT(codigo) DO UPDATE SET nombre=excluded.nombre, tipo=excluded.tipo, activo=1`)
    .bind(c.codigo, c.nombre, c.tipo).run();
  return j({ ok:true });
}
async function finAsientoGuardar(env, body) {
  await finEnsure(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'admin')) return j({ ok:false, error:'Los asientos manuales exigen nivel admin' }, 403);
  const a = body.asiento || {};
  const L = Array.isArray(a.lineas) ? a.lineas.filter(l => l.cuenta_codigo && (Number(l.debe)>0 || Number(l.haber)>0)) : [];
  if (!a.fecha || L.length < 2) return j({ ok:false, error:'fecha y al menos 2 líneas' });
  const debe = finR2(L.reduce((s,l)=>s+(Number(l.debe)||0),0));
  const haber = finR2(L.reduce((s,l)=>s+(Number(l.haber)||0),0));
  if (Math.abs(debe - haber) > 0.01) return j({ ok:false, error:`asiento descuadrado: debe ₡${debe} ≠ haber ₡${haber}` });
  const autor = await finQuienEs(env, body.pin) || String(body.pin||'');
  const id = await finAsientoNuevo(env, a.fecha, a.descripcion||'Asiento manual', 'manual', autor, L);
  return j({ ok:true, id });
}
async function finAsientoBorrarAccion(env, body) {
  await finEnsure(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'admin')) return j({ ok:false, error:'Exige nivel admin' }, 403);
  const a = await env.DB.prepare(`SELECT origen FROM fin_asientos WHERE id=?`).bind(body.id).first();
  if (!a) return j({ ok:false, error:'no existe' });
  if (a.origen !== 'manual') return j({ ok:false, error:'los asientos automáticos se borran eliminando su movimiento' });
  await finAsientoBorrar(env, body.id);
  return j({ ok:true });
}
async function finDiario(env, body) {
  await finEnsure(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  const desde = body.desde || '0000', hasta = body.hasta || '9999';
  const A = (await env.DB.prepare(`SELECT * FROM fin_asientos WHERE fecha>=? AND fecha<=? ORDER BY fecha,numero`)
    .bind(desde, hasta).all()).results || [];
  const ids = A.map(a=>a.id);
  let lineas = [];
  if (ids.length) {
    const q = `SELECT l.*, c.nombre AS cuenta FROM fin_asiento_lineas l LEFT JOIN fin_cuentas c ON c.codigo=l.cuenta_codigo
      WHERE l.asiento_id IN (${ids.map(()=>'?').join(',')}) ORDER BY l.id`;
    lineas = (await env.DB.prepare(q).bind(...ids).all()).results || [];
  }
  const porA = {}; lineas.forEach(l => { (porA[l.asiento_id] = porA[l.asiento_id] || []).push(l); });
  return j({ ok:true, asientos: A.map(a => ({ ...a, lineas: porA[a.id] || [] })) });
}
async function finMayor(env, body) {
  await finEnsure(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  if (!body.cuenta) return j({ ok:false, error:'cuenta requerida' });
  const desde = body.desde || '0000', hasta = body.hasta || '9999';
  const ini = await env.DB.prepare(`SELECT COALESCE(SUM(l.debe),0) AS d, COALESCE(SUM(l.haber),0) AS h
    FROM fin_asiento_lineas l JOIN fin_asientos a ON a.id=l.asiento_id
    WHERE l.cuenta_codigo=? AND a.fecha < ?`).bind(body.cuenta, desde).first();
  const rows = (await env.DB.prepare(`SELECT a.fecha, a.numero, a.descripcion, l.detalle, l.debe, l.haber
    FROM fin_asiento_lineas l JOIN fin_asientos a ON a.id=l.asiento_id
    WHERE l.cuenta_codigo=? AND a.fecha>=? AND a.fecha<=? ORDER BY a.fecha, a.numero, l.id`)
    .bind(body.cuenta, desde, hasta).all()).results || [];
  let saldo = finR2(ini.d - ini.h);
  const saldoInicial = saldo;
  const lineas = rows.map(r => { saldo = finR2(saldo + r.debe - r.haber); return { ...r, saldo }; });
  return j({ ok:true, saldoInicial, lineas, saldoFinal: saldo });
}
async function finBalance(env, body) {
  await finEnsure(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  const hasta = body.hasta || '9999';
  const rows = (await env.DB.prepare(`SELECT l.cuenta_codigo AS codigo, c.nombre, c.tipo,
    COALESCE(SUM(l.debe),0) AS debe, COALESCE(SUM(l.haber),0) AS haber
    FROM fin_asiento_lineas l JOIN fin_asientos a ON a.id=l.asiento_id
    LEFT JOIN fin_cuentas c ON c.codigo=l.cuenta_codigo
    WHERE a.fecha <= ? GROUP BY l.cuenta_codigo ORDER BY l.cuenta_codigo`).bind(hasta).all()).results || [];
  const cuentas = rows.map(r => {
    const s = finR2(r.debe - r.haber);
    return { ...r, debe: finR2(r.debe), haber: finR2(r.haber),
      saldoDeudor: s > 0 ? s : 0, saldoAcreedor: s < 0 ? -s : 0 };
  });
  const tot = cuentas.reduce((t,c)=>({ debe:t.debe+c.debe, haber:t.haber+c.haber,
    sd:t.sd+c.saldoDeudor, sa:t.sa+c.saldoAcreedor }), {debe:0,haber:0,sd:0,sa:0});
  return j({ ok:true, cuentas, totales: { debe:finR2(tot.debe), haber:finR2(tot.haber),
    saldoDeudor:finR2(tot.sd), saldoAcreedor:finR2(tot.sa),
    cuadra: Math.abs(tot.debe-tot.haber) <= 0.01 } });
}
async function finResultados(env, body) {
  await finEnsure(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  const desde = body.desde || '0000', hasta = body.hasta || '9999';
  const rows = (await env.DB.prepare(`SELECT c.codigo, c.nombre, c.tipo,
    COALESCE(SUM(l.debe),0) AS debe, COALESCE(SUM(l.haber),0) AS haber
    FROM fin_asiento_lineas l JOIN fin_asientos a ON a.id=l.asiento_id
    JOIN fin_cuentas c ON c.codigo=l.cuenta_codigo
    WHERE a.fecha>=? AND a.fecha<=? AND c.tipo IN ('ingreso','gasto')
    GROUP BY c.codigo ORDER BY c.codigo`).bind(desde, hasta).all()).results || [];
  const ingresos = rows.filter(r=>r.tipo==='ingreso').map(r=>({ ...r, total: finR2(r.haber - r.debe) }));
  const gastos = rows.filter(r=>r.tipo==='gasto').map(r=>({ ...r, total: finR2(r.debe - r.haber) }));
  const ti = finR2(ingresos.reduce((s,r)=>s+r.total,0)), tg = finR2(gastos.reduce((s,r)=>s+r.total,0));
  return j({ ok:true, ingresos, gastos, totalIngresos: ti, totalGastos: tg, utilidad: finR2(ti - tg) });
}



// ---- CENTROS DE COSTOS + CUENTAS POR COBRAR / PAGAR (Financiero F2) ----
async function finEnsure2(env) {
  if (_yaListo.finEnsure2) return; _yaListo.finEnsure2 = true;   // v120 ⚡ una vez por instancia
  await finEnsure(env);
  if (finEnsure2.done) return;
  await env.DB.batch([
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS fin_centros (
      id INTEGER PRIMARY KEY AUTOINCREMENT, codigo TEXT UNIQUE, nombre TEXT NOT NULL,
      cliente TEXT DEFAULT '', crm_op_id INTEGER, estado TEXT DEFAULT 'abierto', creado_en TEXT DEFAULT '')`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS fin_cxc (
      id INTEGER PRIMARY KEY AUTOINCREMENT, centro_id INTEGER, cliente TEXT DEFAULT '',
      detalle TEXT DEFAULT '', fecha TEXT DEFAULT '', monto REAL DEFAULT 0, moneda TEXT DEFAULT 'CRC',
      tipo_cambio REAL DEFAULT 1, iva REAL DEFAULT 0, saldo REAL DEFAULT 0, estado TEXT DEFAULT 'pendiente',
      asiento_id INTEGER, creado_por TEXT DEFAULT '', creado_en TEXT DEFAULT '')`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS fin_cxp (
      id INTEGER PRIMARY KEY AUTOINCREMENT, centro_id INTEGER, proveedor TEXT DEFAULT '',
      detalle TEXT DEFAULT '', fecha TEXT DEFAULT '', monto REAL DEFAULT 0, moneda TEXT DEFAULT 'CRC',
      tipo_cambio REAL DEFAULT 1, iva REAL DEFAULT 0, cuenta_gasto TEXT DEFAULT '5-06',
      saldo REAL DEFAULT 0, estado TEXT DEFAULT 'pendiente',
      asiento_id INTEGER, creado_por TEXT DEFAULT '', creado_en TEXT DEFAULT '')`)
  ]);
  // v116 — TABLA DE GASTOS OPERATIVOS (planilla, viáticos, servicios, etc.)
  // Reemplaza el paso a mano en el reporte financiero.
  try { await env.DB.prepare(`CREATE TABLE IF NOT EXISTS fin_gastos (
    id INTEGER PRIMARY KEY AUTOINCREMENT, categoria TEXT NOT NULL, grupo TEXT DEFAULT 'otros',
    monto REAL NOT NULL, moneda TEXT DEFAULT 'CRC', empresa TEXT DEFAULT '', periodo TEXT DEFAULT '',
    estado TEXT DEFAULT 'pendiente', vence TEXT DEFAULT '', nota TEXT DEFAULT '',
    creado_por TEXT DEFAULT '', creado_en TEXT DEFAULT '')`).run(); } catch (e) {}
  try { await env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_gastos_periodo ON fin_gastos(periodo,empresa)').run(); } catch (e) {}
  // v117 — DEUDA CON EL DIRECTOR (préstamos del socio a la empresa)
  try { await env.DB.prepare(`CREATE TABLE IF NOT EXISTS fin_director (
    id INTEGER PRIMARY KEY AUTOINCREMENT, concepto TEXT NOT NULL, tipo TEXT DEFAULT 'prestamo',
    monto REAL NOT NULL, moneda TEXT DEFAULT 'CRC', empresa TEXT DEFAULT '', fecha TEXT DEFAULT '',
    estado TEXT DEFAULT 'pendiente', nota TEXT DEFAULT '', creado_por TEXT DEFAULT '', creado_en TEXT DEFAULT '')`).run(); } catch (e) {}
  // v117 — RETENCIONES A FAVOR (2% renta, IVA retenido que Hacienda debe devolver)
  try { await env.DB.prepare(`CREATE TABLE IF NOT EXISTS fin_retenciones (
    id INTEGER PRIMARY KEY AUTOINCREMENT, concepto TEXT NOT NULL, tipo TEXT DEFAULT 'renta',
    monto REAL NOT NULL, moneda TEXT DEFAULT 'CRC', empresa TEXT DEFAULT '', periodo TEXT DEFAULT '',
    estado TEXT DEFAULT 'por_aplicar', nota TEXT DEFAULT '', creado_por TEXT DEFAULT '', creado_en TEXT DEFAULT '')`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE fin_movimientos ADD COLUMN centro_id INTEGER`).run(); } catch (e) {}
  // v18: campos para recordatorios de cobro (migración suave: si ya existen, no pasa nada)
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN vence TEXT DEFAULT ''`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN correo TEXT DEFAULT ''`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN empresa TEXT DEFAULT ''`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN ultimo_aviso TEXT DEFAULT ''`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN avisos INTEGER DEFAULT 0`).run(); } catch (e) {}
  // ── v98: facturación por avances y anticipos ──
  // tipo: 'factura' (lleva IVA y número fiscal) | 'anticipo' (plata recibida
  // por adelantado, sin factura → es PASIVO, su IVA se cobra al facturar).
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN tipo TEXT DEFAULT 'factura'`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN factura_num TEXT DEFAULT ''`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN pago_id INTEGER`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN origen TEXT DEFAULT ''`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN comprobante TEXT DEFAULT ''`).run(); } catch (e) {}
  // ── v102: lo que exige la factura electrónica de Hacienda ──
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN cabys TEXT DEFAULT ''`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN clave TEXT DEFAULT ''`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE fin_cxc ADD COLUMN iva_tarifa REAL`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE razones_sociales ADD COLUMN actividad_economica TEXT DEFAULT ''`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE razones_sociales ADD COLUMN actividades TEXT DEFAULT ''`).run(); } catch (e) {}
  try { await env.DB.prepare(`CREATE TABLE IF NOT EXISTS fe_cabys (
    codigo TEXT PRIMARY KEY, descripcion TEXT, impuesto REAL,
    origen TEXT, usos INTEGER DEFAULT 0, actualizado_en TEXT )`).run(); } catch (e) {}
  try { await env.DB.prepare(`CREATE TABLE IF NOT EXISTS fe_cabys_default (
    empresa TEXT NOT NULL, servicio TEXT NOT NULL DEFAULT '', codigo TEXT NOT NULL,
    actualizado_en TEXT, PRIMARY KEY (empresa, servicio) )`).run(); } catch (e) {}
  // Consecutivo de Hacienda: uno por empresa y tipo de documento. Atómico.
  try { await env.DB.prepare(`CREATE TABLE IF NOT EXISTS fe_consecutivos (
    empresa TEXT NOT NULL, tipo_doc TEXT NOT NULL, sucursal TEXT DEFAULT '001',
    terminal TEXT DEFAULT '00001', ultimo INTEGER DEFAULT 0,
    PRIMARY KEY (empresa, tipo_doc) )`).run(); } catch (e) {}
  // v98: cuenta de PASIVO para los anticipos. NO se hardcodea el código —
  // el 2-04 ya estaba ocupado por 'CCSS por pagar' en producción y el
  // INSERT OR IGNORE se lo tragó callado. cuentaAnticipos() busca uno libre.
  try { await cuentaAnticipos(env); } catch (e) {}
  // v98: las cédulas jurídicas venían vacías; INSERT OR IGNORE no las repara.
  try { await env.DB.prepare(`UPDATE razones_sociales SET cedula_juridica='3-101-851590'
    WHERE codigo='IIMC S.A.' AND COALESCE(cedula_juridica,'')=''`).run(); } catch (e) {}
  try { await env.DB.prepare(`UPDATE razones_sociales SET cedula_juridica='3-101-691218'
    WHERE codigo='MARC S.A.' AND COALESCE(cedula_juridica,'')=''`).run(); } catch (e) {}
  // v71: comprobante adjunto (clave en R2) — migración suave
  try { await env.DB.prepare(`ALTER TABLE fin_movimientos ADD COLUMN comprobante TEXT DEFAULT ''`).run(); } catch (e) {}
  finEnsure2.done = true;
}
const finHoy = () => crParts().iso.slice(0, 10);

async function finCentrosListar(env, body) {
  await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  const centros = (await env.DB.prepare(`SELECT * FROM fin_centros ORDER BY id DESC`).all()).results || [];
  const out = [];
  for (const c of centros) {
    const g = await env.DB.prepare(`SELECT
      COALESCE(SUM(CASE WHEN tipo='ingreso' THEN (monto+iva)*(CASE WHEN moneda='USD' THEN tipo_cambio ELSE 1 END) END),0) AS ing,
      COALESCE(SUM(CASE WHEN tipo='gasto'   THEN (monto+iva)*(CASE WHEN moneda='USD' THEN tipo_cambio ELSE 1 END) END),0) AS gas
      FROM fin_movimientos WHERE centro_id=?`).bind(c.id).first();
    const x = await env.DB.prepare(`SELECT COALESCE(SUM(saldo*(CASE WHEN moneda='USD' THEN tipo_cambio ELSE 1 END)),0) AS s
      FROM fin_cxc WHERE centro_id=? AND estado='pendiente'`).bind(c.id).first();
    out.push({ ...c, ingresos: finR2(g.ing), gastos: finR2(g.gas),
      resultado: finR2(g.ing - g.gas), porCobrar: finR2(x.s) });
  }
  return j({ ok:true, centros: out });
}
async function finCentroGuardar(env, body) {
  await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'admin')) return j({ ok:false, error:'Exige nivel admin' }, 403);
  const c = body.centro || {};
  if (c.id && c.estado) { // cerrar/reabrir
    await env.DB.prepare(`UPDATE fin_centros SET estado=? WHERE id=?`).bind(c.estado, c.id).run();
    return j({ ok:true });
  }
  if (!c.nombre) return j({ ok:false, error:'nombre requerido' });
  // Serie unificada del grupo: CC-2026-XXXX (el próximo proyecto es CC-2026-0146)
  const codigo = await ccSiguienteCodigo(env);
  await env.DB.prepare(`INSERT INTO fin_centros (codigo,nombre,cliente,estado,creado_en) VALUES (?,?,?, 'abierto', datetime('now'))`)
    .bind(codigo, c.nombre, c.cliente||'').run();
  // Registro enriquecido automático: sub-centros según la razón social
  try { await ccRegistrarRico(env, codigo, c.nombre, body.razon_social || marcaARazon(c.empresa) || 'IIMC S.A.', c.empresa, c.cliente, 'financiero:manual'); } catch (e) {}
  return j({ ok:true, codigo });
}
async function finCxcListar(env, body) {
  await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  let sql = `SELECT x.*, ce.codigo AS centro FROM fin_cxc x LEFT JOIN fin_centros ce ON ce.id=x.centro_id WHERE 1=1`;
  const args = [];
  if (body.estado) { sql += ` AND x.estado=?`; args.push(body.estado); }
  if (body.centro_id) { sql += ` AND x.centro_id=?`; args.push(body.centro_id); }
  sql += ` ORDER BY x.id DESC LIMIT 300`;
  return j({ ok:true, cxc: (await env.DB.prepare(sql).bind(...args).all()).results || [] });
}
// ═══════════════════════════════════════════════════════════
//  v98 — 🩻 RADIOGRAFÍA: qué hay DE VERDAD en la base hoy.
//  Solo lee. No cambia un solo dato. Sirve para decidir con números en vez
//  de con supuestos antes de rediseñar la facturación.
// ═══════════════════════════════════════════════════════════

// Los ids de las CxC que creó el módulo de alquileres. Son SAGRADAS: tienen
// el histórico real que sembró la v93. Se reconocen porque alq_registros
// guarda el id de su CxC (y desde la v98 también por fin_cxc.origen).
async function finCxcDeAlquileres(env) {
  const ids = new Set();
  try {
    const r = await env.DB.prepare(`SELECT cxc_id FROM alq_registros WHERE cxc_id IS NOT NULL`).all();
    for (const x of (r.results || [])) if (Number(x.cxc_id)) ids.add(Number(x.cxc_id));
  } catch (e) {}
  try {
    const r = await env.DB.prepare(`SELECT id FROM fin_cxc WHERE origen='alquileres'`).all();
    for (const x of (r.results || [])) if (Number(x.id)) ids.add(Number(x.id));
  } catch (e) {}
  return ids;
}

// ══ v98 — Tipo de cambio del grupo: verlo y ponerlo ══
// Fuente oficial: Banco Central de Costa Rica (tipo de cambio de VENTA).
async function finTipoCambio(env, body) {
  await finEnsure2(env);
  const leer = async () => {
    const g = await tcGrupo(env);
    const anticipos = await cuentaAnticipos(env);
    const alq = await tcDeAlquileres(env);
    let aviso = '';
    if (!g) aviso = '⚠️ Sin tipo de cambio aprobado, facturar en dólares va a FALLAR a propósito.';
    else if (g.dias != null && g.dias > TC_DIAS_AVISO)
      aviso = '⚠️ El tipo de cambio tiene ' + g.dias + ' días. Actualizalo con el del BCCR de hoy.';
    return j({ ok: true, tipo_cambio: g ? g.tc : null, fecha: g ? g.fecha : '',
      fuente: g ? g.fuente : 'NO HAY', dias_de_antiguedad: g ? g.dias : null,
      cuenta_anticipos: anticipos,
      tipo_cambio_de_alquileres: alq,
      alquileres_desalineado: (g && alq && Math.abs(alq - g.tc) / g.tc > 0.05)
        ? '⚠️ Alquileres factura a ' + alq + ' y el grupo a ' + g.tc + ' — revisá cuál es el bueno.' : '',
      aviso });
  };
  if (body.venta === undefined && body.tipo_cambio === undefined) return await leer();
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'admin'))
    return j({ ok: false, error: 'Cambiar el tipo de cambio exige nivel admin de Financiero' }, 403);
  const venta = Number(body.venta !== undefined ? body.venta : body.tipo_cambio);
  if (!tcValido(venta)) return j({ ok: false, error:
    'El tipo de cambio debe estar entre ' + TC_MIN + ' y ' + TC_MAX + ' colones por dólar. Recibí: ' + venta });
  const valor = JSON.stringify({ venta, fecha: body.fecha || finHoy(),
    fuente: body.fuente || 'Banco Central de Costa Rica',
    puesto_por: await finQuienEs(env, body.pin) || String(body.pin || '') });
  await env.DB.prepare(`INSERT INTO config (clave,valor,descripcion,actualizado_en)
    VALUES ('tipo_cambio',?, 'Tipo de cambio del grupo (BCCR, venta)', ?)
    ON CONFLICT(clave) DO UPDATE SET valor=excluded.valor, actualizado_en=excluded.actualizado_en`)
    .bind(valor, crParts().iso).run();
  return await leer();
}

// ══ v98 — 🔧 REPARAR las CxC que nacieron con tipo de cambio 1 ══
// Arregla la CxC Y su asiento contable (si solo se arregla la CxC, el libro
// queda mintiendo). SIMULA por defecto: exige confirmar:'REPARAR'.
async function finRepararTipoCambio(env, body) {
  await finEnsure(env); await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'admin'))
    return j({ ok: false, error: 'Exige nivel admin de Financiero' }, 403);
  let tc = Number(body.tipo_cambio) || 0;
  if (!tcValido(tc)) {
    const g = await tcGrupo(env);
    if (!g) return j({ ok: false, error: 'Poné primero el tipo de cambio del grupo (acción fin_tipo_cambio).' });
    tc = g.tc;
  }
  const alq = await finCxcDeAlquileres(env);
  let rotas = [];
  try {
    rotas = (await env.DB.prepare(`SELECT id,cliente,detalle,fecha,monto,iva,saldo,moneda,tipo_cambio,asiento_id,empresa
      FROM fin_cxc WHERE moneda='USD' AND COALESCE(tipo_cambio,1)=1
      AND COALESCE(estado,'') <> 'anulada' ORDER BY id`).all()).results || [];
  } catch (e) { return j({ ok: false, error: e.message }, 500); }
  rotas = rotas.filter(x => !alq.has(Number(x.id)));
  const ids = Array.isArray(body.ids) && body.ids.length ? body.ids.map(Number) : null;
  if (ids) rotas = rotas.filter(x => ids.includes(Number(x.id)));

  const plan = rotas.map(x => ({ id: x.id, cliente: x.cliente, detalle: x.detalle,
    monto_usd: x.monto, colones_hoy: finR2(Number(x.monto) || 0),
    colones_reparado: finR2((Number(x.monto) || 0) * tc), asiento_id: x.asiento_id }));

  if (String(body.confirmar || '') !== 'REPARAR') {
    return j({ ok: true, simulacion: true, tipo_cambio: tc,
      mensaje: 'SIMULACIÓN — no se cambió nada. Para reparar de verdad mandá confirmar:"REPARAR".',
      se_repararian: plan.length, plan });
  }
  let n = 0, lineas = 0;
  for (const x of rotas) {
    try {
      await env.DB.prepare(`UPDATE fin_cxc SET tipo_cambio=? WHERE id=?`).bind(tc, x.id).run();
      if (x.asiento_id) {
        // el asiento se armó con monto*1: se re-escala al tipo de cambio real
        const ls = (await env.DB.prepare(`SELECT id,debe,haber FROM fin_asiento_lineas WHERE asiento_id=?`)
          .bind(x.asiento_id).all()).results || [];
        for (const l of ls) {
          await env.DB.prepare(`UPDATE fin_asiento_lineas SET debe=?, haber=? WHERE id=?`)
            .bind(finR2((Number(l.debe) || 0) * tc), finR2((Number(l.haber) || 0) * tc), l.id).run();
          lineas++;
        }
      }
      n++;
    } catch (e) {}
  }
  return j({ ok: true, simulacion: false, tipo_cambio: tc, reparadas: n, lineas_de_asiento: lineas });
}

async function finRadiografia(env, body) {
  await finEnsure(env); await finEnsure2(env); await ccEnsure(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'admin'))
    return j({ ok: false, error: 'Exige nivel admin de Financiero' }, 403);
  const uno = async (sql, ...bind) => {
    try { return await env.DB.prepare(sql).bind(...bind).first(); } catch (e) { return { error: e.message }; }
  };
  const todos = async (sql, ...bind) => {
    try { return (await env.DB.prepare(sql).bind(...bind).all()).results || []; } catch (e) { return []; }
  };
  const alq = await finCxcDeAlquileres(env);

  // ── Cuentas por cobrar ──
  const cxc = await todos(`SELECT id,cliente,detalle,fecha,vence,monto,iva,saldo,moneda,tipo_cambio,
    estado,empresa,correo,centro_id,asiento_id FROM fin_cxc ORDER BY id`);
  const porOrigen = { alquileres: [], crm_o_manual: [] };
  for (const x of cxc) (alq.has(Number(x.id)) ? porOrigen.alquileres : porOrigen.crm_o_manual).push(x);
  const suma = (arr, f) => finR2(arr.reduce((s, x) => s + (Number(f(x)) || 0), 0));

  // ── Síntomas del bug de moneda ──
  const sospechosas = porOrigen.crm_o_manual.filter(x =>
    x.moneda === 'USD' && (Number(x.tipo_cambio) || 1) === 1);
  const naceVencida = porOrigen.crm_o_manual.filter(x => x.vence && x.fecha && x.vence <= x.fecha);
  const sinCorreo = porOrigen.crm_o_manual.filter(x => !String(x.correo || '').trim());

  // ── Cotizaciones ──
  const cot = await uno(`SELECT COUNT(*) AS n,
    SUM(CASE WHEN cc_codigo IS NOT NULL AND cc_codigo<>'' THEN 1 ELSE 0 END) AS ganadas,
    SUM(CASE WHEN COALESCE(anulada,0)=1 THEN 1 ELSE 0 END) AS anuladas
    FROM crm_cotizaciones`);
  // Firmadas que NUNCA se ganaron (el bug de la v94: firmaban al vacío)
  const huerfanas = await todos(`SELECT f.consecutivo, f.cliente, f.firmante, f.firmado_en, c.estatus, c.empresa
    FROM crm_firmas f LEFT JOIN crm_cotizaciones c ON c.consecutivo=f.consecutivo
    WHERE f.estado='firmada' AND (c.cc_codigo IS NULL OR c.cc_codigo='')
    ORDER BY f.firmado_en DESC LIMIT 40`);

  // ── Hitos de pago ──
  const hitos = await uno(`SELECT COUNT(*) AS n,
    SUM(CASE WHEN estado='aprobado' THEN 1 ELSE 0 END) AS aprobados,
    SUM(CASE WHEN origen LIKE 'auto:%' AND porcentaje=100 THEN 1 ELSE 0 END) AS auto_100
    FROM cc_pagos`);
  // Proyectos que siguen con el hito único al 100% que puso el sistema solo
  const soloAuto = await todos(`SELECT cc_codigo, COUNT(*) AS n,
    SUM(CASE WHEN origen LIKE 'auto:%' THEN 1 ELSE 0 END) AS autos
    FROM cc_pagos GROUP BY cc_codigo HAVING n=1 AND autos=1 LIMIT 40`);

  // ── Centros y catálogo ──
  const centros = await uno(`SELECT COUNT(*) AS n FROM fin_centros`);
  const ccc = await uno(`SELECT COUNT(*) AS n FROM cc_centros`);
  const anticipos = await cuentaAnticipos(env);
  const ctaAnt = anticipos ? await uno(`SELECT codigo,nombre,tipo FROM fin_cuentas WHERE codigo=?`, anticipos) : null;
  const razones = await todos(`SELECT codigo,nombre,cedula_juridica FROM razones_sociales`);
  const g = await tcGrupo(env);
  const pasivos = await todos(`SELECT codigo,nombre FROM fin_cuentas WHERE tipo='pasivo' ORDER BY codigo`);

  return j({ ok: true, version: MARC_VERSION, fecha: crParts().iso,
    cuentas_por_cobrar: {
      total: cxc.length,
      de_alquileres: { n: porOrigen.alquileres.length,
        saldo: suma(porOrigen.alquileres, x => x.saldo), nota: 'NO SE TOCAN: histórico real' },
      de_crm_o_manual: { n: porOrigen.crm_o_manual.length,
        saldo: suma(porOrigen.crm_o_manual, x => x.saldo),
        nota: 'candidatas a limpieza' },
      sintomas_del_bug: {
        en_dolares_con_tc_1: sospechosas.length,
        nacieron_vencidas: naceVencida.length,
        sin_correo_de_cobro: sinCorreo.length
      },
      detalle_crm_o_manual: porOrigen.crm_o_manual.slice(0, 40)
    },
    cotizaciones: cot,
    firmadas_sin_ganar: { n: huerfanas.length, lista: huerfanas },
    hitos_de_pago: { ...hitos, proyectos_con_hito_unico_automatico: soloAuto },
    centros: { fin_centros: centros && centros.n, cc_centros: ccc && ccc.n },
    tipo_cambio_del_grupo: g
      ? { valor: g.tc, fecha: g.fecha, fuente: g.fuente, dias_de_antiguedad: g.dias,
          aviso: (g.dias != null && g.dias > TC_DIAS_AVISO) ? '⚠️ tiene ' + g.dias + ' días' : '' }
      : { valor: null, aviso: '⚠️ NO HAY tipo de cambio aprobado. Facturar en dólares falla a propósito hasta que se ponga.' },
    tipo_cambio_de_alquileres: await tcDeAlquileres(env),
    listo_para_hacienda: {
      cabys_en_catalogo: (await uno(`SELECT COUNT(*) AS n FROM fe_cabys`) || {}).n || 0,
      cabys_por_empresa: await todos(`SELECT d.empresa, d.servicio, d.codigo, c.descripcion, c.impuesto
        FROM fe_cabys_default d LEFT JOIN fe_cabys c ON c.codigo=d.codigo`),
      empresas_sin_cabys: await todos(`SELECT codigo, nombre FROM empresas
        WHERE activo=1 AND codigo NOT IN (SELECT empresa FROM fe_cabys_default)`),
      consecutivos: await todos(`SELECT empresa, tipo_doc, sucursal, terminal, ultimo FROM fe_consecutivos`),
      actividades_economicas: await todos(`SELECT codigo, cedula_juridica, actividad_economica
        FROM razones_sociales`),
      facturas_con_clave: (await uno(`SELECT COUNT(*) AS n FROM fin_cxc WHERE COALESCE(clave,'')<>''`) || {}).n || 0,
      falta: []
    },
    catalogo: { cuenta_de_anticipos: ctaAnt || 'NO SE PUDO CREAR',
      cuentas_de_pasivo: pasivos, razones_sociales: razones }
  });
}

// ══ v98 — 🧹 LIMPIEZA de las CxC de prueba ══
// SIMULA por defecto. Para borrar de verdad hay que mandar confirmar:'BORRAR'.
// Nunca toca las de alquileres. Borra también el asiento de cada CxC: dejarlo
// huérfano descuadraría el balance para siempre.
async function finCxcLimpiar(env, body) {
  await finEnsure(env); await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'admin'))
    return j({ ok: false, error: 'Exige nivel admin de Financiero' }, 403);
  const alq = await finCxcDeAlquileres(env);
  let cxc = [];
  try { cxc = (await env.DB.prepare(`SELECT id,cliente,detalle,fecha,monto,iva,saldo,moneda,estado,asiento_id,empresa
    FROM fin_cxc ORDER BY id`).all()).results || []; } catch (e) { return j({ ok: false, error: e.message }, 500); }

  const ids = Array.isArray(body.ids) && body.ids.length ? body.ids.map(Number) : null;
  const victimas = cxc.filter(x => !alq.has(Number(x.id)) && (!ids || ids.includes(Number(x.id))));
  const protegidas = cxc.length - victimas.length;
  const total = finR2(victimas.reduce((s, x) => s + (Number(x.monto) || 0) + (Number(x.iva) || 0), 0));

  if (String(body.confirmar || '') !== 'BORRAR') {
    return j({ ok: true, simulacion: true,
      mensaje: 'SIMULACIÓN — no se borró nada. Para borrar de verdad mandá confirmar:"BORRAR".',
      se_borrarian: victimas.length, protegidas_de_alquileres: protegidas,
      monto_total: total, con_asiento: victimas.filter(x => x.asiento_id).length,
      detalle: victimas });
  }

  let borradas = 0, asientos = 0;
  for (const v of victimas) {
    try {
      if (v.asiento_id) { await finAsientoBorrar(env, v.asiento_id); asientos++; }
      await env.DB.prepare(`DELETE FROM fin_cxc WHERE id=?`).bind(v.id).run();
      borradas++;
      // soltar las referencias que quedarían apuntando al vacío
      try { await env.DB.prepare(`UPDATE crm_oportunidades SET cxc_id=NULL WHERE cxc_id=?`).bind(v.id).run(); } catch (e) {}
    } catch (e) {}
  }
  return j({ ok: true, simulacion: false, borradas, asientos_borrados: asientos,
    protegidas_de_alquileres: protegidas, monto_total: total });
}

async function finCxcCrear(env, body) {
  await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  const x = body.cxc || {};
  if (!x.cliente || !(Number(x.monto) > 0)) return j({ ok:false, error:'cliente y monto (>0)' });
  const fx = x.moneda === 'USD' ? (Number(x.tipo_cambio) || 1) : 1;
  const sub = finR2(Number(x.monto) * fx), iva = finR2(Number(x.iva || 0) * fx);
  const autor = await finQuienEs(env, body.pin) || String(body.pin || '');
  const L = [{ cuenta_codigo:'1-02', detalle: x.detalle || x.cliente, debe: finR2(sub + iva), haber: 0 },
             { cuenta_codigo:'4-01', detalle: x.detalle || x.cliente, debe: 0, haber: sub }];
  if (iva > 0) L.push({ cuenta_codigo:'2-02', detalle:'IVA 13%', debe:0, haber: iva });
  const asientoId = await finAsientoNuevo(env, x.fecha || finHoy(),
    'Factura por cobrar: ' + (x.detalle || x.cliente), 'cxc', autor, L);
  // v18: vencimiento (contado por defecto = misma fecha; editable con vence o plazo_dias)
  const fecha = x.fecha || finHoy();
  const vence = x.vence || finSumaDias(fecha, Number(x.plazo_dias) || 0);
  // correo: el que venga escrito, o el del cliente en el CRM (mismo nombre)
  let correo = String(x.correo || '').trim();
  if (!correo) correo = await finCorreoDeCliente(env, x.cliente);
  await env.DB.prepare(`INSERT INTO fin_cxc
    (centro_id,cliente,detalle,fecha,monto,moneda,tipo_cambio,iva,saldo,estado,asiento_id,creado_por,creado_en,vence,correo,empresa)
    VALUES (?,?,?,?,?,?,?,?,?, 'pendiente', ?, ?, datetime('now'), ?, ?, ?)`)
    .bind(x.centro_id||null, x.cliente, x.detalle||'', fecha, Number(x.monto), x.moneda||'CRC',
      Number(x.tipo_cambio)||1, Number(x.iva)||0, finR2(Number(x.monto)+Number(x.iva||0)), asientoId, autor,
      vence, correo, String(x.empresa||'').trim()).run();
  const n = await env.DB.prepare(`SELECT last_insert_rowid() AS id`).first();
  // v19.2 — espejo al Control de Costos si la CxC tiene centro
  if (x.centro_id) { try { await ccEspejo(env, Number(x.centro_id), { tipo:'ingreso', pista:'facturacion', origen:'cxc',
    descripcion:'Factura por cobrar: ' + (x.detalle || x.cliente), referencia:'CXC#' + (n && n.id),
    moneda: x.moneda || 'CRC', monto: Number(x.monto) || 0, fecha, usuario: autor }); } catch (e) {} }
  return j({ ok:true, id: n && n.id, vence, correo });
}
// v18: sumar días a una fecha ISO (YYYY-MM-DD) sin líos de zona horaria
// ══ v98 — EL TIPO DE CAMBIO DEL GRUPO ══
// MARC cotiza mayormente en DÓLARES: el default 'USD' siempre estuvo bien.
// El bug era `Number(body.tipo_cambio) || 1`: como nadie manda tipo de cambio,
// entraba 1 y un trabajo de $112.450 se contabilizaba como ₡112.450.
// Fuente oficial: Banco Central de Costa Rica. Se guarda en config
// 'tipo_cambio' y de ahí lo toma todo el grupo.
// Rango realista del colón. El 300–900 anterior dejaba pasar un 650 heredado
// que inflaba las facturas un 44%. En el último año el dólar se movió entre
// ₡450 y ₡497 (BCCR), así que 350–700 ya es holgado.
const TC_MIN = 350, TC_MAX = 700;
const TC_DIAS_AVISO = 7;   // más viejo que esto, se avisa
const tcValido = (n) => Number(n) >= TC_MIN && Number(n) <= TC_MAX;

// v100 — SOLO el tipo de cambio oficial del grupo. Antes esto caía a
// alq_config si no había uno puesto: en producción eso puso un 650 sin fecha
// a gobernar toda la facturación (el BCCR andaba en 453). Heredar un número
// de otro módulo sin que nadie lo apruebe es el mismo error silencioso que el
// viejo `|| 1`. Si no hay tipo de cambio aprobado, no hay conversión.
async function tcGrupo(env) {
  try {
    const r = await env.DB.prepare(`SELECT valor, actualizado_en FROM config WHERE clave='tipo_cambio'`).first();
    if (!r) return null;
    const o = JSON.parse(r.valor);
    if (!tcValido(o.venta)) return null;
    const fecha = o.fecha || String(r.actualizado_en || '').slice(0, 10);
    return { tc: Number(o.venta), fecha, fuente: o.fuente || 'config', dias: tcDiasDesde(fecha) };
  } catch (e) { return null; }
}
function tcDiasDesde(fecha) {
  const p = String(fecha || '').slice(0, 10).split('-');
  if (p.length < 3) return null;
  const d = Date.UTC(Number(p[0]), Number(p[1]) - 1, Number(p[2]));
  const h = new Date(crParts().fecha + 'T00:00:00Z').getTime();
  return Math.round((h - d) / 86400000);
}
// ══ v101 — Trae el tipo de cambio del BCCR vía la API pública de Hacienda ══
// No pide token ni suscripción. Devuelve { venta:{fecha,valor}, compra:{...} }.
const TC_API = 'https://api.hacienda.go.cr/indicadores/tc/dolar';
// v107 — Lee un interruptor booleano de la tabla config. Por defecto APAGADO.
async function cfgFlag(env, clave, porDefecto) {
  try {
    const r = await env.DB.prepare(`SELECT valor FROM config WHERE clave=?`).bind(clave).first();
    if (!r) return porDefecto;
    const v = String(r.valor).trim().toLowerCase().replace(/^"|"$/g, '');
    if (v === 'true' || v === '1' || v === 'on' || v === 'si') return true;
    if (v === 'false' || v === '0' || v === 'off' || v === 'no') return false;
    return porDefecto;
  } catch (e) { return porDefecto; }
}
// Prende o apaga los correos automáticos. Exige dueño/admin.
async function correosAutomaticos(env, body) {
  await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'admin'))
    return j({ ok: false, error: 'Exige nivel admin de Financiero' }, 403);
  if (body.encender === undefined) {
    const on = await cfgFlag(env, 'correos_automaticos', false);
    return j({ ok: true, correos_automaticos: on,
      estado: on ? '🟢 ENCENDIDOS' : '🔴 APAGADOS',
      nota: on ? 'El cron manda recordatorios de cobro y avisos de alquiler.'
               : 'Nadie recibe correos automáticos. El tipo de cambio sí se sigue actualizando.' });
  }
  const on = !!body.encender;
  await env.DB.prepare(`INSERT INTO config (clave,valor,descripcion,actualizado_en)
    VALUES ('correos_automaticos',?, 'Interruptor de correos automáticos (cobros y alquileres)', ?)
    ON CONFLICT(clave) DO UPDATE SET valor=excluded.valor, actualizado_en=excluded.actualizado_en`)
    .bind(on ? 'true' : 'false', crParts().iso).run();
  return j({ ok: true, correos_automaticos: on, estado: on ? '🟢 ENCENDIDOS' : '🔴 APAGADOS',
    nota: on ? 'Desde el próximo cron se vuelven a mandar recordatorios.'
             : 'Apagados. Nadie recibe correos automáticos hasta que se vuelvan a encender.' });
}

async function tcBccrTraer(env, opts) {
  const o = opts || {};
  let r;
  try {
    r = await fetch(TC_API, { headers: { 'accept': 'application/json' },
      cf: { cacheTtl: 900 } });   // Hacienda pide no repetir consultas: 15 min de caché
  } catch (e) { return { error: 'No pude contactar a Hacienda: ' + e.message }; }
  if (!r.ok) return { error: 'Hacienda respondió ' + r.status +
    (r.status === 429 ? ' (límite de consultas superado: hay que esperar)' : '') };
  let d;
  try { d = await r.json(); } catch (e) { return { error: 'Hacienda devolvió algo que no es JSON' }; }
  const venta = d && d.venta && Number(d.venta.valor);
  const fecha = d && d.venta ? String(d.venta.fecha || '').slice(0, 10) : '';
  if (!tcValido(venta)) return { error: 'Hacienda devolvió un tipo de cambio fuera de rango: ' + venta };
  if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(fecha)) return { error: 'Hacienda devolvió una fecha rara: ' + fecha };

  const previo = await tcGrupo(env);
  // Nunca pisar un dato nuevo con uno más viejo
  if (previo && previo.fecha && fecha < previo.fecha)
    return { sin_cambio: true, tc: previo.tc, fecha: previo.fecha,
      motivo: 'Hacienda trae el del ' + fecha + ' y ya teníamos el del ' + previo.fecha };
  if (previo && previo.tc === venta && previo.fecha === fecha)
    return { sin_cambio: true, tc: venta, fecha, motivo: 'ya estaba al día' };

  if (!o.solo_ver) {
    await env.DB.prepare(`INSERT INTO config (clave,valor,descripcion,actualizado_en)
      VALUES ('tipo_cambio',?, 'Tipo de cambio del grupo (BCCR vía Hacienda)', ?)
      ON CONFLICT(clave) DO UPDATE SET valor=excluded.valor, actualizado_en=excluded.actualizado_en`)
      .bind(JSON.stringify({ venta, compra: Number(d.compra && d.compra.valor) || null,
        fecha, fuente: 'BCCR (API de Hacienda)', puesto_por: 'automático' }), crParts().iso).run();
  }
  return { ok: true, tc: venta, compra: Number(d.compra && d.compra.valor) || null, fecha,
    antes: previo ? previo.tc : null, dias_del_dato: tcDiasDesde(fecha) };
}

// Lo que Alquileres tiene configurado — se REPORTA para poder compararlo,
// pero nunca gobierna la facturación.
async function tcDeAlquileres(env) {
  try {
    const r = await env.DB.prepare(`SELECT valor FROM config WHERE clave='alq_config'`).first();
    if (r) { const o = JSON.parse(r.valor); if (Number(o.tc)) return Number(o.tc); }
  } catch (e) {}
  return null;
}

// Devuelve { moneda, fx } o { error } si el tipo de cambio no es confiable.
// NUNCA inventa un 1: prefiere fallar y que alguien lo vea.
async function cotDivisa(env, body, cot) {
  const moneda = String((body && body.moneda) || (cot && cot.moneda) || 'USD').toUpperCase();
  if (moneda !== 'USD') return { moneda, fx: 1 };
  const propuesto = Number(body && body.tipo_cambio) || Number(cot && cot.tipo_cambio) || 0;
  if (tcValido(propuesto)) return { moneda, fx: propuesto };
  const g = await tcGrupo(env);
  if (g) return { moneda, fx: g.tc, tcFuente: g.fuente, tcFecha: g.fecha };
  return { error: 'No hay tipo de cambio del grupo aprobado. Ponelo con el valor de VENTA del ' +
    'Banco Central de hoy y volvé a intentar. (No se hereda el de otro módulo a propósito: ' +
    'un número sin aprobar gobernando la facturación es cómo se metió un 650 cuando el BCCR ' +
    'andaba en 453 — cada factura en dólares salía 44% inflada.)' };
}

// ══ v98 — LA CUENTA DE ANTICIPOS DE CLIENTES (pasivo) ══
// No se hardcodea el código: en producción el 2-04 ya estaba ocupado por
// 'CCSS por pagar' y el INSERT OR IGNORE se lo tragó en silencio. Se busca un
// código LIBRE de la serie 2-XX, se crea y se recuerda en config.
const CUENTA_ANTICIPOS_NOMBRE = 'Anticipos de clientes';
// v104 — Códigos que OTROS módulos tienen quemados en el código. Aunque hoy
// estén libres en el catálogo, mañana el módulo los va a usar: agarrar uno
// sería meter dos cosas distintas en la misma cuenta.
//   2-01 CxP (compras) · 2-02 IVA (ventas) · 2-04 CCSS y 2-05 salarios (RRHH)
const CUENTAS_RESERVADAS = ['2-01', '2-02', '2-04', '2-05'];
async function cuentaAnticipos(env) {
  // 1) ¿ya la eligieron antes?
  try {
    const r = await env.DB.prepare(`SELECT valor FROM config WHERE clave='cuenta_anticipos'`).first();
    if (r && r.valor) {
      const c = await env.DB.prepare(`SELECT codigo FROM fin_cuentas WHERE codigo=?`).bind(r.valor).first();
      if (c) return c.codigo;
    }
  } catch (e) {}
  // 2) ¿ya existe por nombre? (por si alguien la creó a mano)
  try {
    const c = await env.DB.prepare(`SELECT codigo FROM fin_cuentas WHERE lower(nombre)=lower(?) AND tipo='pasivo'`)
      .bind(CUENTA_ANTICIPOS_NOMBRE).first();
    if (c) { await cuentaAnticiposFijar(env, c.codigo); return c.codigo; }
  } catch (e) {}
  // 3) crearla en el primer código libre de la serie de pasivos que NO esté
  //    reservado por otro módulo. «Libre en el catálogo» no alcanza: RRHH usa
  //    el 2-04 y el 2-05 aunque no existan todavía.
  for (let i = 1; i <= 99; i++) {
    const cod = '2-' + String(i).padStart(2, '0');
    if (CUENTAS_RESERVADAS.includes(cod)) continue;
    try {
      const ocupada = await env.DB.prepare(`SELECT 1 AS x FROM fin_cuentas WHERE codigo=?`).bind(cod).first();
      if (ocupada) continue;
      await env.DB.prepare(`INSERT INTO fin_cuentas (codigo,nombre,tipo,activo) VALUES (?,?, 'pasivo',1)`)
        .bind(cod, CUENTA_ANTICIPOS_NOMBRE).run();
      await cuentaAnticiposFijar(env, cod);
      return cod;
    } catch (e) {}
  }
  return null;
}
async function cuentaAnticiposFijar(env, codigo) {
  try {
    await env.DB.prepare(`INSERT INTO config (clave,valor,descripcion,actualizado_en)
      VALUES ('cuenta_anticipos',?, 'Cuenta de pasivo para anticipos de clientes', ?)
      ON CONFLICT(clave) DO UPDATE SET valor=excluded.valor, actualizado_en=excluded.actualizado_en`)
      .bind(codigo, crParts().iso).run();
  } catch (e) {}
}
// v98 — Correo de cobro: el de la pantalla, si no el que ya guarda la
// cotización (columna cliente_email). Antes quedaba vacío y el motor de
// avisos no tenía a quién escribirle.
function cotCorreo(body, cot) {
  return String((body && body.correo) || (cot && cot.cliente_email) || '').trim();
}
// v98 — Vencimiento: antes `vence = finHoy()` → la CxC nacía venciendo el
// mismo día y el motor de avisos la disparaba de una.
const COT_PLAZO_DEF = 30;
function cotVence(body, desde) {
  const plazo = Number(body && body.plazo_dias);
  return finSumaDias(desde, plazo > 0 ? plazo : COT_PLAZO_DEF);
}
function finSumaDias(fechaISO, dias) {
  const p = String(fechaISO || '').split('-');
  if (p.length < 3) return fechaISO || '';
  const d = new Date(Date.UTC(Number(p[0]), Number(p[1]) - 1, Number(p[2]) + (Number(dias) || 0)));
  return d.toISOString().slice(0, 10);
}
// v18: buscar el correo del cliente en el CRM por nombre exacto (sin distinguir mayúsculas)
async function finCorreoDeCliente(env, nombre) {
  if (!nombre) return '';
  try {
    const c = await env.DB.prepare(`SELECT correo FROM crm_clientes
      WHERE activo=1 AND LOWER(TRIM(nombre))=LOWER(TRIM(?)) AND correo<>'' LIMIT 1`).bind(String(nombre)).first();
    return (c && c.correo) || '';
  } catch (e) { return ''; }
}
async function finCxcAbonar(env, body) {
  await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  const x = await env.DB.prepare(`SELECT * FROM fin_cxc WHERE id=?`).bind(body.id).first();
  if (!x) return j({ ok:false, error:'no existe' });
  if (x.estado !== 'pendiente') return j({ ok:false, error:'esta cuenta ya está cobrada' });
  const monto = Number(body.monto);
  if (!(monto > 0) || monto > x.saldo + 0.01) return j({ ok:false, error:'monto inválido (saldo: ' + x.saldo + ')' });
  const banco = await env.DB.prepare(`SELECT * FROM fin_bancos WHERE id=?`).bind(body.banco_id).first();
  if (!banco) return j({ ok:false, error:'elegí la cuenta que recibe' });
  if (banco.moneda !== x.moneda) return j({ ok:false, error:'la cuenta debe ser en ' + x.moneda });
  const fx = x.moneda === 'USD' ? (Number(x.tipo_cambio) || 1) : 1;
  const crc = finR2(monto * fx);
  const autor = await finQuienEs(env, body.pin) || String(body.pin || '');
  const fecha = body.fecha || finHoy();
  const asientoId = await finAsientoNuevo(env, fecha, 'Cobro CxC #' + x.id + ': ' + (x.detalle || x.cliente), 'cxc', autor,
    [{ cuenta_codigo:'1-01', detalle:'Cobro ' + x.cliente, debe: crc, haber: 0 },
     { cuenta_codigo:'1-02', detalle:'Cobro ' + x.cliente, debe: 0, haber: crc }]);
  await env.DB.prepare(`INSERT INTO fin_movimientos
    (fecha,tipo,categoria_id,banco_id,empresa,descripcion,referencia,monto,moneda,tipo_cambio,iva,asiento_id,centro_id,creado_por,creado_en)
    VALUES (?,'ingreso',NULL,?,?,?,?,?,?,?,0,?,?,?,datetime('now'))`)
    .bind(fecha, banco.id, 'Grupo', 'Abono CxC #' + x.id + ' — ' + x.cliente, '', monto, x.moneda,
      Number(x.tipo_cambio)||1, asientoId, x.centro_id||null, autor).run();
  const saldo = finR2(x.saldo - monto);
  await env.DB.prepare(`UPDATE fin_cxc SET saldo=?, estado=? WHERE id=?`)
    .bind(saldo, saldo <= 0.01 ? 'cobrada' : 'pendiente', x.id).run();
  return j({ ok:true, saldo, estado: saldo <= 0.01 ? 'cobrada' : 'pendiente' });
}
// ── v18: editar datos de cobro de una CxC (vence, correo, empresa, detalle) ──
// No toca montos ni asientos: solo los datos que usan los recordatorios.
async function finCxcEditar(env, body) {
  await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  const x = await env.DB.prepare(`SELECT * FROM fin_cxc WHERE id=?`).bind(body.id).first();
  if (!x) return j({ ok:false, error:'no existe' });
  const sets = [], vals = [];
  if (body.vence !== undefined)   { sets.push('vence=?');   vals.push(String(body.vence || '')); }
  if (body.plazo_dias !== undefined && body.vence === undefined) {
    sets.push('vence=?'); vals.push(finSumaDias(x.fecha || finHoy(), Number(body.plazo_dias) || 0));
  }
  if (body.correo !== undefined)  { sets.push('correo=?');  vals.push(String(body.correo || '').trim()); }
  if (body.empresa !== undefined) { sets.push('empresa=?'); vals.push(String(body.empresa || '').trim()); }
  if (body.detalle !== undefined) { sets.push('detalle=?'); vals.push(String(body.detalle || '')); }
  // Si cambió el vencimiento, se reinicia el ciclo de avisos (nueva cuenta regresiva)
  if (body.vence !== undefined || body.plazo_dias !== undefined) { sets.push(`ultimo_aviso=''`); sets.push('avisos=0'); }
  if (!sets.length) return j({ ok:true, sin_cambios:true });
  vals.push(x.id);
  await env.DB.prepare(`UPDATE fin_cxc SET ` + sets.join(',') + ` WHERE id=?`).bind(...vals).run();
  const y = await env.DB.prepare(`SELECT * FROM fin_cxc WHERE id=?`).bind(x.id).first();
  return j({ ok:true, cxc: y });
}
// ── v18: RECORDATORIOS DE COBRO CxC ──
// Regla: aviso 3 días ANTES de vencer, aviso el DÍA del vencimiento,
// y luego uno cada 7 días mientras la factura siga pendiente.
// Remitente: cobros@grupo-marc.com (secret EMAIL_FROM_COBROS opcional para cambiarlo).
// CC según empresa: IIMC (MARCAIRE/Consulting) → info@marcaire.com ·
//                   MARC S.A. (Metal/Equipos)  → info@equiposmarc.com
// Lo dispara el cron diario del worker o el botón de la app (fin_cxc_avisos).
const FIN_COBROS_CC = { 'IIMC S.A.': 'info@marcaire.com', 'MARC S.A.': 'info@equiposmarc.com' };
function finDiasEntre(deISO, aISO) { // a - de, en días enteros
  const p = s => { const q = String(s || '').split('-'); return q.length < 3 ? null : Date.UTC(Number(q[0]), Number(q[1]) - 1, Number(q[2])); };
  const a = p(aISO), b = p(deISO);
  if (a === null || b === null) return null;
  return Math.round((a - b) / 86400000);
}
function finFmtMonto(monto, moneda) {
  const n = Number(monto) || 0;
  const s = n.toLocaleString('es-CR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return (moneda === 'USD' ? '$' : '₡') + s;
}
async function finCxcEmpresaDe(env, x) {
  // 1) campo empresa de la CxC · 2) la marca de la venta CRM del centro · 3) MARCAIRE por defecto
  if (x.empresa) return x.empresa;
  if (x.centro_id) {
    try {
      const r = await env.DB.prepare(`SELECT o.empresa FROM fin_centros ce
        JOIN crm_oportunidades o ON o.id=ce.crm_op_id WHERE ce.id=?`).bind(x.centro_id).first();
      if (r && r.empresa) return r.empresa;
    } catch (e) {}
  }
  return 'MARCAIRE';
}
async function finCxcAvisos(env) {
  await finEnsure2(env);
  // Llave propia de la cuenta Resend de cobros (dominio grupo-marc.com);
  // si no existe, intenta con la llave general.
  const RESEND_KEY = env.RESEND_API_KEY_COBROS || env.RESEND_API_KEY;
  if (!RESEND_KEY) return { ok:false, sinServicio:true, error:'Correo automático no configurado (secret RESEND_API_KEY_COBROS)' };
  const hoy = finHoy();
  const rows = (await env.DB.prepare(`SELECT * FROM fin_cxc
    WHERE estado='pendiente' AND saldo > 0.01 AND vence<>''`).all()).results || [];
  let enviados = 0, sinCorreo = 0, omitidos = 0;
  const resumen = [];
  const errores = [];
  for (const x of rows) {
    const df = finDiasEntre(hoy, x.vence); // >0 faltan días · 0 vence hoy · <0 días de vencida
    if (df === null) { omitidos++; continue; }
    // ¿Toca avisar hoy?
    let toca = false;
    if (df === 3 || df === 0) toca = true;                    // 3 días antes · día del vencimiento
    else if (df < 0) {                                        // ya vencida: cada 7 días
      if (!x.ultimo_aviso) toca = true;                       // nunca se le avisó → avisar ya
      else { const d = finDiasEntre(x.ultimo_aviso, hoy); toca = (d !== null && d >= 7); }
    }
    if (!toca) { omitidos++; continue; }
    if (x.ultimo_aviso === hoy) { omitidos++; continue; }     // nunca dos correos el mismo día
    // Correo del cliente: el de la CxC o el del CRM
    let correo = String(x.correo || '').trim();
    if (!correo) correo = await finCorreoDeCliente(env, x.cliente);
    if (!correo) {
      sinCorreo++;
      resumen.push('⚠️ #' + x.id + ' ' + (x.cliente || '') + ' — SIN CORREO (saldo ' + finFmtMonto(x.saldo, x.moneda) + ', vence ' + x.vence + ')');
      continue;
    }
    // Empresa que firma y su copia interna
    const marca = await finCxcEmpresaDe(env, x);
    const razon = marcaARazon(marca) || 'IIMC S.A.';
    const cc = FIN_COBROS_CC[razon] || 'info@marcaire.com';
    const firma = (razon === 'MARC S.A.')
      ? marca + '\nEquipos y Andamios MARC S.A.\ninfo@equiposmarc.com · WhatsApp 8316-7373'
      : marca + '\nInstalaciones Industriales MC S.A. (IIMC)\ninfo@marcaire.com · Tel. 8753-5132';
    const estadoTxt = df > 0 ? ('vence en ' + df + ' día(s), el ' + x.vence)
      : df === 0 ? ('vence HOY (' + x.vence + ')')
      : ('venció el ' + x.vence + ' — lleva ' + (-df) + ' día(s) de atraso');
    const asunto = df > 0
      ? 'Recordatorio: su factura vence el ' + x.vence + ' — ' + marca
      : df === 0
      ? 'Su factura vence hoy — ' + marca
      : 'Factura pendiente de pago (' + (-df) + ' día(s) de atraso) — ' + marca;
    const cuerpo = 'Estimado cliente ' + (x.cliente || '') + ':\n\n' +
      'Le recordamos de manera cordial que tiene una factura pendiente con nosotros que ' + estadoTxt + '.\n\n' +
      'Detalle:  ' + (x.detalle || 'Servicios profesionales') + '\n' +
      'Fecha de factura:  ' + (x.fecha || '') + '\n' +
      'Monto total:  ' + finFmtMonto(Number(x.monto) + Number(x.iva || 0), x.moneda) + '\n' +
      'Saldo pendiente:  ' + finFmtMonto(x.saldo, x.moneda) + '\n\n' +
      'Si ya realizó el pago, por favor ignore este mensaje y de ser posible envíenos el comprobante respondiendo a este correo.\n' +
      'Si desea coordinar el pago o tiene alguna consulta, con gusto le atendemos.\n\n' +
      '¡Gracias por su preferencia!\n\n' + firma;
    try {
      const from = env.EMAIL_FROM_COBROS || 'Cobros Grupo MARC <cobros@grupo-marc.com>';
      const r = await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: { 'Authorization': 'Bearer ' + RESEND_KEY, 'Content-Type': 'application/json' },
        body: JSON.stringify({ from, to: [correo], cc: [cc], reply_to: ['cobros@grupo-marc.com'], subject: asunto, text: cuerpo })
      });
      if (r.ok) {
        enviados++;
        await env.DB.prepare(`UPDATE fin_cxc SET ultimo_aviso=?, avisos=COALESCE(avisos,0)+1, correo=? WHERE id=?`)
          .bind(hoy, correo, x.id).run();
        resumen.push('✅ #' + x.id + ' ' + (x.cliente || '') + ' → ' + correo + ' (' + estadoTxt + ', saldo ' + finFmtMonto(x.saldo, x.moneda) + ')');
      } else {
        const d = await r.json().catch(() => ({}));
        errores.push('#' + x.id + ' ' + (x.cliente || '') + ': ' + (d.message || r.status));
      }
    } catch (e) { errores.push('#' + x.id + ' ' + (x.cliente || '') + ': ' + e.message); }
  }
  // Resumen interno para Manu (solo si hubo actividad o cuentas sin correo)
  if (resumen.length || errores.length) {
    const txt = 'Resumen de recordatorios de cobro (CxC) — ' + hoy + '\n\n' +
      (resumen.length ? resumen.join('\n') + '\n\n' : '') +
      (errores.length ? 'Errores:\n' + errores.join('\n') + '\n\n' : '') +
      'Enviados: ' + enviados + ' · Sin correo: ' + sinCorreo + '\n\nMARC-ERP · Financiero';
    try {
      const from = env.EMAIL_FROM_COBROS || 'Cobros Grupo MARC <cobros@grupo-marc.com>';
      await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: { 'Authorization': 'Bearer ' + RESEND_KEY, 'Content-Type': 'application/json' },
        body: JSON.stringify({ from, to: ['info@marcaire.com'],
          subject: '📬 Cobros CxC ' + hoy + ': ' + enviados + ' recordatorio(s) enviado(s)' + (sinCorreo ? ' · ' + sinCorreo + ' sin correo' : ''),
          text: txt })
      });
    } catch (e) {}
  }
  return { ok:true, enviados, sinCorreo, omitidos, errores };
}
// Botón manual desde la app de Financiero
async function finCxcAvisosManual(env, body) {
  await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  const r = await finCxcAvisos(env);
  return j(r, r.ok ? 200 : 400);
}
async function finCxpCrear(env, body) {
  await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  const x = body.cxp || {};
  if (!x.proveedor || !(Number(x.monto) > 0)) return j({ ok:false, error:'proveedor y monto (>0)' });
  const cuenta = x.cuenta_gasto || '5-06';
  const fx = x.moneda === 'USD' ? (Number(x.tipo_cambio) || 1) : 1;
  const sub = finR2(Number(x.monto) * fx), iva = finR2(Number(x.iva || 0) * fx);
  const autor = await finQuienEs(env, body.pin) || String(body.pin || '');
  const L = [{ cuenta_codigo: cuenta, detalle: x.detalle || x.proveedor, debe: sub, haber: 0 }];
  if (iva > 0) L.push({ cuenta_codigo:'1-05', detalle:'IVA 13%', debe: iva, haber: 0 });
  L.push({ cuenta_codigo:'2-01', detalle: x.proveedor, debe: 0, haber: finR2(sub + iva) });
  const asientoId = await finAsientoNuevo(env, x.fecha || finHoy(),
    'Factura por pagar: ' + x.proveedor + (x.detalle ? ' — ' + x.detalle : ''), 'cxp', autor, L);
  await env.DB.prepare(`INSERT INTO fin_cxp
    (centro_id,proveedor,detalle,fecha,monto,moneda,tipo_cambio,iva,cuenta_gasto,saldo,estado,asiento_id,creado_por,creado_en)
    VALUES (?,?,?,?,?,?,?,?,?,?, 'pendiente', ?, ?, datetime('now'))`)
    .bind(x.centro_id||null, x.proveedor, x.detalle||'', x.fecha||finHoy(), Number(x.monto), x.moneda||'CRC',
      Number(x.tipo_cambio)||1, Number(x.iva)||0, cuenta, finR2(Number(x.monto)+Number(x.iva||0)), asientoId, autor).run();
  const n = await env.DB.prepare(`SELECT last_insert_rowid() AS id`).first();
  // v19.2 — espejo al Control de Costos si la CxP tiene centro (gasto devengado,
  // sin IVA para no inflar el costo real; familia opcional desde la app de Compras)
  if (x.centro_id) { try { await ccEspejo(env, Number(x.centro_id), { tipo:'gasto', familia: x.familia || null,
    pista:'compras', origen:'cxp',
    descripcion:'Factura por pagar: ' + x.proveedor + (x.detalle ? ' — ' + x.detalle : ''), referencia:'CXP#' + (n && n.id),
    moneda: x.moneda || 'CRC', monto: Number(x.monto) || 0, fecha: x.fecha || finHoy(), usuario: autor }); } catch (e) {} }
  return j({ ok:true, id: n && n.id });
}
async function finCxpListar(env, body) {
  await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  let sql = `SELECT x.*, ce.codigo AS centro FROM fin_cxp x LEFT JOIN fin_centros ce ON ce.id=x.centro_id WHERE 1=1`;
  const args = [];
  if (body.estado) { sql += ` AND x.estado=?`; args.push(body.estado); }
  sql += ` ORDER BY x.id DESC LIMIT 300`;
  return j({ ok:true, cxp: (await env.DB.prepare(sql).bind(...args).all()).results || [] });
}
async function finCxpPagar(env, body) {
  await finEnsure2(env);
  if (!await tienePermiso(env, body.pin, body.key, 'financiero', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  const x = await env.DB.prepare(`SELECT * FROM fin_cxp WHERE id=?`).bind(body.id).first();
  if (!x) return j({ ok:false, error:'no existe' });
  if (x.estado !== 'pendiente') return j({ ok:false, error:'esta cuenta ya está pagada' });
  const monto = Number(body.monto);
  if (!(monto > 0) || monto > x.saldo + 0.01) return j({ ok:false, error:'monto inválido (saldo: ' + x.saldo + ')' });
  const banco = await env.DB.prepare(`SELECT * FROM fin_bancos WHERE id=?`).bind(body.banco_id).first();
  if (!banco) return j({ ok:false, error:'elegí la cuenta que paga' });
  if (banco.moneda !== x.moneda) return j({ ok:false, error:'la cuenta debe ser en ' + x.moneda });
  const fx = x.moneda === 'USD' ? (Number(x.tipo_cambio) || 1) : 1;
  const crc = finR2(monto * fx);
  const autor = await finQuienEs(env, body.pin) || String(body.pin || '');
  const fecha = body.fecha || finHoy();
  const asientoId = await finAsientoNuevo(env, fecha, 'Pago CxP #' + x.id + ': ' + x.proveedor, 'cxp', autor,
    [{ cuenta_codigo:'2-01', detalle:'Pago ' + x.proveedor, debe: crc, haber: 0 },
     { cuenta_codigo:'1-01', detalle:'Pago ' + x.proveedor, debe: 0, haber: crc }]);
  await env.DB.prepare(`INSERT INTO fin_movimientos
    (fecha,tipo,categoria_id,banco_id,empresa,descripcion,referencia,monto,moneda,tipo_cambio,iva,asiento_id,centro_id,creado_por,creado_en)
    VALUES (?,'gasto',NULL,?,?,?,?,?,?,?,0,?,?,?,datetime('now'))`)
    .bind(fecha, banco.id, 'Grupo', 'Pago CxP #' + x.id + ' — ' + x.proveedor, '', monto, x.moneda,
      Number(x.tipo_cambio)||1, asientoId, x.centro_id||null, autor).run();
  const saldo = finR2(x.saldo - monto);
  await env.DB.prepare(`UPDATE fin_cxp SET saldo=?, estado=? WHERE id=?`)
    .bind(saldo, saldo <= 0.01 ? 'pagada' : 'pendiente', x.id).run();
  return j({ ok:true, saldo, estado: saldo <= 0.01 ? 'pagada' : 'pendiente' });
}

// ---- ORQUESTA: venta GANADA → proyecto + centro de costos + CxC ----
async function crmGanarOrquesta(env, op, autor) {
  await finEnsure2(env);
  // si ya se orquestó antes (re-ganada tras reabrir), devolver lo existente
  if (op.centro_id) {
    const ce = await env.DB.prepare(`SELECT codigo FROM fin_centros WHERE id=?`).bind(op.centro_id).first();
    return { codigo: ce && ce.codigo, centro_id: op.centro_id, cxc_id: op.cxc_id || null,
      proyecto_id: op.proyecto_codigo ? 'CRM-' + op.proyecto_codigo : null, repetida: true };
  }
  // Serie unificada del grupo: CC-2026-XXXX (el próximo proyecto es CC-2026-0146)
  const codigo = await ccSiguienteCodigo(env);
  const cli = await env.DB.prepare(`SELECT nombre, correo FROM crm_clientes WHERE id=?`).bind(op.cliente_id).first();
  const cliente = (cli && cli.nombre) || '';
  const clienteCorreo = (cli && cli.correo) || '';
  const razon = marcaARazon(op.empresa) || (op.empresa === 'MARC S.A.' ? 'MARC S.A.' : 'IIMC S.A.');
  const marca = marcaARazon(op.empresa) ? op.empresa : (op.empresa === 'MARC S.A.' ? 'Metal MARC' : 'MARCAIRE');
  // 1) centro de costos
  await env.DB.prepare(`INSERT INTO fin_centros (codigo,nombre,cliente,crm_op_id,estado,creado_en)
    VALUES (?,?,?,?, 'abierto', datetime('now'))`).bind(codigo, op.titulo, cliente, op.id).run();
  const cid = (await env.DB.prepare(`SELECT id FROM fin_centros WHERE codigo=?`).bind(codigo).first()).id;
  // Registro enriquecido: sub-centros según la razón social + origen
  try { await ccRegistrarRico(env, codigo, 'PROYECTO: ' + op.titulo, razon, marca, cliente, 'crm-op:' + op.id); } catch (e) {}
  // 2) cuenta por cobrar + asiento de devengo (DEBE CxC / HABER Ventas)
  let cxcId = null;
  const fx = op.moneda === 'USD' ? (Number(op.tipo_cambio) || 1) : 1;
  const sub = finR2((Number(op.monto) || 0) * fx);
  if (sub > 0) {
    const asientoId = await finAsientoNuevo(env, finHoy(), 'Venta ganada ' + codigo + ': ' + op.titulo, 'crm', autor,
      [{ cuenta_codigo:'1-02', detalle: op.titulo, debe: sub, haber: 0 },
       { cuenta_codigo:'4-01', detalle: op.titulo, debe: 0, haber: sub }]);
    await env.DB.prepare(`INSERT INTO fin_cxc
      (centro_id,cliente,detalle,fecha,monto,moneda,tipo_cambio,iva,saldo,estado,asiento_id,creado_por,creado_en,vence,correo,empresa)
      VALUES (?,?,?,?,?,?,?,0,?, 'pendiente', ?, ?, datetime('now'), ?, ?, ?)`)
      .bind(cid, cliente, op.titulo, finHoy(), Number(op.monto)||0, op.moneda||'CRC',
        Number(op.tipo_cambio)||1, Number(op.monto)||0, asientoId, autor,
        finHoy(), clienteCorreo, marca).run();
    cxcId = (await env.DB.prepare(`SELECT last_insert_rowid() AS id`).first()).id;
    // v62 — la facturación NUNCA cae completa: se crea el hito pendiente en la
    // tabla de pagos y el ingreso entra al CC solo cuando se aprueba cada pago.
    try { await ccPagoNuevo(env, codigo, { descripcion: 'Adjudicación CRM — ' + op.titulo + ' (definí la tabla de pagos)',
      porcentaje: 100, monto: Number(op.monto) || 0, moneda: op.moneda || 'CRC', origen: 'auto:crm' }); } catch (e) {}
  }
  // 3) proyecto en el maestro + en la app Control de Proyectos
  let pid = 'CRM-' + codigo;
  let proyectoAviso = null;
  const existente = await proyectoYaExiste(env, op.titulo);
  if (existente) { pid = existente.project_id; proyectoAviso = 'Proyecto ya existía (' + existente.project_name + '); se vinculó en vez de duplicar.'; }
  try {
    const t = crParts();
    await env.DB.prepare(`INSERT INTO proyectos (codigo,nombre,razon_social,empresa,cliente,activo,creado_en)
      VALUES (?,?,?,?,?,1,?) ON CONFLICT(codigo,razon_social) DO NOTHING`)
      .bind(codigo, op.titulo, razon, marca, cliente, t.iso).run();
    if (existente) throw { salto: true }; // no crear blob duplicado; el CC y la CxC ya quedaron
    const payload = JSON.stringify({
      project: { name: op.titulo, client: cliente, empresa: marca, razonSocial: razon,
        engineer: op.responsable || '', building: '', floor: '',
        customFields: [
          { label: 'Centro de costos', value: codigo },
          { label: 'Origen', value: 'Ventas CRM · oportunidad #' + op.id } ],
        reportCounter: { cliente: 0, supervisor: 0 }, reportHistory: [], clientUsers: [], assignedTeam: [] },
      equipment: [], logs: [], issues: [], photos: [], restrictions: [], submittals: [], changeOrders: []
    });
    await env.DB.prepare(`INSERT INTO proyectos_data
      (project_id,project_name,client,empresa,razon_social,overall,estado,last_modified,payload,trashed,creado_en,actualizado_en)
      VALUES (?,?,?,?,?,0,'activo',?,?,0,?,?) ON CONFLICT(project_id) DO NOTHING`)
      .bind(pid, op.titulo, cliente, marca, razon, Date.now(), payload, t.iso, t.iso).run();
  } catch (e) {}
  await env.DB.prepare(`UPDATE crm_oportunidades SET proyecto_codigo=?, centro_id=?, cxc_id=? WHERE id=?`)
    .bind(codigo, cid, cxcId, op.id).run();
  return { codigo, centro_id: cid, cxc_id: cxcId, proyecto_id: pid, proyecto_aviso: proyectoAviso };
}

// ============================================================
//  MÓDULO VENTAS CRM  (Grupo MARC)
//  -----------------------------------------------------------
//  POST '/' con action crm_* + pin (tienePermiso módulo 'crm').
//  Clientes → Oportunidades (pipeline por etapas con monto
//  ponderado) → Seguimientos con próxima acción.
// ============================================================
const CRM_ETAPAS = ['Prospecto','Contactado','Cotizado','Negociación'];
const CRM_PROB = { 'Prospecto':10, 'Contactado':25, 'Cotizado':50, 'Negociación':75 };
let CRM_READY = false;
async function crmEnsure(env) {
  if (_yaListo.crmEnsure) return; _yaListo.crmEnsure = true;   // v120 ⚡ una vez por instancia
  if (CRM_READY) return;
  await env.DB.batch([
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS crm_clientes (
      id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, identificacion TEXT DEFAULT '',
      contacto TEXT DEFAULT '', telefono TEXT DEFAULT '', correo TEXT DEFAULT '',
      direccion TEXT DEFAULT '', empresa TEXT DEFAULT 'Grupo', notas TEXT DEFAULT '',
      activo INTEGER DEFAULT 1, creado_por TEXT DEFAULT '', creado_en TEXT DEFAULT '')`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS crm_oportunidades (
      id INTEGER PRIMARY KEY AUTOINCREMENT, cliente_id INTEGER NOT NULL, titulo TEXT NOT NULL,
      empresa TEXT DEFAULT 'Grupo', fuente TEXT DEFAULT '', monto REAL DEFAULT 0,
      moneda TEXT DEFAULT 'CRC', tipo_cambio REAL DEFAULT 1, etapa TEXT DEFAULT 'Prospecto',
      probabilidad INTEGER DEFAULT 10, cierre_estimado TEXT DEFAULT '', responsable TEXT DEFAULT '',
      notas TEXT DEFAULT '', estado TEXT DEFAULT 'abierta', motivo_perdida TEXT DEFAULT '',
      proyecto_codigo TEXT DEFAULT '', centro_id INTEGER, cxc_id INTEGER,
      creado_por TEXT DEFAULT '', creado_en TEXT DEFAULT '', actualizado_en TEXT DEFAULT '')`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS crm_seguimientos (
      id INTEGER PRIMARY KEY AUTOINCREMENT, oportunidad_id INTEGER, cliente_id INTEGER,
      fecha TEXT NOT NULL, tipo TEXT DEFAULT 'llamada', nota TEXT DEFAULT '',
      proximo_paso TEXT DEFAULT '', proxima_fecha TEXT DEFAULT '',
      creado_por TEXT DEFAULT '', creado_en TEXT DEFAULT '')`),
    env.DB.prepare(`INSERT OR IGNORE INTO modulos (codigo,nombre,descripcion,icono,orden,activo)
      VALUES ('crm','Ventas CRM','Clientes y oportunidades','🤝',30,1)`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS crm_ofertas (
      id INTEGER PRIMARY KEY AUTOINCREMENT, consecutivo TEXT, cliente TEXT, proyecto TEXT,
      monto REAL, url TEXT, ruta TEXT, nombre TEXT, creado_por TEXT, creado_en TEXT)`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS crm_config (clave TEXT PRIMARY KEY, valor TEXT)`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS crm_firmas (
      token TEXT PRIMARY KEY, consecutivo TEXT, cliente TEXT, proyecto TEXT, monto REAL,
      pdf_url TEXT, estado TEXT DEFAULT 'pendiente', firmante TEXT DEFAULT '',
      firma_url TEXT DEFAULT '', acta_url TEXT DEFAULT '',
      creado_por TEXT DEFAULT '', creado_en TEXT DEFAULT '', firmado_en TEXT DEFAULT '')`)
  ]);
  try { await env.DB.prepare(`ALTER TABLE crm_ofertas ADD COLUMN version INTEGER`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE crm_oportunidades ADD COLUMN alq_consecutivo TEXT DEFAULT ''`).run(); } catch (e) {}   // v78 🔗 alquileres
  try { await env.DB.prepare(`ALTER TABLE crm_firmas ADD COLUMN alq_accion TEXT DEFAULT ''`).run(); } catch (e) {}                // v79 🔄 'renovacion'
  try { await env.DB.prepare(`ALTER TABLE crm_firmas ADD COLUMN alq_datos TEXT DEFAULT ''`).run(); } catch (e) {}                 // v79 🔄 período propuesto
  try { await env.DB.prepare(`ALTER TABLE crm_firmas ADD COLUMN tipo TEXT DEFAULT 'aprobada'`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE crm_firmas ADD COLUMN empresa TEXT DEFAULT 'marcaire'`).run(); } catch (e) {}
  try { await env.DB.prepare(`CREATE TABLE IF NOT EXISTS metal_productos (codigo TEXT PRIMARY KEY, descripcion TEXT, precio REAL, creado_en TEXT)`).run(); } catch (e) {}
  try { await env.DB.prepare(`CREATE TABLE IF NOT EXISTS crm_oferta_datos (consecutivo TEXT PRIMARY KEY, datos TEXT, actualizado_en TEXT)`).run(); } catch (e) {}
  try { await env.DB.prepare(`CREATE TABLE IF NOT EXISTS crm_contactos (id INTEGER PRIMARY KEY AUTOINCREMENT, cliente TEXT, nombre TEXT, telefono TEXT, email TEXT, creado_en TEXT)`).run(); } catch (e) {}  // v58
  CRM_READY = true;
}
const crmCRC = (o) => (Number(o.monto)||0) * (o.moneda === 'USD' ? (Number(o.tipo_cambio)||1) : 1);
async function crmQuien(env, pin) {
  const u = await env.DB.prepare(`SELECT nombre, apellido FROM usuarios WHERE pin=? AND activo=1`).bind(String(pin||'')).first();
  return u ? ((u.nombre||'') + ' ' + (u.apellido||'')).trim() : '';
}
// v38: equipo de ventas visible y editable desde el CRM (solo dueño/usuarios:admin).
// Nivel efectivo en CRM: dueño/admin = 'admin'; override crm; o rol 'vendedor' = 'operar'.
async function crmNivelDe(env, u) {
  if (u.rol === 'dueno' || u.rol === 'admin') return 'admin';
  const ov = await env.DB.prepare("SELECT nivel FROM permisos_usuario WHERE usuario_id = ? AND modulo = 'crm'").bind(u.id).first();
  if (ov) return ov.nivel;
  const p = await env.DB.prepare("SELECT nivel FROM permisos WHERE rol = ? AND modulo = 'crm'").bind(u.rol).first();
  return (p && p.nivel) || 'sin';
}
async function crmEquipo(env, body) {
  if (!await tienePermiso(env, body.pin || body.adminPin, body.key, 'usuarios', 'admin'))
    return j({ ok: false, error: 'Solo el dueño puede ver y gestionar el equipo' }, 403);
  await puEnsure(env);
  const soloCRM = body.soloCRM !== false; // por defecto, solo el equipo con acceso al CRM
  const us = (await env.DB.prepare('SELECT id,pin,nombre,apellido,rol,empresa,activo FROM usuarios WHERE activo = 1 ORDER BY nombre').all()).results || [];
  const equipo = [];
  for (const u of us) {
    const nivel = await crmNivelDe(env, u);
    if (soloCRM && nivel === 'sin') continue; // solo quienes pueden entrar al CRM
    equipo.push({ id: u.id, pin: u.pin, nombre: ((u.nombre || '') + ' ' + (u.apellido || '')).trim(),
      nombre1: u.nombre, apellido: u.apellido || '', rol: u.rol, empresa: u.empresa || '', activo: u.activo,
      nivel, acceso: nivel === 'admin' ? 'gerente' : (nivel === 'operar' ? 'vendedor' : 'sin'),
      esDueno: (u.rol === 'dueno' || u.rol === 'admin') });
  }
  return j({ ok: true, equipo });
}
async function crmEquipoGuardar(env, body) {
  if (!await tienePermiso(env, body.pin || body.adminPin, body.key, 'usuarios', 'admin'))
    return j({ ok: false, error: 'Solo el dueño puede gestionar el equipo' }, 403);
  await puEnsure(env);
  const p = body.persona || {};
  const nombre = String(p.nombre || '').trim();
  const pin = String(p.pin || '').trim();
  const acceso = (p.acceso === 'gerente') ? 'gerente' : 'vendedor';
  if (!nombre) return j({ ok: false, error: 'Falta el nombre' }, 400);
  if (!/^[0-9]{3,6}$/.test(pin)) return j({ ok: false, error: 'El PIN debe tener de 3 a 6 dígitos' }, 400);
  // PIN único (salvo que sea el mismo usuario)
  const choque = await env.DB.prepare('SELECT id FROM usuarios WHERE pin = ? AND id != ?').bind(pin, String(p.id || '')).first();
  if (choque) return j({ ok: false, error: 'Ese PIN ya lo usa otra persona' }, 400);
  const t = crParts();
  // id ESTABLE e independiente del PIN (evita choques al editar PINs)
  const id = p.id || ('v_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6));
  const existe = p.id ? await env.DB.prepare('SELECT id,rol FROM usuarios WHERE id = ?').bind(p.id).first() : null;
  // Nombre/apellido: si viene junto, partir en primer palabra + resto
  let nom = p.nombre1 != null ? p.nombre1 : nombre, ape = p.apellido != null ? p.apellido : '';
  if (p.nombre1 == null && nombre.includes(' ')) { const parts = nombre.split(' '); nom = parts.shift(); ape = parts.join(' '); }
  // ¿Quién ejecuta la acción? (para no dejar que se quite el poder a sí mismo)
  const yo = await env.DB.prepare('SELECT id FROM usuarios WHERE pin = ? AND activo = 1').bind(String(body.pin || body.adminPin || '')).first();
  const eraAdmin = existe && (existe.rol === 'dueno' || existe.rol === 'admin');
  const bajaDeAdmin = eraAdmin && acceso === 'vendedor'; // se le quita el poder total
  if (bajaDeAdmin) {
    if (yo && yo.id === existe.id) return j({ ok: false, error: 'No podés quitarte a vos mismo el acceso total. Que otro dueño lo haga.' }, 400);
    const admins = await env.DB.prepare("SELECT COUNT(*) AS n FROM usuarios WHERE activo=1 AND rol IN ('dueno','admin')").first();
    if ((admins.n || 0) <= 1) return j({ ok: false, error: 'Debe quedar al menos un dueño/administrador.' }, 400);
  }
  // rol resultante: si se degrada un admin → 'vendedor'; si no, conserva el suyo (o nace vendedor)
  const rolBase = bajaDeAdmin ? 'vendedor' : (existe ? existe.rol : 'vendedor');
  await env.DB.prepare(`INSERT INTO usuarios (id,pin,nombre,apellido,rol,empresa,activo,creado_en,actualizado_en)
    VALUES (?,?,?,?,?,?,?, COALESCE((SELECT creado_en FROM usuarios WHERE id=?),?), ?)
    ON CONFLICT(id) DO UPDATE SET pin=excluded.pin, nombre=excluded.nombre, apellido=excluded.apellido,
      rol=excluded.rol, empresa=excluded.empresa, activo=excluded.activo, actualizado_en=excluded.actualizado_en`)
    .bind(id, pin, nom, ape, rolBase, String(p.empresa || ''), (p.activo === 0 ? 0 : 1), id, t.iso, t.iso).run();
  // Override de CRM solo cuando NO es dueño/admin base (ellos ya tienen todo por su rol)
  if (rolBase !== 'dueno' && rolBase !== 'admin') {
    const nivel = acceso === 'gerente' ? 'admin' : 'operar';
    await env.DB.prepare(`INSERT INTO permisos_usuario (usuario_id,modulo,nivel) VALUES (?, 'crm', ?)
      ON CONFLICT(usuario_id,modulo) DO UPDATE SET nivel=excluded.nivel`).bind(id, nivel).run();
  }
  return j({ ok: true, id, pin, acceso: (rolBase==='dueno'||rolBase==='admin') ? 'gerente' : acceso, degradado: bajaDeAdmin });
}
async function crmEquipoBaja(env, body) {
  if (!await tienePermiso(env, body.pin || body.adminPin, body.key, 'usuarios', 'admin'))
    return j({ ok: false, error: 'Solo el dueño puede gestionar el equipo' }, 403);
  const id = String(body.id || '');
  const u = await env.DB.prepare('SELECT id,rol FROM usuarios WHERE id = ?').bind(id).first();
  if (!u) return j({ ok: false, error: 'No encontrado' }, 404);
  const yo = await env.DB.prepare('SELECT id FROM usuarios WHERE pin = ? AND activo = 1').bind(String(body.pin || body.adminPin || '')).first();
  if (yo && yo.id === u.id) return j({ ok: false, error: 'No podés darte de baja a vos mismo.' }, 400);
  if (u.rol === 'dueno' || u.rol === 'admin') {
    const admins = await env.DB.prepare("SELECT COUNT(*) AS n FROM usuarios WHERE activo=1 AND rol IN ('dueno','admin')").first();
    if ((admins.n || 0) <= 1) return j({ ok: false, error: 'Es el último dueño/administrador: no se puede quitar.' }, 400);
  }
  await env.DB.prepare('UPDATE usuarios SET activo = 0 WHERE id = ?').bind(id).run();
  return j({ ok: true });
}

// v39: asignar vendedor/origen a cotizaciones existentes (en lote). Dato gerencial, cualquier estado.
async function cotVendedor(env, body) {
  if (!await tienePermiso(env, body.pin || body.adminPin, body.key, 'crm', 'operar')) return j({ ok: false, error: 'Sin permiso' }, 403);
  const cons = Array.isArray(body.consecutivos) ? body.consecutivos : (body.consecutivo ? [body.consecutivo] : []);
  if (!cons.length) return j({ ok: false, error: 'Elegí al menos una cotización' });
  const vendedor = body.vendedor != null ? String(body.vendedor).trim() : null;
  const origen = body.origen != null ? String(body.origen).trim() : null;
  if (vendedor == null && origen == null) return j({ ok: false, error: 'Nada que asignar' });
  const t = crParts();
  let n = 0;
  for (const c of cons) {
    if (vendedor != null && origen != null)
      await env.DB.prepare('UPDATE crm_cotizaciones SET vendedor=?, origen=?, actualizado_en=? WHERE consecutivo=?').bind(vendedor, origen, t.iso, String(c).trim()).run();
    else if (vendedor != null)
      await env.DB.prepare('UPDATE crm_cotizaciones SET vendedor=?, actualizado_en=? WHERE consecutivo=?').bind(vendedor, t.iso, String(c).trim()).run();
    else
      await env.DB.prepare('UPDATE crm_cotizaciones SET origen=?, actualizado_en=? WHERE consecutivo=?').bind(origen, t.iso, String(c).trim()).run();
    n++;
  }
  return j({ ok: true, actualizadas: n, vendedor, origen });
}

// v41: guardar el PDF de una oferta en R2, ligado a su consecutivo
// v54: GUARDAR/CARGAR los DATOS EDITABLES de la oferta (no solo el PDF), ligados al consecutivo.
// Así, al reabrir la oferta se recuperan TODAS las ediciones y se corrige ahí (no en Word/PDF).
async function ofertaDatosGuardar(env, body) {
  if (!await tienePermiso(env, body.pin || body.adminPin, body.key, 'crm', 'operar')) return j({ ok: false, error: 'Sin permiso' }, 403);
  await crmEnsure(env);
  const cons = String(body.consecutivo || '').trim();
  if (!cons) return j({ ok: false, error: 'Falta consecutivo' }, 400);
  const datos = typeof body.datos === 'string' ? body.datos : JSON.stringify(body.datos || {});
  const t = crParts();
  await env.DB.prepare(`INSERT INTO crm_oferta_datos (consecutivo,datos,actualizado_en) VALUES (?,?,?)
    ON CONFLICT(consecutivo) DO UPDATE SET datos=excluded.datos, actualizado_en=excluded.actualizado_en`)
    .bind(cons, datos, t.iso).run();
  return j({ ok: true, consecutivo: cons });
}
async function ofertaDatosCargar(env, body) {
  if (!await tienePermiso(env, body.pin || body.adminPin, body.key, 'crm', 'operar')) return j({ ok: false, error: 'Sin permiso' }, 403);
  await crmEnsure(env);
  const cons = String(body.consecutivo || '').trim();
  if (!cons) return j({ ok: false, error: 'Falta consecutivo' }, 400);
  const r = await env.DB.prepare('SELECT datos, actualizado_en FROM crm_oferta_datos WHERE consecutivo=?').bind(cons).first();
  if (!r) return j({ ok: true, existe: false, datos: null });
  let datos = null; try { datos = JSON.parse(r.datos); } catch (e) { datos = null; }
  return j({ ok: true, existe: true, datos, actualizado_en: r.actualizado_en });
}
async function crmOfertaGuardar(env, body) {
  if (!await tienePermiso(env, body.pin || body.adminPin, body.key, 'crm', 'operar')) return j({ ok: false, error: 'Sin permiso' }, 403);
  await crmEnsure(env);
  if (!env.ARCHIVOS) return j({ ok: false, error: 'R2 no configurado' }, 400);
  if (!body.base64) return j({ ok: false, error: 'Falta el PDF' }, 400);
  const cons = String(body.consecutivo || 'sin').replace(/[^0-9A-Za-z#-]/g, '');
  // Versión: la enviada, o la siguiente para este consecutivo
  let version = Number(body.version) || 0;
  if (!version) {
    const mx = await env.DB.prepare("SELECT MAX(version) v FROM crm_ofertas WHERE consecutivo = ?").bind(String(body.consecutivo || '')).first();
    version = ((mx && mx.v) || 0) + 1;
  }
  const id = cons.replace('#', '') + '-v' + version + '-' + Date.now().toString(36);
  const ruta = 'ofertas/' + id + '.pdf';
  const t = crParts();
  try {
    const bytes = Uint8Array.from(atob(soloBase64(body.base64)), c => c.charCodeAt(0));
    await env.ARCHIVOS.put(ruta, bytes, { httpMetadata: { contentType: 'application/pdf' } });
    const base = 'https://marc-erp-espejo.mariangel.workers.dev/archivo';   // v59: SIEMPRE por la puerta del núcleo (r2.dev dejó de servir)
    const url = base + '/' + ruta;
    const nombre = String(body.nombre || ('Oferta ' + cons + ' v' + version + '.pdf'));
    await env.DB.prepare(`INSERT INTO crm_ofertas (consecutivo,cliente,proyecto,monto,url,ruta,nombre,version,creado_por,creado_en)
      VALUES (?,?,?,?,?,?,?,?,?,?)`).bind(String(body.consecutivo || ''), String(body.cliente || ''), String(body.proyecto || ''),
      Number(body.monto) || 0, url, ruta, nombre, version, String(body.pin || ''), t.iso).run();
    return j({ ok: true, url, ruta, version });
  } catch (e) { return j({ ok: false, error: e.message }, 500); }
}
// v43: enviar la oferta al cliente por correo (PDF adjunto) para que la devuelva firmada
// v44: FIRMA ELECTRÓNICA — crear solicitud, consultar (público), firmar (público), listar
async function crmFirmaCrear(env, body) {
  if (!await tienePermiso(env, body.pin || body.adminPin, body.key, 'crm', 'operar')) return j({ ok: false, error: 'Sin permiso' }, 403);
  await crmEnsure(env);
  const token = (crypto.randomUUID ? crypto.randomUUID().replace(/-/g, '') : (Date.now().toString(36) + Math.random().toString(36).slice(2))).slice(0, 24);
  const t = crParts();
  const tipo = (String(body.tipo || 'aprobada').toLowerCase() === 'recibida') ? 'recibida' : 'aprobada';
  const emp = String(body.empresa || 'marcaire').toLowerCase();
  const empresa = (emp === 'metal') ? 'metal' : (emp === 'equipos') ? 'equipos' : 'marcaire';   // v77 🏗️ Equipos MARC
  await env.DB.prepare(`INSERT INTO crm_firmas (token,consecutivo,cliente,proyecto,monto,pdf_url,estado,tipo,empresa,creado_por,creado_en)
    VALUES (?,?,?,?,?,?,'pendiente',?,?,?,?)`).bind(token, String(body.consecutivo || ''), String(body.cliente || ''),
    String(body.proyecto || ''), Number(body.monto) || 0, String(body.pdf_url || ''), tipo, empresa, String(body.pin || ''), t.iso).run();
  return j({ ok: true, token, tipo, empresa });
}
// PÚBLICO (sin PIN): el cliente abre el link con ?firmar=token
async function crmFirmaInfo(env, body) {
  await crmEnsure(env);
  const r = await env.DB.prepare('SELECT token,consecutivo,cliente,proyecto,monto,pdf_url,estado,firmante,firmado_en,acta_url,tipo,empresa,alq_accion,alq_datos FROM crm_firmas WHERE token = ?').bind(String(body.token || '')).first();
  if (!r) return j({ ok: false, error: 'Solicitud de firma no encontrada' }, 404);
  return j({ ok: true, firma: r });
}
// PÚBLICO: el cliente firma con el dedo
async function crmFirmaFirmar(env, body) {
  await crmEnsure(env);
  const token = String(body.token || '');
  const r = await env.DB.prepare('SELECT * FROM crm_firmas WHERE token = ?').bind(token).first();
  if (!r) return j({ ok: false, error: 'Solicitud no encontrada' }, 404);
  if (r.estado === 'firmada') return j({ ok: false, error: 'Esta oferta ya fue firmada' }, 409);
  const firmante = String(body.firmante || '').trim();
  if (!firmante) return j({ ok: false, error: 'Falta el nombre de quien firma' }, 400);
  if (!body.firma) return j({ ok: false, error: 'Falta la firma' }, 400);
  const t = crParts();
  let firmaUrl = '', actaUrl = '';
  const base = 'https://marc-erp.late-dew-2dd9.workers.dev/archivo';   // v59: SIEMPRE por la puerta del núcleo (r2.dev dejó de servir)
  if (env.ARCHIVOS) {
    try {
      const fr = 'ofertas/firmas/' + token + '.png';
      await env.ARCHIVOS.put(fr, Uint8Array.from(atob(soloBase64(body.firma)), c => c.charCodeAt(0)), { httpMetadata: { contentType: 'image/png' } });
      firmaUrl = base + '/' + fr;
    } catch (e) {}
    if (body.acta) {
      try {
        const ar = 'ofertas/firmadas/' + token + '.pdf';
        await env.ARCHIVOS.put(ar, Uint8Array.from(atob(soloBase64(body.acta)), c => c.charCodeAt(0)), { httpMetadata: { contentType: 'application/pdf' } });
        actaUrl = base + '/' + ar;
      } catch (e) {}
    }
  }
  await env.DB.prepare(`UPDATE crm_firmas SET estado='firmada', firmante=?, firma_url=?, acta_url=?, firmado_en=? WHERE token=?`)
    .bind(firmante, firmaUrl, actaUrl, t.iso, token).run();
  // ── v79 🔄 El cliente firmó una propuesta de RENOVACIÓN: se renueva sola ──
  // El candado de alqRenovar (estado 'Renovada') impide que esto choque con
  // una renovación hecha a mano; y renovar a mano anula esta solicitud antes.
  let renov = null;
  if (String(r.alq_accion || '') === 'renovacion') {
    try {
      let d = {};
      try { d = JSON.parse(r.alq_datos || '{}'); } catch (e) {}
      const rr = await alqRenovar(env, { key: (env && env.SETUP_KEY) || SETUP_KEY,
        consecutivo: r.consecutivo, fechaAprob: d.fechaAprob || '', dias: d.dias,
        totalUSD: d.totalUSD, detalle: d.detalle || '', pdf: r.pdf_url || '',
        cotizadoPor: 'Firma del cliente: ' + firmante, avisar: true, correo: d.correo || '' });
      renov = await rr.json();
    } catch (e) { renov = { ok: false, error: String(e) }; }
  }
  // ── v94 🧾 LA FIRMA APRUEBA Y FACTURA ──────────────────────────────────────
  // Firmar es aceptar: abre el centro de costos y manda el detalle a
  // facturación, igual que si Manu tocara Aprobar. Sirve para la oferta normal
  // y para el período nuevo de una renovación. Idempotente: alqAprobar no
  // duplica CC ni CxC si ya existen.
  let facturado = null;
  if (String(r.empresa || '') === 'equipos') {
    const objetivo = (renov && renov.ok && renov.consecutivo) ? renov.consecutivo : r.consecutivo;
    if (objetivo) {
      try {
        const cfg = await alqConfigGet(env);
        const fr = await alqAprobar(env, { key: (env && env.SETUP_KEY) || SETUP_KEY,
          consecutivo: objetivo, plazoDias: Number(cfg.plazoFirma) || 0,
          cotizadoPor: 'Firma del cliente: ' + firmante });
        facturado = await fr.json();
      } catch (e) { facturado = { ok: false, error: String(e) }; }
    }
  }
  // ── v97 (17-jul-2026): 🐛 FIX — LA FIRMA NO APROBABA METAL MARC NI MARCAIRE ──
  // La v94 decía "firmar es aceptar" pero el if solo cubría empresa='equipos'.
  // Las firmas de 'metal' y 'marcaire' guardaban acta, mandaban el correo... y
  // la cotización quedaba en Pendiente PARA SIEMPRE (caso oferta 1660).
  // Ahora la firma de APROBACIÓN también las gana, vía cotGanar (la misma
  // orquesta del botón Aprobar: abre CC + CxC + asiento).
  // 🔒 Candados:
  //   · tipo='recibida' (recibido conforme) NO gana: no abre CC ni CxC.
  //   · cotGanar ya rechaza si la cotización tiene cc_codigo → no duplica.
  //   · cotGanar ya rechaza alquileres y anuladas → no choca con la v92.
  //   · Va después del correo-aviso porque este es best-effort y no debe
  //     perderse si cotGanar falla; y si falla, la firma NO se pierde.
  else if (r.consecutivo && String(r.tipo || 'aprobada') === 'aprobada') {
    try {
      const fr = await cotGanar(env, { key: (env && env.SETUP_KEY) || SETUP_KEY,
        consecutivo: String(r.consecutivo), usuario: 'Firma del cliente: ' + firmante });
      facturado = await fr.json();
    } catch (e) { facturado = { ok: false, error: String(e) }; }
  }
  // Aviso a MARC (best-effort; no bloquea la firma)
  const esEquipos = String(r.empresa || '') === 'equipos';                       // v77 🏗️
  const KEY = esEquipos ? (env.RESEND_API_KEY || env.RESEND_API_KEY_MARCAIRE)
                        : (env.RESEND_API_KEY_MARCAIRE || env.RESEND_API_KEY);
  if (KEY) {
    try {
      const from = esEquipos ? (env.EMAIL_FROM || 'Equipos MARC <onboarding@resend.dev>')
                             : (env.EMAIL_FROM_MARCAIRE || 'MARC AIRE <no-reply@marcaire.com>');
      const aviso = 'Oferta ' + (r.consecutivo || '') + (r.proyecto ? ' · ' + r.proyecto : '') + ' FIRMADA por ' + firmante;
      const cuerpo = firmante + ' firmó la oferta ' + (r.consecutivo || '') + (r.proyecto ? ' del proyecto ' + r.proyecto : '') +
        ' (cliente ' + (r.cliente || '') + ') el ' + t.fecha + '.\n\n' + (actaUrl ? 'Acta firmada: ' + actaUrl + '\n' : '') + (r.pdf_url ? 'Oferta: ' + r.pdf_url : '');
      const dest = esEquipos ? 'info@equiposmarc.com' : (env.EMAIL_AVISOS_OFERTAS || 'info@marcaire.com');
      const payload = { from, to: [dest], subject: '✅ ' + aviso, text: cuerpo };
      if (esEquipos) { try { const cc = alqCC(await alqConfigGet(env), []); if (cc.length) payload.cc = cc; } catch (e) {} }
      if (body.acta) payload.attachments = [{ filename: 'Acta_' + (r.consecutivo || 'firma').replace(/[^A-Za-z0-9]/g,'') + '.pdf', content: soloBase64(body.acta) }];
      await fetch('https://api.resend.com/emails', { method: 'POST', headers: { 'Authorization': 'Bearer ' + KEY, 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    } catch (e) {}
  }
  return j({ ok: true, acta_url: actaUrl, firmado_en: t.iso, renovacion: renov, facturado });   // v94 🧾
}
async function crmFirmaBorrar(env, body) {
  if (!await tienePermiso(env, body.pin || body.adminPin, body.key, 'crm', 'operar')) return j({ ok: false, error: 'Sin permiso' }, 403);
  await crmEnsure(env);
  const token = String(body.token || '');
  if (!token) return j({ ok: false, error: 'Falta token' }, 400);
  if (env.ARCHIVOS) {
    try { await env.ARCHIVOS.delete('ofertas/firmas/' + token + '.png'); } catch (e) {}
    try { await env.ARCHIVOS.delete('ofertas/firmadas/' + token + '.pdf'); } catch (e) {}
  }
  await env.DB.prepare('DELETE FROM crm_firmas WHERE token = ?').bind(token).run();
  return j({ ok: true });
}
async function crmFirmaListar(env, body) {
  if (!await tienePermiso(env, body.pin || body.adminPin, body.key, 'crm', 'ver')) return j({ ok: false, error: 'Sin permiso' }, 403);
  await crmEnsure(env);
  let q = 'SELECT token,consecutivo,cliente,proyecto,estado,tipo,empresa,firmante,firmado_en,acta_url,pdf_url,creado_en FROM crm_firmas';
  const bind = [];
  const cond = [];
  // v77: las firmas de Alquileres (empresa='equipos') viven en su propia app;
  // no ensucian el panel del CRM salvo que se pidan expresamente.
  if (body.empresa) { cond.push('empresa = ?'); bind.push(String(body.empresa)); }
  else if (!body.todas) cond.push("(empresa IS NULL OR empresa <> 'equipos')");
  if (body.consecutivo) { cond.push('consecutivo = ?'); bind.push(String(body.consecutivo)); }
  if (cond.length) q += ' WHERE ' + cond.join(' AND ');
  q += ' ORDER BY rowid DESC LIMIT 200';
  const st = env.DB.prepare(q); const res = await (bind.length ? st.bind(...bind) : st).all();
  return j({ ok: true, firmas: res.results || [] });
}
async function crmOfertaEnviar(env, body) {
  if (!await tienePermiso(env, body.pin || body.adminPin, body.key, 'crm', 'operar')) return j({ ok: false, error: 'Sin permiso' }, 403);
  await crmEnsure(env);
  const KEY = env.RESEND_API_KEY_MARCAIRE || env.RESEND_API_KEY;
  if (!KEY) return j({ ok: false, error: 'Correo no configurado (falta secret RESEND_API_KEY_MARCAIRE)' }, 400);
  const to = String(body.email || '').trim();
  if (!to || !to.includes('@')) return j({ ok: false, error: 'Falta el correo del cliente' }, 400);
  if (!body.base64) return j({ ok: false, error: 'Falta el PDF' }, 400);
  const cons = String(body.consecutivo || '').replace('#', '');
  const nombre = String(body.nombre || ('Oferta ' + cons + '.pdf')).replace(/[^A-Za-z0-9._-]/g, '_');
  // 1) Guardar copia en R2 (registro)
  let url = '';
  if (env.ARCHIVOS) {
    try {
      const ruta = 'ofertas/' + (cons || 'x') + '-' + Date.now().toString(36) + '.pdf';
      const bytes = Uint8Array.from(atob(soloBase64(body.base64)), c => c.charCodeAt(0));
      await env.ARCHIVOS.put(ruta, bytes, { httpMetadata: { contentType: 'application/pdf' } });
      const base = 'https://marc-erp.late-dew-2dd9.workers.dev/archivo';   // v59: SIEMPRE por la puerta del núcleo (r2.dev dejó de servir)
      url = base + '/' + ruta;
      const t = crParts();
      await env.DB.prepare(`INSERT INTO crm_ofertas (consecutivo,cliente,proyecto,monto,url,ruta,nombre,creado_por,creado_en)
        VALUES (?,?,?,?,?,?,?,?,?)`).bind(String(body.consecutivo || ''), String(body.cliente || ''), String(body.proyecto || ''),
        Number(body.monto) || 0, url, ruta, nombre, String(body.pin || ''), t.iso).run();
    } catch (e) {}
  }
  // 2) Enviar por correo con adjunto
  const from = env.EMAIL_FROM_MARCAIRE || 'MARC AIRE <no-reply@marcaire.com>';
  const proy = String(body.proyecto || '');
  const cli = String(body.cliente || '');
  const asunto = 'Oferta ' + (body.consecutivo || '') + (proy ? ' · ' + proy : '') + ' — MARC AIRE';
  const cuerpo = String(body.mensaje || '').trim() ||
    ('Estimado cliente,\n\nAdjunto encontrará nuestra propuesta técnico-comercial' + (proy ? ' para el proyecto ' + proy : '') + '.\n\n' +
     'Una vez revisada, le agradecemos devolver este documento firmado para formalizar la aceptación. Quedamos atentos a cualquier consulta.\n\n' +
     'Cordialmente,\nMARC AIRE — HVAC Systems\nTel. 8316-7373 / 8840-5201 · info@marcaire.com');
  const payload = {
    from, to: [to], reply_to: env.EMAIL_REPLY_OFERTAS || 'info@marcaire.com',
    subject: asunto, text: cuerpo,
    attachments: [{ filename: nombre.endsWith('.pdf') ? nombre : (nombre + '.pdf'), content: soloBase64(body.base64) }]
  };
  try {
    const r = await fetch('https://api.resend.com/emails', {
      method: 'POST', headers: { 'Authorization': 'Bearer ' + KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload)
    });
    if (!r.ok) { const tx = await r.text(); return j({ ok: false, error: 'Resend: ' + tx.slice(0, 200), url }, 502); }
    return j({ ok: true, enviado: to, url });
  } catch (e) { return j({ ok: false, error: e.message, url }, 500); }
}
