  await env.DB.prepare(`INSERT INTO crm_seguimientos
    (oportunidad_id,cliente_id,fecha,tipo,nota,proximo_paso,proxima_fecha,creado_por,creado_en)
    VALUES (?,?,?,?,?,?,?,?,datetime('now'))`)
    .bind(s.oportunidad_id||null, s.cliente_id||null, s.fecha, s.tipo||'llamada', s.nota||'',
      s.proximo_paso||'', s.proxima_fecha||'', autor).run();
  if (s.oportunidad_id) await env.DB.prepare(
    `UPDATE crm_oportunidades SET actualizado_en=datetime('now') WHERE id=?`).bind(s.oportunidad_id).run();
