async function crmSegListar(env, body) {
  await crmEnsure(env);
  if (!await tienePermiso(env, body.pin, body.key, 'crm', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  let sql = `SELECT s.*, o.titulo AS oportunidad, c.nombre AS cliente
    FROM crm_seguimientos s
    LEFT JOIN crm_oportunidades o ON o.id=s.oportunidad_id
    LEFT JOIN crm_clientes c ON c.id = COALESCE(s.cliente_id, o.cliente_id) WHERE 1=1`;
  const args = [];
  if (body.oportunidad_id) { sql += ` AND s.oportunidad_id=?`; args.push(body.oportunidad_id); }
  if (body.cliente_id) { sql += ` AND (s.cliente_id=? OR o.cliente_id=?)`; args.push(body.cliente_id, body.cliente_id); }
  if (body.pendientes) sql += ` AND s.proxima_fecha <> '' AND s.proxima_fecha <= date('now')
    AND o.estado IS NOT 'ganada' AND o.estado IS NOT 'perdida'`;
  sql += ` ORDER BY s.fecha DESC, s.id DESC LIMIT 300`;
  return j({ ok:true, seguimientos: (await env.DB.prepare(sql).bind(...args).all()).results || [] });
}
async function crmPanel(env, body) {
  await crmEnsure(env);
  if (!await tienePermiso(env, body.pin, body.key, 'crm', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  const desde = body.desde || '0000', hasta = body.hasta || '9999';
  const abiertas = (await env.DB.prepare(`SELECT o.*, c.nombre AS cliente FROM crm_oportunidades o
    LEFT JOIN crm_clientes c ON c.id=o.cliente_id WHERE o.estado='abierta' ORDER BY o.actualizado_en DESC`).all()).results || [];
  const pipeline = CRM_ETAPAS.map(e => {
    const ops = abiertas.filter(o => o.etapa === e);
    const monto = ops.reduce((s,o)=>s+crmCRC(o),0);
    const ponderado = ops.reduce((s,o)=>s+crmCRC(o)*(Number(o.probabilidad)||0)/100,0);
    return { etapa: e, cantidad: ops.length, monto: Math.round(monto), ponderado: Math.round(ponderado) };
  });
  const cerr = await env.DB.prepare(`SELECT
    COALESCE(SUM(CASE WHEN estado='ganada' THEN 1 END),0) AS gn,
    COALESCE(SUM(CASE WHEN estado='ganada' THEN monto*(CASE WHEN moneda='USD' THEN tipo_cambio ELSE 1 END) END),0) AS gm,
    COALESCE(SUM(CASE WHEN estado='perdida' THEN 1 END),0) AS pn
    FROM crm_oportunidades WHERE actualizado_en >= ? AND actualizado_en <= ? || ' 23:59:59'`)
    .bind(desde, hasta).first();
  const vencidos = (await env.DB.prepare(`SELECT s.*, o.titulo AS oportunidad, c.nombre AS cliente
    FROM crm_seguimientos s
    LEFT JOIN crm_oportunidades o ON o.id=s.oportunidad_id
    LEFT JOIN crm_clientes c ON c.id=COALESCE(s.cliente_id,o.cliente_id)
    WHERE s.proxima_fecha <> '' AND s.proxima_fecha <= date('now')
      AND (o.id IS NULL OR o.estado='abierta')
    ORDER BY s.proxima_fecha LIMIT 50`).all()).results || [];
  return j({ ok:true, pipeline,
    totalAbiertas: abiertas.length,
    montoPipeline: Math.round(abiertas.reduce((s,o)=>s+crmCRC(o),0)),
    montoPonderado: Math.round(abiertas.reduce((s,o)=>s+crmCRC(o)*(Number(o.probabilidad)||0)/100,0)),
    ganadas: { cantidad: cerr.gn, monto: Math.round(cerr.gm) }, perdidas: cerr.pn,
    vencidos, top: abiertas.slice().sort((a,b)=>crmCRC(b)-crmCRC(a)).slice(0,8) });
}


// ============================================================
//  MÓDULO RECURSOS HUMANOS  (Grupo MARC)
//  -----------------------------------------------------------
//  POST '/' con action rh_* + pin (tienePermiso módulo 'rrhh').
//  Expediente de empleados, planilla CR (CCSS obrero/patrono,
//  provisión de aguinaldo) con asiento contable automático al
//  Financiero, pago de planilla contra banco, y vacaciones.
//  Nivel 'ver' = consultar y registrar ausencias.
//  Nivel 'admin' = empleados, salarios y planilla.
// ============================================================
let RH_READY = false;
async function rhEnsure(env) {
  if (_yaListo.rhEnsure) return; _yaListo.rhEnsure = true;   // v120 ⚡ una vez por instancia
  await finEnsure2(env); // la planilla asienta en el Financiero
  if (RH_READY) return;
  await env.DB.batch([
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS rh_empleados (
      id INTEGER PRIMARY KEY AUTOINCREMENT, nombre TEXT NOT NULL, identificacion TEXT DEFAULT '',
      puesto TEXT DEFAULT '', empresa TEXT DEFAULT 'Grupo', salario_mensual REAL DEFAULT 0,
      tipo_pago TEXT DEFAULT 'quincenal', fecha_ingreso TEXT DEFAULT '', telefono TEXT DEFAULT '',
      correo TEXT DEFAULT '', cuenta_iban TEXT DEFAULT '', notas TEXT DEFAULT '',
      activo INTEGER DEFAULT 1, creado_en TEXT DEFAULT '')`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS rh_planillas (
      id INTEGER PRIMARY KEY AUTOINCREMENT, periodo TEXT NOT NULL, quincena INTEGER,
      estado TEXT DEFAULT 'borrador', total_bruto REAL DEFAULT 0, total_obrero REAL DEFAULT 0,
      total_neto REAL DEFAULT 0, total_patrono REAL DEFAULT 0, total_costo REAL DEFAULT 0,
      asiento_id INTEGER, asiento_pago_id INTEGER, creado_por TEXT DEFAULT '', creado_en TEXT DEFAULT '')`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS rh_planilla_lineas (
      id INTEGER PRIMARY KEY AUTOINCREMENT, planilla_id INTEGER NOT NULL, empleado_id INTEGER,
      nombre TEXT DEFAULT '', bruto REAL DEFAULT 0, ccss_obrero REAL DEFAULT 0, neto REAL DEFAULT 0,
      ccss_patrono REAL DEFAULT 0, aguinaldo REAL DEFAULT 0)`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS rh_ausencias (
      id INTEGER PRIMARY KEY AUTOINCREMENT, empleado_id INTEGER NOT NULL, tipo TEXT DEFAULT 'vacaciones',
      desde TEXT DEFAULT '', hasta TEXT DEFAULT '', dias REAL DEFAULT 0, nota TEXT DEFAULT '',
      creado_por TEXT DEFAULT '', creado_en TEXT DEFAULT '')`),
    env.DB.prepare(`INSERT OR IGNORE INTO config (clave,valor) VALUES ('rh_ccss_obrero','10.67')`),
    env.DB.prepare(`INSERT OR IGNORE INTO config (clave,valor) VALUES ('rh_ccss_patrono','26.67')`),
    env.DB.prepare(`INSERT OR IGNORE INTO fin_cuentas (codigo,nombre,tipo) VALUES ('2-04','CCSS por pagar','pasivo')`),
    env.DB.prepare(`INSERT OR IGNORE INTO fin_cuentas (codigo,nombre,tipo) VALUES ('2-05','Salarios por pagar','pasivo')`),
    env.DB.prepare(`INSERT OR IGNORE INTO modulos (codigo,nombre,descripcion,icono,orden,activo)
      VALUES ('rrhh','Recursos Humanos','Personal y planilla','👥',25,1)`)
  ]);
  RH_READY = true;
}
async function rhRates(env) {
  const o = await env.DB.prepare(`SELECT valor FROM config WHERE clave='rh_ccss_obrero'`).first();
  const p = await env.DB.prepare(`SELECT valor FROM config WHERE clave='rh_ccss_patrono'`).first();
  return { obrero: Number(o && o.valor) || 10.67, patrono: Number(p && p.valor) || 26.67 };
}
