  await rhEnsure(env);
  if (!await tienePermiso(env, body.pin, body.key, 'rrhh', 'ver')) return j({ ok:false, error:'Sin permiso' }, 403);
  const r = (await env.DB.prepare(`SELECT * FROM rh_planillas ORDER BY periodo DESC, quincena DESC LIMIT 60`).all()).results || [];
