// ============================================================
//  PAQUETE DE EMPRESA (v145)
//  Arma el expediente completo de UNA unidad de negocio:
//  clientes, cotizaciones, proyectos, plata y documentos.
//  Sirve para una venta, una auditoría o un banco.
//  Es de solo lectura: no modifica ni un dato.
// ============================================================
const ARCH_PAQ_EMPRESAS = [
  { cod: 'MARCAIRE',       nombre: 'MARCAIRE',            razon: 'IIMC S.A.' },
  { cod: 'METALMARC',      nombre: 'Metal MARC',          razon: 'Equipos y Andamios MARC S.A.' },
  { cod: 'equipos',        nombre: 'Equipos MARC',        razon: 'Equipos y Andamios MARC S.A.' },
  { cod: 'MARCCONSULTING', nombre: 'MARC Consulting',     razon: 'IIMC S.A.' },
];
// modo 'empresa' = la tabla tiene columna empresa
// modo 'sub'     = se llega por el padre (centro de costo o cotización)
// modo 'fija'    = la tabla entera pertenece a una sola unidad
const ARCH_PAQ_SECCIONES = [
  { t: 'crm_clientes',      etq: 'Clientes',                 modo: 'empresa' },
  { t: 'crm_contactos',     etq: 'Contactos',                modo: 'ninguno' },
  { t: 'crm_cotizaciones',  etq: 'Cotizaciones',             modo: 'empresa' },
  { t: 'crm_oportunidades', etq: 'Oportunidades',            modo: 'empresa' },
  { t: 'crm_ofertas',       etq: 'Ofertas firmadas',         modo: 'sub',
    sql: 'consecutivo IN (SELECT consecutivo FROM crm_cotizaciones WHERE empresa = ?)' },
  { t: 'proyectos',         etq: 'Proyectos',                modo: 'empresa' },
  { t: 'cc_centros',        etq: 'Centros de costo',         modo: 'empresa' },
  { t: 'cc_pagos',          etq: 'Tablas de pago',           modo: 'sub',
    sql: 'cc_codigo IN (SELECT codigo FROM cc_centros WHERE empresa = ?)' },
  { t: 'fin_cxc',           etq: 'Cuentas por cobrar',       modo: 'sub',
    sql: 'centro_id IN (SELECT codigo FROM cc_centros WHERE empresa = ?)' },
  { t: 'fin_gastos',        etq: 'Gastos',                   modo: 'empresa' },
  { t: 'fin_movimientos',   etq: 'Movimientos financieros',  modo: 'empresa' },
  { t: 'fab_fabricaciones', etq: 'Fabricaciones',            modo: 'empresa' },
  { t: 'alq_registros',     etq: 'Alquileres',               modo: 'fija', emp: 'equipos' },
  { t: 'mant_certificados', etq: 'Certificados de mantenimiento', modo: 'fija', emp: 'MARCAIRE' },
  { t: 'tra_viajes',        etq: 'Transportes',              modo: 'fija', emp: 'MARCAIRE' },
  { t: 'rh_empleados',      etq: 'Personal',                 modo: 'empresa' },
  { t: 'arch_docs',         etq: 'Documentos del archivo',   modo: 'empresa', extra: 'borrado = 0' },
];

// ¿existe la tabla? (defensivo: si un módulo aún no corrió, no revienta)
async function archPaqExiste(env, tabla) {
  try {
    const r = await env.DB.prepare(
      "SELECT name FROM sqlite_master WHERE type = 'table' AND name = ?").bind(tabla).first();
    return !!r;
  } catch (e) { return false; }
}
function archPaqDonde(sec, empresa) {
  if (sec.modo === 'empresa') return { sql: 'empresa = ?', args: [empresa] };
  if (sec.modo === 'sub')     return { sql: sec.sql, args: [empresa] };
  if (sec.modo === 'fija')    return (sec.emp === empresa)
    ? { sql: '1 = 1', args: [] } : { sql: '1 = 0', args: [] };
  return { sql: '1 = 0', args: [] };
}
function archPaqEmpresa(cod) {
  return ARCH_PAQ_EMPRESAS.find(e => e.cod === String(cod || '')) || null;
}

async function archPaqResumen(env, body) {
  const g = await archAuth(env, body, 'admin'); if (g) return g;
  await archEnsure(env);
  const emp = archPaqEmpresa(body.empresa);
  if (!emp) return j({ ok: false, error: 'Elegí una empresa válida', empresas: ARCH_PAQ_EMPRESAS });
  const secciones = [];
  let filasTotal = 0;
  for (const sec of ARCH_PAQ_SECCIONES) {
    if (!(await archPaqExiste(env, sec.t))) {
      secciones.push({ tabla: sec.t, etiqueta: sec.etq, filas: 0, disponible: false });
      continue;
    }
    const d = archPaqDonde(sec, emp.cod);
    const cond = d.sql + (sec.extra ? ' AND ' + sec.extra : '');
    try {
      const r = await env.DB.prepare('SELECT COUNT(*) c FROM ' + sec.t + ' WHERE ' + cond)
        .bind(...d.args).first();
      const n = Number(r && r.c || 0);
      filasTotal += n;
      secciones.push({ tabla: sec.t, etiqueta: sec.etq, filas: n, disponible: true });
    } catch (e) {
      secciones.push({ tabla: sec.t, etiqueta: sec.etq, filas: 0, disponible: false,
        nota: 'no se pudo leer' });
    }
  }
  let docs = { c: 0, s: 0 };
  try {
    docs = await env.DB.prepare(
      'SELECT COUNT(*) c, COALESCE(SUM(tam),0) s FROM arch_docs WHERE borrado = 0 AND empresa = ?'
    ).bind(emp.cod).first() || docs;
  } catch (e) {}
  await archLog(env, await archQuien(env, body.pin), 'paquete-resumen', emp.cod, '');
  return j({ ok: true, empresa: emp, secciones: secciones, filas_total: filasTotal,
    documentos: Number(docs.c || 0), peso: Number(docs.s || 0),
    generado_en: crParts().iso, version: MARC_VERSION });
}

async function archPaqDatos(env, body) {
  const g = await archAuth(env, body, 'admin'); if (g) return g;
  await archEnsure(env);
  const emp = archPaqEmpresa(body.empresa);
  if (!emp) return j({ ok: false, error: 'Elegí una empresa válida' });
  const sec = ARCH_PAQ_SECCIONES.find(x => x.t === String(body.tabla || ''));
  if (!sec) return j({ ok: false, error: 'Sección no reconocida' });
  if (!(await archPaqExiste(env, sec.t))) return j({ ok: true, filas: [], total: 0, no_disponible: true });
  const d = archPaqDonde(sec, emp.cod);
  const cond = d.sql + (sec.extra ? ' AND ' + sec.extra : '');
  const lim = Math.min(500, Math.max(1, Number(body.limite) || 300));
  const off = Math.max(0, Number(body.desplazamiento) || 0);
  try {
    const tot = await env.DB.prepare('SELECT COUNT(*) c FROM ' + sec.t + ' WHERE ' + cond)
      .bind(...d.args).first();
    const r = await env.DB.prepare('SELECT * FROM ' + sec.t + ' WHERE ' + cond
      + ' LIMIT ? OFFSET ?').bind(...d.args, lim, off).all();
    return j({ ok: true, tabla: sec.t, etiqueta: sec.etq, filas: r.results || [],
      total: Number(tot && tot.c || 0), limite: lim, desplazamiento: off });
  } catch (e) {
    return j({ ok: false, error: 'No pude leer ' + sec.t + ': ' + String(e && e.message || e) });
  }
}

// Enlaces firmados de todos los documentos de la empresa, por tandas.
async function archPaqEnlaces(env, body) {
  const g = await archAuth(env, body, 'admin'); if (g) return g;
  await archEnsure(env);
  const emp = archPaqEmpresa(body.empresa);
  if (!emp) return j({ ok: false, error: 'Elegí una empresa válida' });
  const dias = Math.min(365, Math.max(1, Number(body.dias) || 90));
  const lim = Math.min(200, Math.max(1, Number(body.limite) || 100));
  const off = Math.max(0, Number(body.desplazamiento) || 0);
  const tot = await env.DB.prepare(
    'SELECT COUNT(*) c FROM arch_docs WHERE borrado = 0 AND empresa = ?').bind(emp.cod).first();
  const r = await env.DB.prepare(
    `SELECT clave,nombre,modulo,carpeta,cliente,referencia,anio,tam,subido_en
     FROM arch_docs WHERE borrado = 0 AND empresa = ?
     ORDER BY carpeta, subido_en LIMIT ? OFFSET ?`).bind(emp.cod, lim, off).all();
  const filas = [];
  for (const d of (r.results || [])) {
    filas.push(Object.assign({}, d, { url: await archEnlaceDe(env, d.clave, dias) }));
  }
  const total = Number(tot && tot.c || 0);
  if (off === 0) await archLog(env, await archQuien(env, body.pin), 'paquete-enlaces', emp.cod,
    total + ' documentos · enlaces por ' + dias + ' días');
  return j({ ok: true, documentos: filas, total: total, vence_dias: dias,
    desplazamiento: off, hay_mas: (off + filas.length) < total });
}

