// Regla de líneas de negocio del grupo (definida por Manu):
//   Proyectos y Mantenimiento -> IIMC S.A. (MARCAIRE)
//   Ductos                    -> MARC S.A. (Metal MARC, taller)
//   Venta insumos / Alquileres-> MARC S.A. (Equipos MARC)
function lineaDeNegocio(tipoServicio) {
  const t = String(tipoServicio || '').trim().toLowerCase();
  if (t === 'ductos') return { empresa: 'METALMARC', razon: 'MARC S.A.' };
  if (t.includes('insumo') || t.includes('alquiler')) return { empresa: 'EQUIPOS', razon: 'MARC S.A.' };
  return { empresa: 'MARCAIRE', razon: 'IIMC S.A.' }; // Proyectos, Mantenimiento y por defecto
}
