  viaje_recogido:     'HX475f7dc7fd394805ac94b3e7ee29b8f6', // {{1}}viaje  → solicitante
  viaje_entregado:    'HX064d2e6f7b89d588d6f620281c46316a', // {{1}}viaje  → solicitante
