// v136 · App de Choferes embebida (build 23jul-CH6). Se sirve tal cual.
// v144 · La app de Choferes vive en Pages (viajeschoferes.marcaire.com).
// El worker ya no la lleva embebida; /choferes redirige al sitio real.
const CHOFERES_URL = 'https://viajeschoferes.marcaire.com';

export default {
  // Cron diario (Worker → Configuración → Desencadenadores → Cron, ej. "0 13 * * *" = 7:00 a.m. CR):
  // revisa vencimientos y envía los avisos automáticamente.
  async scheduled(event, env, ctx) {
    // v101 💱 el tipo de cambio primero: los avisos de cobro lo necesitan al día.
    // Esto NO manda correos, solo actualiza el número: se deja siempre encendido.
    try { console.log('cron tipo de cambio:', JSON.stringify(await tcBccrTraer(env))); }
    catch (e) { console.log('cron tc:', e.message); }

    // v107 🛑 INTERRUPTOR DE CORREOS AUTOMÁTICOS. Nace APAGADO: mientras el
    // sistema esté en pruebas NADIE recibe correos automáticos. Se enciende a
    // propósito desde Financiero → Config cuando todo esté probado. Un cliente
    // real recibió un cobro por algo sin facturar: hasta entender por qué, esto
    // queda mudo. El tipo de cambio (arriba) sigue corriendo porque no manda nada.
    // v125 - respaldo diario de tablas de pagos a R2. Va ANTES del interruptor
    // de correos a proposito: es proteccion de datos, no mensajeria, y debe
    // correr siempre aunque los correos esten apagados.
    try { console.log('cron respaldo pagos:', JSON.stringify(await pagosRespaldoDiario(env))); }
    catch (e) { console.log('cron respaldo pagos ERROR:', e.message); }

    const correosOn = await cfgFlag(env, 'correos_automaticos', false);
    if (!correosOn) { console.log('cron: correos automáticos APAGADOS (config correos_automaticos=false)'); return; }
    try { if (env.RESEND_API_KEY) await alqEnviarAvisos(env); } catch (e) { console.log('cron avisos:', e.message); }
    try { if (env.RESEND_API_KEY_COBROS || env.RESEND_API_KEY) await finCxcAvisos(env); } catch (e) { console.log('cron cobros CxC:', e.message); }
  },
  async fetch(request, env) {
    if (request.method === 'OPTIONS') return new Response(null, { headers: cors });
    const url = new URL(request.url);

    if (request.method === 'GET') {
      // v136 - la app de Choferes se sirve desde el worker
      if (url.pathname === '/choferes') {
        return Response.redirect(CHOFERES_URL, 302);
      }
      // v125 - la pantalla de rescate ya NO es publica: exige la misma clave
      // que el resto de las herramientas de administracion.
      if (url.pathname === '/rescate') {
        if (!segClaveOk(env, url.searchParams.get('key'))) {
          return new Response(paginaClaveRescate(), { status: 403,
            headers: { 'content-type': 'text/html; charset=utf-8' } });
        }
        return paginaRescate(segClaveReal(env));
      }
      if (url.pathname === '/setup') {
        if (url.searchParams.get('key') !== SETUP_KEY) return j({ ok: false, error: 'Clave de instalación incorrecta' }, 403);
        try { return await runSetup(env); } catch (e) { return j({ ok: false, error: 'Error instalando: ' + e.message }, 500); }
      }
      // v98 🩻 RADIOGRAFÍA — se abre en el navegador (cero Terminal).
      // Solo LEE. La limpieza queda fuera de GET a propósito: un enlace que
      // borra se guarda en el historial y se puede re-disparar sin querer.
      if (url.pathname === '/radiografia') {
        // La clave del enlace vale si coincide con el SECRETO de Cloudflare o
        // con la constante. Y hacia adentro se manda LA MISMA que espera
        // tienePermiso: `env.SETUP_KEY || SETUP_KEY`. Si se manda solo la
        // constante teniendo el secreto puesto, el propio worker se rechaza.
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { return await finRadiografia(env, { key: segClaveReal(env) }); }
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v98 🧹 SIMULACIÓN de la limpieza (tampoco borra: solo muestra el listado)
      if (url.pathname === '/cxc-simular-limpieza') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { return await finCxcLimpiar(env, { key: segClaveReal(env) }); }   // sin confirmar → simula
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v102 🔎 Buscar un CABYS desde el navegador
      //   /cabys?key=…&q=aire%20acondicionado   /cabys?key=…&codigo=5330100010000
      //   agregar &crudo=1 para ver la respuesta tal cual la manda Hacienda
      if (url.pathname === '/cabys') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { return await cabysBuscar(env, { key: segClaveReal(env),
          q: url.searchParams.get('q') || '', codigo: url.searchParams.get('codigo') || '',
          top: url.searchParams.get('top') || 10,
          crudo: url.searchParams.get('crudo') === '1',
          forzar_hacienda: url.searchParams.get('hacienda') === '1' }); }
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v102 🏢 Actividades económicas de las dos razones sociales (?ver=1 no guarda)
      if (url.pathname === '/actividades') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { return await feActividades(env, { key: segClaveReal(env),
          solo_ver: url.searchParams.get('ver') === '1',
          crudo: url.searchParams.get('crudo') === '1' }); }
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v107 🚫 Anular una cuenta por cobrar desde el navegador
      //   /cxc-anular?key=…&id=5                    → vista previa (no toca nada)
      //   /cxc-anular?key=…&id=5&motivo=...&ok=1    → anula de verdad
      if (url.pathname === '/cxc-anular') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { return await cxcAnular(env, { key: segClaveReal(env),
          id: url.searchParams.get('id'),
          confirmar: url.searchParams.get('ok') === '1',
          motivo: url.searchParams.get('motivo') || '',
          forzar_alquiler: url.searchParams.get('forzar') === '1' }); }
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v107 🛑 Apagar/encender correos automáticos desde el navegador (emergencia)
      //   /correos?key=…          → ver el estado
      //   /correos?key=…&apagar=1 → APAGAR ya   ·   &encender=1 → encender
      if (url.pathname === '/correos') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        let enc;
        if (url.searchParams.get('apagar') === '1') enc = false;
        else if (url.searchParams.get('encender') === '1') enc = true;
        try { return await correosAutomaticos(env, { key: segClaveReal(env), encender: enc }); }
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v101 🤖 Traer el tipo de cambio del BCCR ya mismo (?ver=1 solo consulta)
      if (url.pathname === '/tipo-cambio-bccr') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { return await finTcBccr(env, { key: segClaveReal(env),
          solo_ver: url.searchParams.get('ver') === '1' }); }
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v100 💱 Poner el tipo de cambio desde el navegador (sin Terminal).
      //   /tipo-cambio?key=…            → lo muestra
      //   /tipo-cambio?key=…&venta=453.07 → lo pone (valor de VENTA del BCCR)
      if (url.pathname === '/tipo-cambio') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        const v = url.searchParams.get('venta');
        try { return await finTipoCambio(env, { key: segClaveReal(env),
          venta: v === null ? undefined : v, fecha: url.searchParams.get('fecha') || undefined }); }
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v98 🔧 SIMULACIÓN de la reparación del tipo de cambio (no cambia nada)
      // v111 — crear una CUENTA DE DINERO desde el navegador (están arrancando).
      //   /cuenta?key=…                                       → lista las que hay
      //   /cuenta?key=…&nombre=BAC%20Dolares&moneda=USD&ok=1  → la crea
      //   tipo opcional: &tipo=banco (por defecto) o &tipo=efectivo
      if (url.pathname === '/cuenta') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try {
          await finEnsure(env);
          if (url.searchParams.get('ok') !== '1') {
            const bancos = (await env.DB.prepare(`SELECT id,nombre,moneda,tipo FROM fin_bancos ORDER BY id`).all()).results || [];
            return j({ ok: true, para_crear: 'agregá &nombre=&moneda=USD&ok=1  (tipo opcional: banco|efectivo)',
              cuentas_que_hay: bancos });
          }
          const nombre = (url.searchParams.get('nombre') || '').trim();
          if (!nombre) return j({ ok: false, error: 'Decí el nombre de la cuenta (&nombre=)' });
          return await finBancoGuardar(env, { key: segClaveReal(env), banco: {
            nombre, moneda: (url.searchParams.get('moneda') || 'CRC').toUpperCase(),
            tipo: url.searchParams.get('tipo') || 'banco',
            empresa: url.searchParams.get('empresa') || 'Grupo' } });
        } catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v113 — LISTAR centros (para ver códigos antes de fusionar/mover)
      //   /centros?key=…                 → todos los centros con código, nombre, estado
      //   /centros?key=…&buscar=MANMART  → solo los que digan MANMART
      if (url.pathname === '/centros') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try {
          await ccEnsure(env);
          const q = (url.searchParams.get('buscar') || '').trim().toUpperCase();
          const rows = (await env.DB.prepare(`SELECT c.codigo, c.nombre, c.cliente, c.empresa, c.estado,
              (SELECT id FROM fin_centros f WHERE f.codigo=c.codigo) AS centro_id,
              (SELECT COUNT(*) FROM cc_movimientos m WHERE m.cc_codigo=c.codigo) AS movs,
              (SELECT COUNT(*) FROM crm_cotizaciones q WHERE q.cc_codigo=c.codigo) AS cots,
              (SELECT COUNT(*) FROM fin_cxc x WHERE x.centro_id=(SELECT id FROM fin_centros f2 WHERE f2.codigo=c.codigo)) AS cxc
            FROM cc_centros c ORDER BY c.codigo`).all()).results || [];
          // buscar por código, nombre, cliente O por centro_id exacto (ej: id=130)
          const idBusca = url.searchParams.get('id');
          const lista = rows.filter(r => {
            if (idBusca) return String(r.centro_id) === String(idBusca);
            return !q || (r.codigo||'').toUpperCase().includes(q) ||
              (r.nombre||'').toUpperCase().includes(q) || (r.cliente||'').toUpperCase().includes(q);
          });
          return j({ ok: true, total: lista.length, centros: lista });
        } catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v113 — FUSIONAR dos centros en uno (unir todo el MANMART, etc.)
      //   /fusionar?key=…&destino=CC-2026-0151&origen=CC-2026-M013         → simula
      //   /fusionar?key=…&destino=CC-2026-0151&origen=CC-2026-M013&ok=1    → fusiona
      //   el DESTINO es el que se queda; el ORIGEN se absorbe y queda 'fusionado'
      if (url.pathname === '/fusionar') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { return await ccFusionar(env, { key: segClaveReal(env),
          destino: url.searchParams.get('destino'),
          origen: url.searchParams.get('origen'),
          confirmar: url.searchParams.get('ok') === '1' }); }
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v118 — agregar un movimiento a mano a un centro (ej: el $9117 al MANMART)
      //   /agregar-mov?key=…&cc=CC-2026-0151&monto=9117&desc=Extra&extra=1&ok=1
      if (url.pathname === '/agregar-mov') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        if (url.searchParams.get('ok') !== '1')
          return j({ ok: true, ayuda: 'agregá &cc=&monto=&desc=&extra=1&moneda=USD&tipo=ingreso&ok=1' });
        try { return await ccMovAgregar(env, { key: segClaveReal(env),
          cc_codigo: url.searchParams.get('cc'), monto: url.searchParams.get('monto'),
          descripcion: url.searchParams.get('desc'), moneda: url.searchParams.get('moneda') || 'USD',
          tipo: url.searchParams.get('tipo') || 'ingreso',
          como_extra: url.searchParams.get('extra') === '1' }); }
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v113 — mover un monto de un CC a otro como EXTRA
      //   /mover-extra?key=…&origen=CC-TALLER&destino=CC-MANMART&monto=9117            → simula
      //   /mover-extra?key=…&origen=CC-TALLER&destino=CC-MANMART&monto=9117&ok=1       → mueve
      //   si hay varios del mismo monto, usá &mov=ID en vez de &monto=
      if (url.pathname === '/mover-extra') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { return await ccMoverExtra(env, { key: segClaveReal(env),
          cc_origen: url.searchParams.get('origen'),
          cc_destino: url.searchParams.get('destino'),
          monto: url.searchParams.get('monto'),
          mov_id: url.searchParams.get('mov'),
          confirmar: url.searchParams.get('ok') === '1' ? 'MOVER' : undefined }); }
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v113 — reparar el MONTO de un centro en todos lados (mov, pago, CxC, asiento)
      //   /reparar-monto?key=…&cc=CC-2026-0146&viejo=112450&nuevo=106820         → simula
      //   /reparar-monto?key=…&cc=CC-2026-0146&viejo=112450&nuevo=106820&ok=1    → repara
      if (url.pathname === '/reparar-monto') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { return await ccRepararMonto(env, { key: segClaveReal(env),
          cc_codigo: url.searchParams.get('cc'),
          monto_viejo: url.searchParams.get('viejo'),
          monto_nuevo: url.searchParams.get('nuevo'),
          confirmar: url.searchParams.get('ok') === '1' ? 'REPARAR' : undefined }); }
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v109 — registrar un ANTICIPO desde el navegador (sin el Financiero).
      //   /anticipo?key=…                         → lista tus cuentas de dinero y centros
      //   /anticipo?key=…&monto=3000&banco=ID&cc=CC-2026-0126&cliente=EDIFICIO%20STRATA
      //     &detalle=Anticipo%2030%25&ok=1        → registra el anticipo (pasivo)
      //   agregá &facturado=1 solo si el cliente pidió factura del anticipo
      if (url.pathname === '/anticipo') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try {
          await finEnsure(env); await finEnsure2(env);
          if (url.searchParams.get('ok') !== '1') {
            // Mostrar las cuentas de dinero y los centros del Strata para elegir
            const bancos = (await env.DB.prepare(`SELECT id,nombre,moneda FROM fin_bancos ORDER BY id`).all()).results || [];
            const centros = (await env.DB.prepare(`SELECT id,codigo,nombre,cliente FROM fin_centros
              WHERE UPPER(cliente) LIKE '%STRATA%' OR UPPER(nombre) LIKE '%STRATA%' ORDER BY id`).all()).results || [];
            return j({ ok: true, para_registrar: 'agregá &monto=&banco=ID&cc=CODIGO&cliente=&detalle=&ok=1',
              cuentas_de_dinero: bancos.length ? bancos : 'NO HAY — creá una cuenta primero',
              centros_del_strata: centros });
          }
          // v111 — si en vez de un banco existente das &banco_nuevo=NOMBRE, se
          // crea la cuenta al vuelo (en la moneda del anticipo) y se usa esa.
          let bancoId = url.searchParams.get('banco');
          const bancoNuevo = (url.searchParams.get('banco_nuevo') || '').trim();
          const monedaAnt = (url.searchParams.get('moneda') || 'USD').toUpperCase();
          if (!bancoId && bancoNuevo) {
            await finBancoGuardar(env, { key: segClaveReal(env), banco: {
              nombre: bancoNuevo, moneda: monedaAnt, tipo: url.searchParams.get('tipo') || 'banco',
              empresa: url.searchParams.get('empresa') || 'Grupo' } });
            const nb = await env.DB.prepare(`SELECT id FROM fin_bancos WHERE nombre=? ORDER BY id DESC LIMIT 1`).bind(bancoNuevo).first();
            bancoId = nb && nb.id;
          }
          return await finAnticipoCrear(env, { key: segClaveReal(env), anticipo: {
            monto: url.searchParams.get('monto'),
            banco_id: bancoId,
            cc_codigo: url.searchParams.get('cc') || undefined,
            cliente: url.searchParams.get('cliente') || '',
            detalle: url.searchParams.get('detalle') || '',
            moneda: monedaAnt,
            facturado: url.searchParams.get('facturado') === '1',
            empresa: url.searchParams.get('empresa') || 'MARCAIRE' } });
        } catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // v109 — reparar el tipo de cambio de CxC ESPECÍFICAS.
      //   /tc-simular-reparacion?key=…                 → simula TODAS las rotas
      //   /tc-simular-reparacion?key=…&ids=2           → simula solo la #2
      //   /tc-simular-reparacion?key=…&ids=2&ok=1      → REPARA solo la #2
      //   ids acepta varias separadas por coma: ids=2,4
      if (url.pathname === '/tc-simular-reparacion' || url.pathname === '/reparar-tc') {
        if (!segClaveOk(env, url.searchParams.get('key'))) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        const idsTxt = url.searchParams.get('ids');
        const ids = idsTxt ? idsTxt.split(',').map(s => Number(s.trim())).filter(Boolean) : undefined;
        try { return await finRepararTipoCambio(env, { key: segClaveReal(env),
          tipo_cambio: url.searchParams.get('tc'),
          ids,
          confirmar: url.searchParams.get('ok') === '1' ? 'REPARAR' : undefined }); }
        catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // WhatsApp: cargar contactos conocidos de un solo toque
      if (url.pathname === '/wa/seed') {
        if (url.searchParams.get('key') !== SETUP_KEY) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { return await waSeed(env); } catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      if (url.pathname === '/sincronizar-cc') {
        if (url.searchParams.get('key') !== SETUP_KEY) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { return await sincronizarCC(env); } catch (e) { return j({ ok: false, error: 'Error sincronizando: ' + e.message }, 500); }
      }
      if (url.pathname === '/sembrar-vendedores') {
        if (url.searchParams.get('key') !== SETUP_KEY) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { const r = await sembrarVendedores(env); return j({ ok: true, ...r }); } catch (e) { return j({ ok: false, error: 'Error sembrando: ' + e.message }, 500); }
      }
      if (url.pathname === '/importar-datos') {
        if (url.searchParams.get('key') !== SETUP_KEY) return j({ ok: false, error: 'Clave incorrecta' }, 403);
        try { return await importarDatosIniciales(env); } catch (e) { return j({ ok: false, error: 'Error importando: ' + e.message }, 500); }
      }
      // Archivos guardados en R2, servidos por el propio worker (PDFs, etc.)
      if (url.pathname.startsWith('/archivo/')) {
        if (!env.ARCHIVOS) return j({ ok: false, error: 'R2 no configurado (binding ARCHIVOS)' }, 400);
        const key = decodeURIComponent(url.pathname.slice('/archivo/'.length));
        // v61: variantes tolerantes por si el enlace viene con mañas
        const variantes = [key, key.replace(/^\/+/, ''), key.replace(/^archivo\//, ''), key.replace(/^\/?archivo\//, '')];
        try { const k2 = decodeURIComponent(key); if (!variantes.includes(k2)) variantes.push(k2); } catch (e) {}
        let obj = null, usada = '';
        for (const k of variantes) { if (!k) continue; obj = await env.ARCHIVOS.get(k); if (obj) { usada = k; break; } }
        if (!obj) return j({ ok: false, error: 'Archivo no encontrado', clave: key, probadas: variantes }, 404);
        // v63 — archivos privados: sin caché público y, en estricta, token o PIN
        const privado = segEsPrivado(usada);
        if (privado && segModo(env) === 'estricta') {
          const okToken = await segTokenValido(env, usada, url.searchParams.get('t'), url.searchParams.get('e'));
          const okPin = okToken ? true : await segPinValido(env, url.searchParams.get('pin'));
          if (!okToken && !okPin) return j({ ok: false, error: 'Archivo privado: falta token o PIN (pedí un enlace con archivo_token)' }, 403);
        }
        let ct = (obj.httpMetadata && obj.httpMetadata.contentType) || 'application/octet-stream';
        const cabeceras = { ...cors, 'cache-control': privado ? 'no-store, private' : 'public, max-age=31536000' };
        // v63 — tipos que ejecutan código se sirven como descarga neutra (anti XSS almacenado)
        if (segMimePeligroso(ct)) { ct = 'application/octet-stream'; cabeceras['content-disposition'] = 'attachment'; }
        cabeceras['content-type'] = ct;
        return new Response(obj.body, { headers: cabeceras });
      }
      // TRANSPORTES (v22): GET /transportes → estado + próximo consecutivo STM
      if (url.pathname === '/transportes') {
        try {
          await traEnsure(env);
          const c = await env.DB.prepare("SELECT valor FROM contadores WHERE nombre='transportes'").first();
          return j({ ok: true, servicio: 'MARC-ERP Transportes', nextNumber: c ? (Number(c.valor) + 1) : null });
        } catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // Cotizador Pruebas de Presión (MARC Consulting): GET /cotpresion?action=...
      if (url.pathname === '/cotpresion') {
        try {
          const a = url.searchParams.get('action') || '';
          if (a === 'peek')       return await cotpPeek(env);
          if (a === 'reserve')    return await cotpReserve(env);
          if (a === 'listar')     return await cotpListar(env);
          if (a === 'setcounter') return await cotpSetCounter(env, url.searchParams);
          if (a === 'verifyaccess')   return await mcVerify(env, url.searchParams);
          if (a === 'users')          return await mcUsers(env, url.searchParams);
          if (a === 'saveuser')       return await mcSaveUser(env, url.searchParams);
          if (a === 'deluser')        return await mcDelUser(env, url.searchParams);
          if (a === 'changeadminpin') return await mcChangeAdminPin(env, url.searchParams);
          return j({ ok: false, error: 'acción desconocida: ' + a }, 400);
        } catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // Conteo de Ductos: API compatible con el Apps Script (GET)
      if (url.pathname === '/conteo') {
        try { return await handleConteoGet(env, url.searchParams); }
        catch (e) { return j({ success: false, error: e.message }, 500); }
      }
      if (url.pathname === '/reservar') {
        const r = await env.DB.prepare("UPDATE contadores SET valor = valor + 1 WHERE nombre='global' RETURNING valor").first();
        return j({ ok: true, nextNumber: r ? r.valor : null });
      }
      // Módulo MANTENIMIENTO (compat Apps Script): GET /?action=list|cliente|getUsers   v19.3
      const mAct = url.searchParams.get('action') || '';
      // Ajuste administrativo del consecutivo de Mantenimiento (requiere clave)
      if (mAct === 'setcounter' || mAct === 'fixcounter') {
        if (url.searchParams.get('key') !== SETUP_KEY) return j({ ok: false, error: 'clave incorrecta' }, 403);
        await mantEnsure(env);
        if (mAct === 'setcounter') {
          const v = parseInt(url.searchParams.get('value') || '0', 10);
          if (!v || v < 1) return j({ ok: false, error: 'value inválido' }, 400);
          await env.DB.prepare("UPDATE contadores SET valor = ? WHERE nombre = 'mantenimiento'").bind(v).run();
          return j({ ok: true, contador: 'mantenimiento', valor: v, proximo: 'SGM-' + v });
        }
        // fixcounter: recalcula el contador desde el número real más alto guardado
        const r = await env.DB.prepare("SELECT MAX(CAST(REPLACE(numero,'SGM-','') AS INTEGER)) AS mx FROM mant_certificados WHERE numero LIKE 'SGM-%' AND trashed = 0").first();
        const mx = (r && r.mx) ? r.mx : 0;
        const nuevo = mx + 1;
        await env.DB.prepare("UPDATE contadores SET valor = ? WHERE nombre = 'mantenimiento'").bind(nuevo).run();
        return j({ ok: true, maxReal: mx, nuevoContador: nuevo, proximo: 'SGM-' + nuevo });
      }
      // Diagnóstico: qué campos trae realmente un certificado (columnas vs contenido).
      // Uso: ?action=mant_diag&key=marc2026&numero=SGM-326   (omitir numero = el más reciente)
      if (mAct === 'mant_diag') {
        if (url.searchParams.get('key') !== SETUP_KEY) return j({ ok: false, error: 'clave incorrecta' }, 403);
        await mantEnsure(env);
        const num = url.searchParams.get('numero');
        const row = num
          ? await env.DB.prepare('SELECT * FROM mant_certificados WHERE numero = ?').bind(num).first()
          : await env.DB.prepare('SELECT * FROM mant_certificados WHERE trashed = 0 ORDER BY actualizado_en DESC LIMIT 1').first();
        if (!row) return j({ ok: false, error: 'certificado no encontrado' }, 404);
        const columnas = {};
        for (const k of ['numero', 'cliente', 'fecha', 'visita', 'autor', 'tipo_mantenimiento', 'tipo_equipo', 'equipos', 'pdf_url']) {
          columnas[k] = row[k] || '(vacío)';
        }
        let contenido = {}, claves = [];
        try {
          const p = JSON.parse(row.payload || '{}');
          claves = Object.keys(p);
          const resumir = v => v == null ? '(vacío)'
            : Array.isArray(v) ? '[' + v.length + ' elementos]'
            : (typeof v === 'object') ? '{' + Object.keys(v).join(', ') + '}'
            : String(v).slice(0, 60) || '(vacío)';
          for (const k of claves) contenido[k] = resumir(p[k]);
          if (p.cliente && typeof p.cliente === 'object') {
            contenido['cliente.*'] = {};
            for (const k of Object.keys(p.cliente)) contenido['cliente.*'][k] = resumir(p.cliente[k]);
          }
        } catch (e) { contenido = { error: 'payload ilegible: ' + e.message }; }
        return j({ ok: true, columnasEnLaTabla: columnas, clavesDelCertificado: claves, contenido });
      }
      if (mAct === 'list' || mAct === 'cliente' || mAct === 'getUsers' || mAct === 'reserve') {
        try {
          await mantEnsure(env);
          if (mAct === 'list')     return await mantList(env);
          if (mAct === 'cliente')  return await mantCliente(env, url.searchParams.get('nombre'));
          if (mAct === 'getUsers') return await mantGetUsers(env);
          if (mAct === 'reserve')  return await mantReserve(env);
        } catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // BODEGA (v20): reserva del consecutivo SBM (?reservar=1, contador 'global')
      if (url.searchParams.get('reservar')) {
        await bodEnsure(env);
        const r = await env.DB.prepare("UPDATE contadores SET valor = valor + 1 WHERE nombre='global' RETURNING valor").first();
        return j({ ok: true, nextNumber: r ? r.valor : null });
      }
      // BODEGA (v20): rastreador y dashboard por GET (la app los llama con querystring)
      if (mAct === 'todas' || mAct === 'misSolicitudes' || mAct === 'filtrosDisponibles' || mAct === 'dashboard') {
        try {
          await bodEnsure(env);
          const p = Object.fromEntries(url.searchParams.entries());
          if (mAct === 'todas')             return await bodTodas(env);
          if (mAct === 'misSolicitudes')    return await bodMis(env, p.email);
          if (mAct === 'filtrosDisponibles') return await bodFiltros(env);
          return await bodDashboard(env, p);
        } catch (e) { return j({ ok: false, error: e.message }, 500); }
      }
      // estado
      let tablas = null;
      try { const r = await env.DB.prepare("SELECT COUNT(*) AS n FROM sqlite_master WHERE type='table'").first(); tablas = r.n; } catch (e) {}
      // v19.5 — Consecutivo de Mantenimiento: el frontend lo consume (data.nextNumber)
      // para no repetir números. Antes NO se devolvía y el número quedaba pegado.
      let nextNumber = null;
      try { const c = await env.DB.prepare("SELECT valor FROM contadores WHERE nombre = 'mantenimiento'").first(); if (c && c.valor != null) nextNumber = c.valor; } catch (e) {}
      // v150 — La versión va en la respuesta de estado. Verificar un despliegue
      // no debería exigir clave ni recordar el nombre de una acción: se abre la
      // raíz del worker en el navegador y ahí está.
      let cron = null;
      try {
        const c = await env.DB.prepare(
          "SELECT COUNT(*) AS n FROM sqlite_master WHERE type='table' AND name LIKE 'cron\\_%' ESCAPE '\\'").first();
        cron = c ? c.n : null;
      } catch (e) {}
      return j({ ok: true, servicio: 'MARC-ERP API', version: MARC_VERSION,
        tablas, tablas_cronogramas: cron, r2: !!env.ARCHIVOS, nextNumber });
    }

    // TRANSPORTES (v22): POST /transportes con {accion:...}
    if (url.pathname === '/transportes') {
      try {
        const b = await request.json();
        await traEnsure(env);
        return await traHandle(env, b);
      } catch (e) { return j({ ok: false, error: e.message }, 500); }
    }
    // Cotizador Pruebas de Presión: guardar cotización + PDF (POST JSON)
    if (url.pathname === '/cotpresion') {
      try {
        const b = await request.json();
        if ((b.action || '') === 'guardar') return await cotpGuardar(env, b);
        return j({ ok: false, error: 'acción desconocida' }, 400);
      } catch (e) { return j({ ok: false, error: e.message }, 500); }
    }
    // Conteo de Ductos: subida de PDFs y acciones con cuerpo (POST FormData)
    if (url.pathname === '/conteo') {
      try { return await conteoPost(env, request); }
      catch (e) { return j({ success: false, error: e.message }, 500); }
    }

    // Webhook de ENTRADA de WhatsApp (Twilio manda form-urlencoded, no JSON)
    if (url.pathname === '/wa/inbound') {
      try { return await waInbound(env, request); }
      catch (e) { console.log('wa inbound', e.message); return twiml('Ups, hubo un detalle. Proba de nuevo.'); }
    }

    // POST
    let body = {};
    try { body = await request.json(); } catch (e) { return j({ ok: false, error: 'JSON inválido' }, 400); }
    // Módulo MANTENIMIENTO (compat Apps Script): POST sin action   v19.3
    if (!body.action && !body.accion) {
      try {
        if (body.guardarUsuarios) { await mantEnsure(env); return await mantSaveUsers(env, body); }
        if (body.certData)        { await mantEnsure(env); return await mantSave(env, body); }
        if (body.solicitudData)   { await bodEnsure(env);  return await bodCrear(env, body); }   // v20 Bodega
      } catch (e) { return j({ ok: false, error: e.message }, 500); }
    }
    try { return await handle(env, body.action || body.accion, body); }
    catch (err) { console.log('ERROR', body.action, err.message, err.stack); return j({ ok: false, error: err.message || 'Error interno' }, 500); }
  },
};


// ============================================================
//  MÓDULO BODEGA (bod_) — v20 (07-jul-2026)
//  ------------------------------------------------------------
//  Integra la app "Bodegas MARC — Solicitud Interna" al núcleo.
//  Contrato 100% compatible con el frontend existente:
//   POST {pdfBase64,filename,solicitudData}    → crear solicitud SBM (+PDF a R2 bodega/)
//   GET/POST action=todas|misSolicitudes|filtrosDisponibles|dashboard → rastreador
//   POST accion=cambiarEstado                  → panel de bodega (Roberto)
//   POST action=stockMapa | accion=ajustarStock → stock con kardex
//   POST action=activosListar | listarProyectos
//   GET  ?reservar=1                           → consecutivo atómico (contador 'global')
//   POST bod_importar / bod_setcounter (clave) → migración desde bodegas-marc-ap
//  Avisos por correo: Resend con env.RESEND_API_KEY (si falta, NO bloquea).
// ============================================================
let BOD_READY = false;
async function bodEnsure(env) {
  if (_yaListo.bodEnsure) return; _yaListo.bodEnsure = true;   // v120 ⚡ una vez por instancia
  if (BOD_READY) return;
  const stmts = [
    `CREATE TABLE IF NOT EXISTS bod_solicitudes (
      numero TEXT PRIMARY KEY, estado TEXT DEFAULT 'pendiente',
      solicitante TEXT, email TEXT, proyecto TEXT, centro_costo TEXT,
      empresa_costo TEXT, marca TEXT, fecha TEXT, prioridad TEXT,
      payload TEXT NOT NULL, pdf_url TEXT, historial TEXT,
      creado_en TEXT, actualizado_en TEXT )`,
    `CREATE INDEX IF NOT EXISTS idx_bodsol_estado ON bod_solicitudes(estado)`,
    `CREATE INDEX IF NOT EXISTS idx_bodsol_email ON bod_solicitudes(email)`,
    `CREATE TABLE IF NOT EXISTS bod_stock (
      codigo TEXT PRIMARY KEY, descripcion TEXT, unidad TEXT,
      actual REAL DEFAULT 0, minimo REAL DEFAULT 0, actualizado_en TEXT )`,
    `CREATE TABLE IF NOT EXISTS bod_stock_mov ( id INTEGER PRIMARY KEY AUTOINCREMENT,
      codigo TEXT, antes REAL, despues REAL, motivo TEXT, por TEXT, fecha TEXT, ts TEXT )`,
    `CREATE TABLE IF NOT EXISTS bod_activos ( id INTEGER PRIMARY KEY AUTOINCREMENT,
      codigo TEXT, nombre TEXT, estado TEXT, asignado TEXT, payload TEXT, actualizado_en TEXT )`,
    `CREATE TABLE IF NOT EXISTS bod_proyectos ( codigo TEXT, nombre TEXT, razon_social TEXT,
      activo INTEGER DEFAULT 1, PRIMARY KEY (codigo, razon_social) )`,
    `CREATE TABLE IF NOT EXISTS bod_compras ( id INTEGER PRIMARY KEY AUTOINCREMENT,
      referencia TEXT, solicitud TEXT, items TEXT, motivo TEXT,
      estado TEXT DEFAULT 'pendiente', creado_en TEXT )`,
    `INSERT OR IGNORE INTO contadores (nombre,valor) VALUES ('global', 1)`,
    `INSERT OR IGNORE INTO contadores (nombre,valor) VALUES ('compras', 1000)`,
    // --- v21: sitio completo ---
    `ALTER TABLE bod_solicitudes ADD COLUMN origen TEXT DEFAULT ''`,
    `ALTER TABLE bod_solicitudes ADD COLUMN parcial INTEGER DEFAULT 0`,
    `ALTER TABLE bod_stock_mov ADD COLUMN ref TEXT`,
    `ALTER TABLE bod_compras ADD COLUMN pdf_url TEXT`,
    `ALTER TABLE bod_compras ADD COLUMN datos TEXT`,
    `CREATE TABLE IF NOT EXISTS bod_stock2 (
      codigo TEXT NOT NULL, empresa TEXT NOT NULL DEFAULT '', descripcion TEXT, unidad TEXT,
      actual REAL DEFAULT 0, minimo REAL DEFAULT 0, actualizado_en TEXT,
      PRIMARY KEY (codigo, empresa) )`,
    `CREATE TABLE IF NOT EXISTS bod_activos2 (
      codigo TEXT PRIMARY KEY, nombre TEXT, categoria TEXT, empresa_legal TEXT,
      estado TEXT, ubicacion TEXT, notas TEXT, prestado TEXT, actualizado_en TEXT )`,
    `CREATE TABLE IF NOT EXISTS bod_catalogo (
      codigo TEXT NOT NULL, empresa_legal TEXT NOT NULL DEFAULT '', descripcion TEXT,
      unidad TEXT, categoria TEXT, PRIMARY KEY (codigo, empresa_legal) )`,
    // Copia única desde las tablas v20 (si stock2/activos2 están vacías)
    `INSERT OR IGNORE INTO bod_stock2 (codigo,empresa,descripcion,unidad,actual,minimo,actualizado_en)
       SELECT codigo,'',descripcion,unidad,actual,minimo,actualizado_en FROM bod_stock`,
    `INSERT OR IGNORE INTO bod_activos2 (codigo,nombre,estado,actualizado_en)
       SELECT COALESCE(NULLIF(codigo,''),'ACT-'||id), nombre, estado, actualizado_en FROM bod_activos`,
  ];
  for (const s of stmts) { try { await env.DB.prepare(s).run(); } catch (e) { /* ya existe */ } }
  BOD_READY = true;
}

// Correo best-effort vía Resend. NUNCA bloquea la operación principal.
async function bodEmail(env, para, asunto, html, cc) {
  const key = env.RESEND_API_KEY || env.RESEND_API_KEY_MARCAIRE;
  if (!key) return false;
  try {
    const body = { from: env.EMAIL_FROM || 'Bodegas MARC <no-reply@marcaire.com>', to: Array.isArray(para) ? para : [para], subject: asunto, html };
    if (cc && cc.length) body.cc = cc;
    const r = await fetch('https://api.resend.com/emails', {
      method: 'POST', headers: { 'Authorization': 'Bearer ' + key, 'Content-Type': 'application/json' },
      body: JSON.stringify(body)
    });
    return r.ok;
  } catch (e) { return false; }
}

// --- Vocabulario de estados unificado (v21) ---
// Canónico (lo que se guarda): pendiente | aprobada | rechazada | listo | entregado
// El rastreador del index habla: aceptado | preparado | rechazado_total | rechazado_parcial...
function bodEstadoCanon(e) {
  const m = { aceptado: 'aprobada', preparado: 'listo', rechazado_total: 'rechazada',
    rechazado_parcial: 'listo', cancelado: 'rechazada', pendiente: 'pendiente',
    aprobada: 'aprobada', rechazada: 'rechazada', listo: 'listo', entregado: 'entregado', entregada: 'entregado' };
  return m[String(e || 'pendiente')] || 'pendiente';
}
function bodEstadoIndex(canon, parcial) {
  if (canon === 'listo' && parcial) return 'rechazado_parcial';
  const m = { pendiente: 'pendiente', aprobada: 'aceptado', listo: 'preparado', entregado: 'entregado', rechazada: 'rechazado_total' };
  return m[canon] || canon;
}
function bodGrupo(canon) {
  if (canon === 'listo' || canon === 'aprobada' || canon === 'entregado') return 'aprobadas';
  if (canon === 'rechazada') return 'rechazadas';
  return 'espera';
}
// ¿El PIN pertenece a un rol operativo? (el panel manda adminPin en cada acción)
async function bodAuth(env, pin, roles) {
  if (!pin) return false;
  if (String(pin) === SETUP_KEY) return true;
  const u = await env.DB.prepare('SELECT rol FROM usuarios WHERE pin=? AND activo=1').bind(String(pin)).first();
  if (!u) return false;
  return (roles || ['dueno', 'admin', 'bodega', 'compras']).includes(u.rol);
}

// Aplana la fila para el rastreador/panel (la app lee s.numero, s.estado,
// s.solicitante, s.proyecto, s.centroCosto, s.empresaCosto, s.items...)
function bodFlat(row) {
  let p = {};
  try { p = JSON.parse(row.payload) || {}; } catch (e) {}
  const canon = bodEstadoCanon(row.estado);
  return Object.assign({}, p, {
    numero: row.numero, estado: bodEstadoIndex(canon, row.parcial), pdf_url: row.pdf_url || '',
    origen: row.origen || p.origen || '',
    solicitante: row.solicitante || (p.solicitante && p.solicitante.empleado) || '',
    email: row.email || (p.solicitante && p.solicitante.email) || '',
    proyecto: row.proyecto || (p.destino && p.destino.proyecto) || '',
    centroCosto: row.centro_costo || (p.asignacion && p.asignacion.centroCosto) || '',
    empresaCosto: row.empresa_costo || (p.asignacion && p.asignacion.empresaCosto) || '',
    marca: row.marca || (p.solicitante && p.solicitante.empresaMarc) || '',
    fecha: row.fecha || p.fecha || '', creado_en: row.creado_en || '', actualizado_en: row.actualizado_en || ''
  });
}

// POST {pdfBase64,filename,solicitudData} → upsert por numero (reintentos NO duplican)
async function bodCrear(env, body) {
  const d = body.solicitudData || {};
  const numero = String(d.numero || '').trim();
  if (!numero) return j({ ok: false, error: 'Falta numero en solicitudData' }, 400);
  let pdfUrl = null;
  if (body.pdfBase64 && env.ARCHIVOS) {
    try {
      const ruta = 'bodega/' + numero.replace(/[^a-zA-Z0-9_-]/g, '_') + '.pdf';
      const bytes = Uint8Array.from(atob(soloBase64(body.pdfBase64)), c => c.charCodeAt(0));
      await env.ARCHIVOS.put(ruta, bytes, { httpMetadata: { contentType: 'application/pdf' } });
      pdfUrl = 'https://marc-erp.late-dew-2dd9.workers.dev/archivo/' + ruta;
    } catch (e) { /* si R2 falla, igual guardamos el registro */ }
  }
  const t = crParts();
  const sol = d.solicitante || {}, des = d.destino || {}, asg = d.asignacion || {};
  const hist = JSON.stringify([{ estado: 'pendiente', por: sol.empleado || '', nota: 'Solicitud creada', ts: t.iso }]);
  const origen = String(body.origen || d.origen || d.app || '');
  await env.DB.prepare(
    `INSERT INTO bod_solicitudes (numero,estado,solicitante,email,proyecto,centro_costo,empresa_costo,marca,fecha,prioridad,payload,pdf_url,historial,origen,creado_en,actualizado_en)
     VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
     ON CONFLICT(numero) DO UPDATE SET
       payload=excluded.payload, pdf_url=COALESCE(excluded.pdf_url, bod_solicitudes.pdf_url),
       solicitante=excluded.solicitante, email=excluded.email, proyecto=excluded.proyecto,
       centro_costo=excluded.centro_costo, empresa_costo=excluded.empresa_costo, marca=excluded.marca,
       fecha=excluded.fecha, prioridad=excluded.prioridad, actualizado_en=excluded.actualizado_en`
  ).bind(numero, 'pendiente', sol.empleado || '', sol.email || '', des.proyecto || '',
    asg.centroCosto || '', asg.empresaCosto || '', sol.empresaMarc || '', d.fecha || t.fecha,
    (des.prioridad || ''), JSON.stringify(d), pdfUrl, hist, origen, t.iso, t.iso).run();

  // Aviso a bodega (best-effort). CC al solicitante si dejó correo.
  const itemsHtml = (d.items || []).map(it => `<li>${it.cantidad || ''} ${it.unidad || ''} — ${it.descripcion || ''}${it.codigoERP ? ' (' + it.codigoERP + ')' : ''}</li>`).join('');
  const cc = (sol.email && /@/.test(sol.email)) ? [sol.email] : [];
  const emailOk = await bodEmail(env, ['bodega@metal-marc.com'],
    `📦 Nueva solicitud ${numero} — ${sol.empleado || 'Solicitante'} (${des.proyecto || 'sin proyecto'})`,
    `<h2>Solicitud ${numero}</h2>
     <p><b>Solicitante:</b> ${sol.empleado || ''} · <b>Proyecto:</b> ${des.proyecto || ''} · <b>CC:</b> ${asg.centroCosto || ''}</p>
     <p><b>Prioridad:</b> ${des.prioridad || 'normal'} · <b>Necesario para:</b> ${des.fechaNecesario || '—'}</p>
     <ul>${itemsHtml}</ul>
     ${pdfUrl ? `<p><a href="${pdfUrl}">📄 Ver PDF de la solicitud</a></p>` : ''}`, cc);
  // WhatsApp: aviso al solicitante (plantilla solicitud_recibida)
  try {
    const telSol = await waTelPara(env, { email: sol.email, nombre: sol.empleado });
    if (telSol) await enviarPlantilla(env, telSol, WA_TPL.solicitud_recibida, { '1': numero }, 'solicitud_recibida');
  } catch (e) { console.log('wa bodCrear', e.message); }
  return j({ ok: true, numero, url: pdfUrl || '', emailEnviado: emailOk });
}

async function bodTodas(env) {
  const res = await env.DB.prepare(`SELECT * FROM bod_solicitudes ORDER BY creado_en DESC LIMIT 800`).all();
  return j({ ok: true, solicitudes: (res.results || []).map(bodFlat) });
}
async function bodMis(env, email) {
  const e = String(email || '').trim().toLowerCase();
  if (!e) return j({ ok: true, solicitudes: [] });
  const res = await env.DB.prepare(`SELECT * FROM bod_solicitudes WHERE LOWER(email)=? ORDER BY creado_en DESC LIMIT 300`).bind(e).all();
  return j({ ok: true, solicitudes: (res.results || []).map(bodFlat) });
}
async function bodFiltros(env) {
  const cnt = async (col) => {
    const r = await env.DB.prepare(`SELECT ${col} AS valor, COUNT(*) AS count FROM bod_solicitudes WHERE ${col}<>'' GROUP BY ${col} ORDER BY count DESC LIMIT 60`).all();
    return (r.results || []).map(x => ({ valor: x.valor, count: x.count }));
  };
  return j({ ok: true, proyectos: await cnt('proyecto'), centrosCostos: await cnt('centro_costo'), marcas: await cnt('marca') });
}

// Dashboard con filtros (proyecto/cc/marca/desde/hasta)
async function bodDashboard(env, p) {
  p = p || {};
  let sql = `SELECT * FROM bod_solicitudes WHERE 1=1`; const binds = [];
  if (p.proyecto) { sql += ` AND proyecto=?`; binds.push(p.proyecto); }
  if (p.cc)       { sql += ` AND centro_costo=?`; binds.push(p.cc); }
  if (p.marca)    { sql += ` AND marca=?`; binds.push(p.marca); }
  if (p.desde)    { sql += ` AND fecha>=?`; binds.push(p.desde); }
  if (p.hasta)    { sql += ` AND fecha<=?`; binds.push(p.hasta); }
  const rows = (await env.DB.prepare(sql).bind(...binds).all()).results || [];
  const hoy = crParts().fecha, hace7 = finSumaDias(hoy, -7), hace30 = finSumaDias(hoy, -30);
  const est = s => rows.filter(r => bodEstadoIndex(bodEstadoCanon(r.estado), r.parcial) === s).length;
  const top = (getter, limit) => {
    const m = {};
    rows.forEach(r => { const k = getter(r); if (k) m[k] = (m[k] || 0) + 1; });
    return Object.entries(m).sort((a, b) => b[1] - a[1]).slice(0, limit || 5).map(([nombre, count]) => ({ nombre, count }));
  };
  // Tiempo promedio de despacho (creación → entregado), en días con 1 decimal
  let suma = 0, nEnt = 0;
  rows.forEach(r => {
    if (r.estado !== 'entregado' || !r.creado_en) return;
    let hist = []; try { hist = JSON.parse(r.historial) || []; } catch (e) {}
    const ent = hist.filter(h => h.estado === 'entregado').pop();
    const fin = (ent && ent.ts) || r.actualizado_en;
    if (!fin) return;
    const dias = (new Date(fin) - new Date(r.creado_en)) / 86400000;
    if (dias >= 0) { suma += dias; nEnt++; }
  });
  const itemsDe = r => { try { return (JSON.parse(r.payload).items) || []; } catch (e) { return []; } };
  const topItems = (() => {
    const m = {};
    rows.filter(r => (r.fecha || '') >= hace30).forEach(r => itemsDe(r).forEach(it => {
      const k = (it.descripcion || '').trim(); if (k) m[k] = (m[k] || 0) + 1;
    }));
    return Object.entries(m).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([nombre, count]) => ({ nombre, count }));
  })();
  const compras = (await env.DB.prepare(`SELECT items FROM bod_compras`).all()).results || [];
  const topRechazados = (() => {
    const m = {};
    compras.forEach(c => { let its = []; try { its = JSON.parse(c.items) || []; } catch (e) {}
      its.forEach(it => { const k = (it.descripcion || '').trim(); if (k) m[k] = (m[k] || 0) + 1; }); });
    return Object.entries(m).sort((a, b) => b[1] - a[1]).slice(0, 8).map(([nombre, count]) => ({ nombre, count }));
  })();
  // Formato del PANEL (d.resumen): estados por grupo, meses, tops {nombre,n}
  const topN = (getter, limit) => {
    const m = {};
    rows.forEach(r => { const k = getter(r); if (k) m[k] = (m[k] || 0) + 1; });
    return Object.entries(m).sort((a, b) => b[1] - a[1]).slice(0, limit || 8).map(([nombre, n]) => ({ nombre, n }));
  };
  const meses = (() => {
    const m = {};
    rows.forEach(r => { const k = String(r.fecha || '').slice(0, 7); if (k) m[k] = (m[k] || 0) + 1; });
    return Object.entries(m).sort().map(([mes, n]) => ({ mes, n }));
  })();
  let itemsTotal = 0, conTransporte = 0;
  rows.forEach(r => {
    let pl = {}; try { pl = JSON.parse(r.payload) || {}; } catch (e) {}
    itemsTotal += Array.isArray(pl.items) ? pl.items.length : 0;
    if (pl.transporte && pl.transporte.necesita) conTransporte++;
  });
  const grupos = { espera: 0, aprobadas: 0, rechazadas: 0 };
  rows.forEach(r => { grupos[bodGrupo(bodEstadoCanon(r.estado))]++; });
  const resumen = {
    total: rows.length, estados: grupos, transporte: conTransporte, items: itemsTotal,
    meses, proyectos: topN(r => r.proyecto), solicitantes: topN(r => r.solicitante), empresas: topN(r => r.empresa_costo)
  };
  return j({ ok: true, resumen, dashboard: {
    total: rows.length,
    enUltimosSiete: rows.filter(r => (r.fecha || '') >= hace7).length,
    pendientes: est('pendiente'), aceptadas: est('aceptado'), preparadas: est('preparado'),
    entregadas: est('entregado'), rechazadasTotales: est('rechazado_total'), rechazadasParciales: est('rechazado_parcial'),
    tiempoPromedioDespacho: nEnt ? Math.round((suma / nEnt) * 10) / 10 : 0,
    topProyectos: top(r => r.proyecto), topCCs: top(r => r.centro_costo),
    topMarcas: top(r => r.marca), topSolicitantes: top(r => r.solicitante),
    topItems, topRechazados
  } });
}

// POST {accion:'cambiarEstado', numero, nuevoEstado, por, nota?, motivoRechazo?, itemsRechazados?}
// Despacho parcial: los faltantes generan COMPRA-XXXX y se avisa a compras.
async function bodCambiarEstado(env, body) {
  const numero = String(body.numero || '').trim();
  const nuevo = String(body.nuevoEstado || '').trim();
  if (!numero || !nuevo) return j({ ok: false, error: 'numero y nuevoEstado requeridos' }, 400);
  const row = await env.DB.prepare(`SELECT * FROM bod_solicitudes WHERE numero=?`).bind(numero).first();
  if (!row) return j({ ok: false, error: 'Solicitud no existe: ' + numero }, 404);
  const t = crParts();
  let hist = []; try { hist = JSON.parse(row.historial) || []; } catch (e) {}
  const canon = bodEstadoCanon(nuevo);   // v21: el index habla su idioma; guardamos canónico
  hist.push({ estado: canon, por: body.por || '', nota: body.nota || '', motivo: body.motivoRechazo || '', ts: t.iso });
  let comprasRef = null;
  const rech = Array.isArray(body.itemsRechazados) ? body.itemsRechazados : [];
  if (rech.length) {
    comprasRef = await siguienteNumero(env, 'compras', 'COMPRA-');
    await env.DB.prepare(`INSERT INTO bod_compras (referencia,solicitud,items,motivo,estado,creado_en) VALUES (?,?,?,?,?,?)`)
      .bind(comprasRef, numero, JSON.stringify(rech), body.motivoRechazo || '', 'pendiente', t.iso).run();
    const lista = rech.map(it => `<li>${it.cantidad || ''} ${it.unidad || ''} — ${it.descripcion || ''} (pedidas ${it.cantidadOriginalPedida || '?'}, despachadas ${it.cantidadDespachada || 0})</li>`).join('');
    await bodEmail(env, ['compras@marcaire.com'],
      `🛒 ${comprasRef} — Faltantes de ${numero} (${rech.length} ítem/s)`,
      `<h2>${comprasRef}</h2><p>De la solicitud <b>${numero}</b> (${row.solicitante || ''} · ${row.proyecto || ''}).</p>
       <p><b>Motivo:</b> ${body.motivoRechazo || '—'}</p><ul>${lista}</ul>`);
  }
  await env.DB.prepare(`UPDATE bod_solicitudes SET estado=?, parcial=CASE WHEN ? THEN 1 ELSE parcial END, historial=?, actualizado_en=? WHERE numero=?`)
    .bind(canon, rech.length ? 1 : 0, JSON.stringify(hist), t.iso, numero).run();
  // Aviso al solicitante cuando queda listo o entregado (best-effort)
  if ((canon === 'listo' || canon === 'entregado') && row.email && /@/.test(row.email)) {
    const msj = canon === 'listo' ? '📦 Tu pedido está LISTO para retirar en bodega.' : '🚚 Tu pedido fue ENTREGADO.';
    await bodEmail(env, [row.email], `${numero}: ${canon === 'listo' ? 'Listo para retirar' : 'Entregado'}`,
      `<p>${msj}</p><p>Solicitud <b>${numero}</b> · Proyecto ${row.proyecto || '—'}.</p>`);
  }
  // WhatsApp: aviso al solicitante cuando queda LISTO (plantilla pedido_listo)
  try {
    if (canon === 'listo') {
      const telSol = await waTelPara(env, { email: row.email, nombre: row.solicitante });
      if (telSol) await enviarPlantilla(env, telSol, WA_TPL.pedido_listo, { '1': numero }, 'pedido_listo');
    }
  } catch (e) { console.log('wa bodEstado', e.message); }
  return j({ ok: true, estado: nuevo, comprasRef });
}

// Stock: por empresa (panel manda empresaLegal) o suma total (index sin parámetro)
async function bodStockMapa(env, body) {
  const emp = String((body && body.empresaLegal) || '').trim();
  const res = emp
    ? await env.DB.prepare(`SELECT codigo, actual FROM bod_stock2 WHERE empresa=?`).bind(emp).all()
    : await env.DB.prepare(`SELECT codigo, SUM(actual) AS actual FROM bod_stock2 GROUP BY codigo`).all();
  const stock = {};
  (res.results || []).forEach(r => { stock[r.codigo] = Number(r.actual) || 0; });
  return j({ ok: true, stock });
}
// {codigoERP, nombre, nuevoActual, nuevoMinimo, motivo, por} → upsert + kardex
async function bodAjustarStock(env, body) {
  const codigo = String(body.codigoERP || body.codigo || '').trim();
  if (!codigo) return j({ ok: false, error: 'codigoERP requerido' }, 400);
  const nuevo = Math.max(0, Number(body.nuevoActual) || 0);
  const minimo = Math.max(0, Number(body.nuevoMinimo) || 0);
  const t = crParts();
  const emp = String(body.empresaLegal || '').trim();
  const prev = await env.DB.prepare(`SELECT actual FROM bod_stock2 WHERE codigo=? AND empresa=?`).bind(codigo, emp).first();
  const antes = prev ? Number(prev.actual) || 0 : 0;
  await env.DB.prepare(`INSERT INTO bod_stock2 (codigo,empresa,descripcion,unidad,actual,minimo,actualizado_en) VALUES (?,?,?,?,?,?,?)
    ON CONFLICT(codigo,empresa) DO UPDATE SET actual=excluded.actual, minimo=excluded.minimo,
      descripcion=CASE WHEN excluded.descripcion<>'' THEN excluded.descripcion ELSE bod_stock2.descripcion END,
      actualizado_en=excluded.actualizado_en`)
    .bind(codigo, emp, String(body.nombre || ''), String(body.unidad || ''), nuevo, minimo, t.iso).run();
  await env.DB.prepare(`INSERT INTO bod_stock_mov (codigo,antes,despues,motivo,por,fecha,ts,ref) VALUES (?,?,?,?,?,?,?,?)`)
    .bind(codigo, antes, nuevo, String(body.motivo || ''), String(body.por || ''), t.fecha, t.iso, emp ? 'emp:' + emp : '').run();
  return j({ ok: true, codigo, antes, actual: nuevo, minimo });
}

async function bodActivosListar(env, body) {
  body = body || {};
  const res = await env.DB.prepare(`SELECT * FROM bod_activos2 ORDER BY nombre`).all();
  let items = (res.results || []).map(r => {
    let prestado = null; try { prestado = r.prestado ? JSON.parse(r.prestado) : null; } catch (e) {}
    return { codigo: r.codigo || '', nombre: r.nombre || '', categoria: r.categoria || '',
      empresa_legal: r.empresa_legal || '', estado: r.estado || '', ubicacion: r.ubicacion || '',
      notas: r.notas || '', prestado };
  });
  const q = String(body.q || '').toLowerCase();
  if (q) items = items.filter(a => (a.nombre + ' ' + a.codigo + ' ' + a.ubicacion + ' ' + a.notas).toLowerCase().includes(q));
  if (body.categoria) items = items.filter(a => a.categoria === body.categoria);
  if (body.soloDisponibles) items = items.filter(a => !a.prestado);
  if (body.soloPrestados) items = items.filter(a => !!a.prestado);
  return j({ ok: true, items });
}
async function bodListarProyectos(env) {
  const res = await env.DB.prepare(`SELECT codigo,nombre,razon_social FROM bod_proyectos WHERE activo=1 ORDER BY razon_social, codigo`).all();
  return j({ ok: true, proyectos: res.results || [] });
}

// ---- MIGRACIÓN desde bodegas-marc-ap (clave SETUP_KEY) ----
async function bodImportar(env, body) {
  if (String(body.key || '') !== SETUP_KEY) return j({ ok: false, error: 'Clave incorrecta' }, 403);
  const tabla = String(body.tabla || ''), filas = Array.isArray(body.filas) ? body.filas : [];
  if (!filas.length) return j({ ok: false, error: 'filas vacías' }, 400);
  if (filas.length > 800) return j({ ok: false, error: 'Máximo 800 filas por tanda' }, 400);
  const t = crParts(); let n = 0;
  if (tabla === 'proyectos') {
    for (const f of filas) {
      if (!f || !f.codigo) continue;
      await env.DB.prepare(`INSERT INTO bod_proyectos (codigo,nombre,razon_social,activo) VALUES (?,?,?,1)
        ON CONFLICT(codigo,razon_social) DO UPDATE SET nombre=excluded.nombre, activo=1`)
        .bind(String(f.codigo), String(f.nombre || ''), String(f.razon_social || f.empresaLegal || '')).run();
      n++;
    }
  } else if (tabla === 'stock') {
    for (const f of filas) {
      if (!f || !f.codigo) continue;
      const emp = String(f.empresa || f.empresaLegal || '');
      await env.DB.prepare(`INSERT INTO bod_stock2 (codigo,empresa,descripcion,unidad,actual,minimo,actualizado_en) VALUES (?,?,?,?,?,?,?)
        ON CONFLICT(codigo,empresa) DO UPDATE SET actual=excluded.actual,
          minimo=CASE WHEN excluded.minimo>0 THEN excluded.minimo ELSE bod_stock2.minimo END,
          descripcion=CASE WHEN excluded.descripcion<>'' THEN excluded.descripcion ELSE bod_stock2.descripcion END,
          actualizado_en=excluded.actualizado_en`)
        .bind(String(f.codigo), emp, String(f.descripcion || f.nombre || ''), String(f.unidad || ''),
          Number(f.actual != null ? f.actual : f.disponible) || 0, Number(f.minimo) || 0, t.iso).run();
      n++;
    }
  } else if (tabla === 'activos') {
    for (const f of filas) {
      if (!f) continue;
      await env.DB.prepare(`INSERT INTO bod_activos (codigo,nombre,estado,asignado,payload,actualizado_en) VALUES (?,?,?,?,?,?)`)
        .bind(String(f.codigo || ''), String(f.nombre || f.descripcion || ''), String(f.estado || ''),
          String(f.asignado || f.prestadoA || ''), JSON.stringify(f), t.iso).run();
      n++;
    }
  } else if (tabla === 'solicitudes') {
    for (const f of filas) {
      const numero = String((f && f.numero) || '').trim();
      if (!numero) continue;
      const sol = f.solicitante && typeof f.solicitante === 'object' ? f.solicitante : {};
      await env.DB.prepare(
        `INSERT INTO bod_solicitudes (numero,estado,solicitante,email,proyecto,centro_costo,empresa_costo,marca,fecha,prioridad,payload,pdf_url,historial,origen,creado_en,actualizado_en)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
         ON CONFLICT(numero) DO UPDATE SET estado=excluded.estado, payload=excluded.payload, origen=excluded.origen,
           pdf_url=COALESCE(NULLIF(excluded.pdf_url,''), bod_solicitudes.pdf_url), actualizado_en=excluded.actualizado_en`
      ).bind(numero, bodEstadoCanon(f.estado),
        String((typeof f.solicitante === 'string' ? f.solicitante : sol.empleado) || ''),
        String(f.email || sol.email || ''), String(f.proyecto || (f.destino && f.destino.proyecto) || ''),
        String(f.centroCosto || (f.asignacion && f.asignacion.centroCosto) || ''),
        String(f.empresaCosto || (f.asignacion && f.asignacion.empresaCosto) || ''),
        String(f.marca || sol.empresaMarc || ''), String(f.fecha || ''),
        String(f.prioridad || (f.destino && f.destino.prioridad) || ''),
        JSON.stringify(f), String(f.pdf_url || f.driveUrl || ''),
        JSON.stringify([{ estado: bodEstadoCanon(f.estado), por: 'migración', nota: 'Importado de bodegas-marc-ap', ts: t.iso }]),
        String(f.origen || f.app || ''),
        String(f.creado_en || f.timestamp || t.iso), t.iso).run();
      n++;
    }
  } else return j({ ok: false, error: 'tabla desconocida: ' + tabla }, 400);
  return j({ ok: true, tabla, importados: n });
}
async function bodSetCounter(env, body) {
  if (String(body.key || '') !== SETUP_KEY) return j({ ok: false, error: 'Clave incorrecta' }, 403);
  const nombre = String(body.nombre || 'global');
  if (nombre !== 'global' && nombre !== 'compras') return j({ ok: false, error: 'contador no permitido' }, 400);
  const v = parseInt(body.valor, 10);
  if (!v || v < 1) return j({ ok: false, error: 'valor inválido' }, 400);
  await env.DB.prepare(`INSERT INTO contadores (nombre,valor) VALUES (?,?) ON CONFLICT(nombre) DO UPDATE SET valor=excluded.valor`).bind(nombre, v).run();
  return j({ ok: true, contador: nombre, valor: v });
}


// ============================================================
//  v21 — PANEL DE BODEGA, COMPRA.HTML, KIOSKO TALLER, IMPORTADORES
// ============================================================

// {grupo?, desde?, hasta?, origen?, email?, solicitante?} → lista para el panel
async function bodHistorial(env, p) {
  p = p || {};
  let sql = `SELECT * FROM bod_solicitudes WHERE 1=1`; const binds = [];
  if (p.desde)  { sql += ` AND fecha>=?`; binds.push(String(p.desde)); }
  if (p.hasta)  { sql += ` AND fecha<=?`; binds.push(String(p.hasta)); }
  if (p.origen) { sql += ` AND (origen=? OR payload LIKE ?)`; binds.push(String(p.origen), '%"origen":"' + String(p.origen) + '"%'); }
  if (p.email)  { sql += ` AND LOWER(email)=?`; binds.push(String(p.email).toLowerCase()); }
  if (p.solicitante) { sql += ` AND solicitante=?`; binds.push(String(p.solicitante)); }
  sql += ` ORDER BY creado_en DESC LIMIT 600`;
  const rows = (await env.DB.prepare(sql).bind(...binds).all()).results || [];
  const grupo = String(p.grupo || '');
  const solicitudes = [];
  for (const r of rows) {
    const canon = bodEstadoCanon(r.estado);
    if (grupo && bodGrupo(canon) !== grupo) continue;
    let pl = {}; try { pl = JSON.parse(r.payload) || {}; } catch (e) {}
    solicitudes.push({
      numero: r.numero, estado: canon,
      solicitante: r.solicitante || '', proyecto: r.proyecto || '',
      transporte: !!(pl.transporte && pl.transporte.necesita),
      fecha: r.fecha || '', hora: pl.hora || '',
      items: Array.isArray(pl.items) ? pl.items.length : 0,
      origen: r.origen || pl.origen || ''
    });
  }
  return j({ ok: true, solicitudes });
}

// {numero} → detalle completo para revisar
async function bodDetalle(env, p) {
  const numero = String((p && p.numero) || '').trim();
  const r = await env.DB.prepare(`SELECT * FROM bod_solicitudes WHERE numero=?`).bind(numero).first();
  if (!r) return j({ ok: false, error: 'Solicitud no existe: ' + numero }, 404);
  let pl = {}; try { pl = JSON.parse(r.payload) || {}; } catch (e) {}
  return j({ ok: true, numero: r.numero, estado: bodEstadoCanon(r.estado), solicitud: pl, items: Array.isArray(pl.items) ? pl.items : [] });
}

// {numero, lineas, estado(aprobada|rechazada|listo), por, sinCorreo, pdfBase64}
// listo: descuenta stock por línea entregada; comprar>0 → COMPRA-XXXX a Carlos.
async function bodResolver(env, body) {
  const numero = String(body.numero || '').trim();
  const estado = bodEstadoCanon(body.estado);
  if (!numero) return j({ ok: false, error: 'numero requerido' }, 400);
  const row = await env.DB.prepare(`SELECT * FROM bod_solicitudes WHERE numero=?`).bind(numero).first();
  if (!row) return j({ ok: false, error: 'Solicitud no existe: ' + numero }, 404);
  const t = crParts();
  let pl = {}; try { pl = JSON.parse(row.payload) || {}; } catch (e) {}
  const items = Array.isArray(pl.items) ? pl.items : [];
  const lineas = Array.isArray(body.lineas) ? body.lineas : [];
  // Merge de líneas revisadas dentro del payload
  lineas.forEach(l => {
    const it = items[l.idx]; if (!it) return;
    it.estadoLinea = l.estadoLinea; it.aprobada = l.aprobada;
    it.existente = l.existente; it.cantidadEntregada = l.cantidadEntregada;
    it.cantidadComprar = l.cantidadComprar;
  });
  // Faltantes a compras
  let comprasRef = null, parcial = 0;
  const aComprar = lineas.filter(l => Number(l.cantidadComprar) > 0);
  if (estado !== 'rechazada' && aComprar.length) {
    parcial = 1;
    comprasRef = await siguienteNumero(env, 'compras', 'COMPRA-');
    const detalle = aComprar.map(l => {
      const it = items[l.idx] || {};
      return { descripcion: it.descripcion || '', codigoERP: it.codigoERP || '', unidad: it.unidad || '',
        cantidad: Number(l.cantidadComprar) || 0, cantidadOriginalPedida: Number(it.cantidad) || 0,
        cantidadDespachada: Number(l.cantidadEntregada) || 0 };
    });
    await env.DB.prepare(`INSERT INTO bod_compras (referencia,solicitud,items,motivo,estado,creado_en) VALUES (?,?,?,?,?,?)`)
      .bind(comprasRef, numero, JSON.stringify(detalle), 'Faltantes al despachar', 'pendiente', t.iso).run();
    if (!body.sinCorreo) {
      const lista = detalle.map(d2 => `<li>${d2.cantidad} ${d2.unidad} — ${d2.descripcion}${d2.codigoERP ? ' (' + d2.codigoERP + ')' : ''}</li>`).join('');
      await bodEmail(env, ['compras@marcaire.com'],
        `🛒 ${comprasRef} — Faltantes de ${numero} (${detalle.length} ítem/s)`,
        `<h2>${comprasRef}</h2><p>De la solicitud <b>${numero}</b> (${row.solicitante || ''} · ${row.proyecto || ''}).</p><ul>${lista}</ul>`);
    }
  }
  // Despacho: descuenta stock por lo entregado (kardex con ref para poder devolver)
  if (estado === 'listo') {
    const emp = (pl.solicitante && pl.solicitante.empresaLegal) || '';
    for (const l of lineas) {
      const it = items[l.idx] || {};
      const cod = String(it.codigoERP || '').trim();
      const ent = Number(l.cantidadEntregada) || 0;
      if (!cod || ent <= 0) continue;
      let fila = await env.DB.prepare(`SELECT empresa,actual FROM bod_stock2 WHERE codigo=? AND empresa=?`).bind(cod, emp).first();
      let empFila = emp;
      if (!fila) { fila = await env.DB.prepare(`SELECT empresa,actual FROM bod_stock2 WHERE codigo=? ORDER BY actual DESC LIMIT 1`).bind(cod).first(); if (fila) empFila = fila.empresa; }
      if (!fila) continue;
      const antes = Number(fila.actual) || 0, despues = Math.max(0, antes - ent);
      await env.DB.prepare(`UPDATE bod_stock2 SET actual=?, actualizado_en=? WHERE codigo=? AND empresa=?`).bind(despues, t.iso, cod, empFila).run();
      await env.DB.prepare(`INSERT INTO bod_stock_mov (codigo,antes,despues,motivo,por,fecha,ts,ref) VALUES (?,?,?,?,?,?,?,?)`)
        .bind(cod, antes, despues, 'Despacho ' + numero, String(body.por || ''), t.fecha, t.iso, numero).run();
    }
  }
  // PDF del despacho (opcional)
  if (body.pdfBase64 && env.ARCHIVOS) {
    try {
      const ruta = 'bodega/' + numero.replace(/[^a-zA-Z0-9_-]/g, '_') + '-despacho.pdf';
      const bytes = Uint8Array.from(atob(soloBase64(body.pdfBase64)), c => c.charCodeAt(0));
      await env.ARCHIVOS.put(ruta, bytes, { httpMetadata: { contentType: 'application/pdf' } });
      pl.pdfDespachoUrl = 'https://marc-erp.late-dew-2dd9.workers.dev/archivo/' + ruta;
    } catch (e) {}
  }
  let hist = []; try { hist = JSON.parse(row.historial) || []; } catch (e) {}
  hist.push({ estado, por: body.por || '', nota: comprasRef ? ('Faltantes → ' + comprasRef) : '', ts: t.iso });
  pl.items = items; pl.aprobadoPor = body.por || pl.aprobadoPor;
  await env.DB.prepare(`UPDATE bod_solicitudes SET estado=?, parcial=CASE WHEN ? THEN 1 ELSE parcial END, payload=?, historial=?, actualizado_en=? WHERE numero=?`)
    .bind(estado, parcial, JSON.stringify(pl), JSON.stringify(hist), t.iso, numero).run();
  // Aviso al solicitante
  if (!body.sinCorreo && row.email && /@/.test(row.email)) {
    const msj = estado === 'listo' ? '📦 Tu pedido está LISTO para retirar en bodega.'
      : estado === 'aprobada' ? '✅ Tu solicitud fue APROBADA.' : '❌ Tu solicitud fue RECHAZADA.';
    await bodEmail(env, [row.email], `${numero}: ${estado}`,
      `<p>${msj}</p><p>Solicitud <b>${numero}</b> · Proyecto ${row.proyecto || '—'}.</p>` +
      (pl.pdfDespachoUrl ? `<p><a href="${pl.pdfDespachoUrl}">📄 Comprobante de despacho</a></p>` : ''));
  }
  return j({ ok: true, estado, comprasRef });
}

// {numero} → borra y devuelve al inventario lo despachado (kardex con ref)
async function bodEliminar(env, p) {
  const numero = String((p && p.numero) || '').trim();
  const row = await env.DB.prepare(`SELECT numero FROM bod_solicitudes WHERE numero=?`).bind(numero).first();
  if (!row) return j({ ok: false, error: 'Solicitud no existe: ' + numero }, 404);
  const t = crParts();
  const movs = (await env.DB.prepare(`SELECT codigo, antes, despues FROM bod_stock_mov WHERE ref=?`).bind(numero).all()).results || [];
  let devuelto = false;
  for (const m of movs) {
    const delta = (Number(m.antes) || 0) - (Number(m.despues) || 0);   // lo que se descontó
    if (delta <= 0) continue;
    const fila = await env.DB.prepare(`SELECT empresa,actual FROM bod_stock2 WHERE codigo=? ORDER BY actualizado_en DESC LIMIT 1`).bind(m.codigo).first();
    if (!fila) continue;
    const nuevo = (Number(fila.actual) || 0) + delta;
    await env.DB.prepare(`UPDATE bod_stock2 SET actual=?, actualizado_en=? WHERE codigo=? AND empresa=?`).bind(nuevo, t.iso, m.codigo, fila.empresa).run();
    await env.DB.prepare(`INSERT INTO bod_stock_mov (codigo,antes,despues,motivo,por,fecha,ts,ref) VALUES (?,?,?,?,?,?,?,?)`)
      .bind(m.codigo, Number(fila.actual) || 0, nuevo, 'Devolución por eliminación de ' + numero, 'sistema', t.fecha, t.iso, numero + '-dev').run();
    devuelto = true;
  }
  await env.DB.prepare(`DELETE FROM bod_solicitudes WHERE numero=?`).bind(numero).run();
  return j({ ok: true, eliminado: numero, inventarioDevuelto: devuelto });
}

// {codigo, empresaLegal, disponible, adminPin} — existencias del panel
async function bodStockAjustarPanel(env, body) {
  if (!(await bodAuth(env, body.adminPin))) return j({ ok: false, error: 'PIN sin permiso' }, 403);
  const codigo = String(body.codigo || '').trim();
  if (!codigo) return j({ ok: false, error: 'codigo requerido' }, 400);
  const emp = String(body.empresaLegal || '');
  const val = Math.max(0, Number(body.disponible) || 0);
  const t = crParts();
  const prev = await env.DB.prepare(`SELECT actual FROM bod_stock2 WHERE codigo=? AND empresa=?`).bind(codigo, emp).first();
  await env.DB.prepare(`INSERT INTO bod_stock2 (codigo,empresa,actual,actualizado_en) VALUES (?,?,?,?)
    ON CONFLICT(codigo,empresa) DO UPDATE SET actual=excluded.actual, actualizado_en=excluded.actualizado_en`)
    .bind(codigo, emp, val, t.iso).run();
  await env.DB.prepare(`INSERT INTO bod_stock_mov (codigo,antes,despues,motivo,por,fecha,ts,ref) VALUES (?,?,?,?,?,?,?,?)`)
    .bind(codigo, prev ? Number(prev.actual) || 0 : 0, val, 'Ajuste panel', '', t.fecha, t.iso, 'emp:' + emp).run();
  return j({ ok: true, codigo, empresa: emp, disponible: val });
}

