async function bodUsuariosGuardar(env, body) {
  if (!(await bodAuth(env, body.adminPin, ['dueno', 'admin']))) return j({ ok: false, error: 'PIN sin permiso' }, 403);
  const u = body.usuario || {};
  const pin = String(u.pin || '').trim();
  if (!pin) return j({ ok: false, error: 'Falta el PIN' }, 400);
  const t = crParts();
  const anterior = String(body.pinAnterior || '').trim();
  const rol = String(u.rol || 'solicitante'), nombre = String(u.nombre || ''), email = String(u.email || '');
  if (anterior && anterior !== pin) {
    const choque = await env.DB.prepare(`SELECT pin FROM usuarios WHERE pin=?`).bind(pin).first();
    if (choque) return j({ ok: false, error: 'Ese PIN ya está en uso' }, 400);
    await env.DB.prepare(`UPDATE usuarios SET pin=?, nombre=?, rol=?, email=?, activo=1, actualizado_en=? WHERE pin=?`)
      .bind(pin, nombre, rol, email, t.iso, anterior).run();
    return j({ ok: true, actualizado: pin });
  }
  const existe = await env.DB.prepare(`SELECT id FROM usuarios WHERE pin=?`).bind(pin).first();
  if (existe) {
    await env.DB.prepare(`UPDATE usuarios SET nombre=?, rol=?, email=?, activo=1, actualizado_en=? WHERE pin=?`)
      .bind(nombre, rol, email, t.iso, pin).run();
  } else {
    await env.DB.prepare(`INSERT INTO usuarios (id,pin,nombre,apellido,email,rol,empresa,activo,creado_en) VALUES (?,?,?,?,?,?,?,1,?)`)
      .bind('u_' + Math.random().toString(36).slice(2, 10), pin, nombre, '', email, rol, '', t.iso).run();
  }
  return j({ ok: true, guardado: pin });
}
