// Crea un PIN (últimos 4 de la cédula) para cada empleado sin usuario
async function bodGenerarPines(env, body) {
  if (!(await bodAuth(env, body.adminPin, ['dueno', 'admin']))) return j({ ok: false, error: 'PIN sin permiso' }, 403);
  const emps = (await env.DB.prepare(`SELECT nombre,cedula,email FROM empleados WHERE activo=1`).all()).results || [];
  const yaNombres = new Set(((await env.DB.prepare(`SELECT nombre,apellido FROM usuarios`).all()).results || [])
    .map(u => ((u.nombre || '') + (u.apellido ? ' ' + u.apellido : '')).trim().toLowerCase()));
  const t = crParts(); const creados = [];
  for (const e of emps) {
    const nom = String(e.nombre || '').trim();
    if (!nom || yaNombres.has(nom.toLowerCase())) continue;
    const ced = String(e.cedula || '').replace(/\D/g, '');
    if (ced.length < 4) continue;
    let pin = ced.slice(-4);
    let libre = !(await env.DB.prepare(`SELECT pin FROM usuarios WHERE pin=?`).bind(pin).first());
    if (!libre && ced.length >= 5) { pin = ced.slice(-5); libre = !(await env.DB.prepare(`SELECT pin FROM usuarios WHERE pin=?`).bind(pin).first()); }
    if (!libre) continue;
    await env.DB.prepare(`INSERT INTO usuarios (id,pin,nombre,apellido,email,rol,empresa,activo,creado_en) VALUES (?,?,?,?,?,?,?,1,?)`)
      .bind('u_' + Math.random().toString(36).slice(2, 10), pin, nom, '', String(e.email || ''), 'solicitante', '', t.iso).run();
    creados.push({ nombre: nom, pin });
  }
  return j({ ok: true, total: creados.length, creados });
}

