async function bodGuardarArchivo(env, body) {
  if (!env.ARCHIVOS) return j({ ok: false, error: 'R2 no configurado' }, 400);
  const carpeta = String(body.carpeta || 'archivos').replace(/[^a-zA-Z0-9_-]/g, '_');
  const numero = String(body.numero || '').replace(/[^a-zA-Z0-9_-]/g, '_');
  const nombre = String(body.nombre || 'archivo').replace(/[^a-zA-Z0-9._ -]/g, '_');
  const ruta = carpeta + '/' + (numero ? numero + '/' : '') + nombre;
  const bytes = Uint8Array.from(atob(soloBase64(String(body.base64 || ''))), c => c.charCodeAt(0));
  await env.ARCHIVOS.put(ruta, bytes, { httpMetadata: { contentType: String(body.contentType || 'application/octet-stream') } });
  return j({ ok: true, url: 'https://marc-erp.late-dew-2dd9.workers.dev/archivo/' + ruta });
}
async function bodCrearCompra(env, body) {
  const numero = String(body.numero || '').trim();
  if (!numero) return j({ ok: false, error: 'numero requerido' }, 400);
  const t = crParts();
  const datos = body.datos || {};
  let pdfUrl = String(body.pdfUrl || '');
  if (!pdfUrl && body.pdfBase64 && env.ARCHIVOS) {
    try {
      const ruta = 'compras/' + numero.replace(/[^a-zA-Z0-9_-]/g, '_') + '.pdf';
      const bytes = Uint8Array.from(atob(soloBase64(body.pdfBase64)), c => c.charCodeAt(0));
      await env.ARCHIVOS.put(ruta, bytes, { httpMetadata: { contentType: 'application/pdf' } });
      pdfUrl = 'https://marc-erp.late-dew-2dd9.workers.dev/archivo/' + ruta;
    } catch (e) {}
  }
  await env.DB.prepare(`INSERT INTO bod_compras (referencia,solicitud,items,motivo,estado,creado_en,pdf_url,datos) VALUES (?,?,?,?,?,?,?,?)`)
    .bind(numero, '', JSON.stringify(datos.items || []), String(datos.motivo || ''), 'pendiente', t.iso, pdfUrl, JSON.stringify(datos)).run();
  const items = (datos.items || []).map(it => `<li>${it.cantidad || ''} ${it.unidad || ''} — ${it.descripcion || it.nombre || ''}</li>`).join('');
  await bodEmail(env, ['compras@marcaire.com'],
    `🛒 ${numero} — Solicitud de compra de ${datos.solicitante || '—'} (${datos.proyecto || 'sin proyecto'})`,
    `<h2>${numero}</h2><p><b>Solicitante:</b> ${datos.solicitante || ''} · <b>Empresa:</b> ${datos.empresa || ''} · <b>Prioridad:</b> ${datos.prioridad || ''}</p>
     <p><b>Motivo:</b> ${datos.motivo || '—'}</p><ul>${items}</ul>${pdfUrl ? `<p><a href="${pdfUrl}">📄 Ver PDF</a></p>` : ''}`);
  return j({ ok: true, numero, url: pdfUrl });
}

