function bodImpAuth(env, body) { return String(body.key || '') === SETUP_KEY || body.adminPin; }
async function bodImportarDatos(env, body) {
  if (!(String(body.key || '') === SETUP_KEY || await bodAuth(env, body.adminPin))) return j({ ok: false, error: 'Sin permiso' }, 403);
  const tabla = String(body.tabla || ''), filas = Array.isArray(body.filas) ? body.filas : [];
  const modo = String(body.modo || 'upsert');
  const t = crParts(); let n = 0;
  if (tabla === 'catalogo') {
    if (modo === 'reemplazar') await env.DB.prepare(`DELETE FROM bod_catalogo`).run();
    for (const f of filas) {
      if (!f || !f.codigo) continue;
      await env.DB.prepare(`INSERT INTO bod_catalogo (codigo,empresa_legal,descripcion,unidad,categoria) VALUES (?,?,?,?,?)
        ON CONFLICT(codigo,empresa_legal) DO UPDATE SET descripcion=excluded.descripcion, unidad=excluded.unidad, categoria=excluded.categoria`)
        .bind(String(f.codigo), String(f.empresaLegal || f.empresa_legal || ''), String(f.descripcion || ''), String(f.unidad || ''), String(f.categoria || '')).run();
      n++;
    }
  } else if (tabla === 'empleados') {
    for (const f of filas) {
      if (!f || !f.nombre) continue;
      const ex = await env.DB.prepare(`SELECT id,email FROM empleados WHERE nombre=?`).bind(String(f.nombre)).first();
      const email = (body.incluirCorreos === false && ex) ? (ex.email || '') : String(f.email || (ex && ex.email) || '');
      if (ex) {
        await env.DB.prepare(`UPDATE empleados SET cedula=?, telefono=?, razon_social=?, email=?, activo=1 WHERE id=?`)
          .bind(String(f.cedula || ''), String(f.telefono || ''), String(f.empresaLegal || f.razon_social || ''), email, ex.id).run();
      } else {
        await env.DB.prepare(`INSERT INTO empleados (id,nombre,cedula,email,telefono,razon_social,empresa,activo,creado_en) VALUES (?,?,?,?,?,?,?,1,?)`)
          .bind('e_' + Math.random().toString(36).slice(2, 10), String(f.nombre), String(f.cedula || ''), email, String(f.telefono || ''), String(f.empresaLegal || f.razon_social || ''), '', t.iso).run();
      }
      n++;
    }
  } else return j({ ok: false, error: 'tabla desconocida: ' + tabla }, 400);
  return j({ ok: true, tabla, importados: n });
}
