// ============================================================
//  MÓDULO TRANSPORTES (tra_) — v22 (07-jul-2026)
//  Migrado de bodegas-marc-ap al NÚCLEO. Ruta: /transportes
//  · Un solo login (usuarios del núcleo) · Consecutivo STM- atómico
//  · Compatible con Transportes_MARC (Solicitantes) y app de choferes
// ============================================================

async function traEnsure(env) {
  if (_yaListo.traEnsure) return; _yaListo.traEnsure = true;   // v120 ⚡ una vez por instancia
  await env.DB.prepare(`CREATE TABLE IF NOT EXISTS tra_viajes (
    numero TEXT PRIMARY KEY,
    estado TEXT DEFAULT 'creado',
    solicitante TEXT, email TEXT, chofer TEXT,
    vehiculo TEXT, placa TEXT,
    fecha TEXT, hora TEXT,
    proyecto TEXT, origen TEXT, destino TEXT,
    bodega_ref TEXT, doc_url TEXT,
    payload TEXT,
    creado_en TEXT, actualizado_en TEXT
  )`).run();
  await env.DB.prepare(`INSERT OR IGNORE INTO contadores (nombre, valor) VALUES ('transportes', 1)`).run();
  // v24: centro de costos en cada viaje (ALTER individual: D1 truena en duplicados)
  try { await env.DB.prepare(`ALTER TABLE tra_viajes ADD COLUMN centro_costo TEXT DEFAULT ''`).run(); } catch (e) {}
}

// Campos planos a partir del payload del viaje (para columnas consultables)
function traCampos(v) {
  v = v || {};
  const sol = (v.solicitante && typeof v.solicitante === 'object') ? v.solicitante : {};
  const ch  = (v.chofer && typeof v.chofer === 'object') ? v.chofer : {};
  const ve  = (v.vehiculo && typeof v.vehiculo === 'object') ? v.vehiculo : {};
  const or_ = (v.origen && typeof v.origen === 'object') ? v.origen : {};
  const de  = (v.destino && typeof v.destino === 'object') ? v.destino : {};
  return {
    solicitante: typeof v.solicitante === 'string' ? v.solicitante : String(sol.empleado || ''),
    email:       String(sol.email || v.email || ''),
    chofer:      typeof v.chofer === 'string' ? v.chofer : String(ch.nombre || ''),
    vehiculo:    String(v.tipoVehiculo || ve.tipo || ''),
    placa:       String(v.placa || ve.placa || ''),
    fecha:       String(v.fechaNecesario || v.fecha || ''),
    hora:        String(v.horaNecesario || v.hora || ''),
    proyecto:    String(de.proyecto || v.proyecto || ''),
    origen:      typeof v.origen === 'string' ? v.origen : String(or_.direccion || ''),
    destino:     typeof v.destino === 'string' ? v.destino : String(de.direccion || ''),
    bodegaRef:   String(v.bodegaRef || ''),
    centroCosto: String(v.centroCosto || v.centro_costo || de.centroCosto || '')
  };
}

function traHaversine(a, b) {
  const R = 6371, rad = x => x * Math.PI / 180;
  const dLat = rad(b.lat - a.lat), dLng = rad(b.lng - a.lng);
  const s = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
            Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) * Math.sin(dLng / 2);
  return 2 * R * Math.asin(Math.sqrt(s));
}

// Km estimados: origen→destino si tienen GPS; si no, primer→último evento con GPS
function traKm(v) {
  const num = x => { const n = Number(x); return isFinite(n) ? n : null; };
  const pt = o => (o && num(o.lat) != null && num(o.lng) != null) ? { lat: num(o.lat), lng: num(o.lng) } : null;
  let A = pt(v.origen), B = pt(v.destino);
  if (!A || !B) {
    const evs = (Array.isArray(v.eventos) ? v.eventos : []).map(e => e && e.gps ? pt(e.gps) : null).filter(Boolean);
    if (evs.length >= 2) { A = evs[0]; B = evs[evs.length - 1]; }
  }
  if (!A || !B) return null;
  return Math.round(traHaversine(A, B) * 10) / 10;
}

// Minutos entre el evento de recogida y el de entrega (si existen)
function traMinutos(v) {
  const evs = Array.isArray(v.eventos) ? v.eventos : [];
  const busca = pal => { const e = evs.filter(x => x && String(x.estado || '').toLowerCase().indexOf(pal) !== -1).pop(); return e && e.timestamp ? new Date(e.timestamp) : null; };
  const r = busca('recog'), en = busca('entreg');
  if (!r || !en) return null;
  const m = Math.round((en - r) / 60000);
  return m >= 0 ? m : null;
}

// POST {accion:'crearViaje', viaje:{...}} → asigna STM-N atómico y guarda
async function traCrearViaje(env, body) {
  const v = (body && body.viaje && typeof body.viaje === 'object') ? body.viaje : null;
  if (!v) return j({ ok: false, error: 'Falta el objeto viaje' }, 400);
  const t = crParts();
  const numero = await siguienteNumero(env, 'transportes', 'STM-');
  v.numero = numero;
  v.estado = v.estado || 'creado';
  v.creadoEn = v.creadoEn || t.iso;
  v.ultimaActualizacion = t.iso;
  const c = traCampos(v);
  await env.DB.prepare(`INSERT INTO tra_viajes (numero,estado,solicitante,email,chofer,vehiculo,placa,fecha,hora,proyecto,centro_costo,origen,destino,bodega_ref,doc_url,payload,creado_en,actualizado_en)
    VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`)
    .bind(numero, v.estado, c.solicitante, c.email, c.chofer, c.vehiculo, c.placa, c.fecha, c.hora,
      c.proyecto, c.centroCosto, c.origen, c.destino, c.bodegaRef, '', JSON.stringify(v), t.iso, t.iso).run();
  // Aviso por correo al solicitante (best-effort; nunca bloquea)
  if (c.email && /@/.test(c.email)) {
    await bodEmail(env, [c.email], '🚚 ' + numero + ' — Solicitud de transporte creada',
      '<h2>' + numero + '</h2><p>Tu solicitud de viaje fue registrada.</p>' +
      '<p><b>Chofer:</b> ' + (c.chofer || '—') + ' · <b>Fecha:</b> ' + c.fecha + ' ' + c.hora + '</p>' +
      '<p><b>Recoger en:</b> ' + (c.origen || '—') + '<br><b>Entregar en:</b> ' + (c.destino || '—') + '</p>');
  }
  // WhatsApp: aviso al CHOFER (plantilla viaje_asignado)
  try {
    if (c.chofer) {
      const telCh = await waTelPara(env, { nombre: c.chofer });
      if (telCh) await enviarPlantilla(env, telCh, WA_TPL.viaje_asignado,
        { '1': numero, '2': c.origen || '—', '3': c.destino || '—', '4': c.fecha || '', '5': c.hora || '' }, 'viaje_asignado');
    }
  } catch (e) { console.log('wa traCrear', e.message); }
  return j({ ok: true, numero });
}

// POST {accion:'listarViajes'} → payloads completos (los consume el Excel del equipo)
async function traListarViajes(env) {
  const rows = (await env.DB.prepare(`SELECT payload FROM tra_viajes ORDER BY creado_en DESC LIMIT 1000`).all()).results || [];
  const viajes = [];
  rows.forEach(r => { try { viajes.push(JSON.parse(r.payload)); } catch (e) {} });
  return j({ ok: true, viajes });
}

// POST {accion:'actualizarViaje', numero, viaje?} o {numero, estado, evento?}
// (lo usa la app de choferes: cambio de estado, GPS, km, firma de recepción)
async function traActualizarViaje(env, body) {
  const numero = String(body.numero || (body.viaje && body.viaje.numero) || '').trim();
  if (!numero) return j({ ok: false, error: 'numero requerido' }, 400);
  const row = await env.DB.prepare(`SELECT payload FROM tra_viajes WHERE numero=?`).bind(numero).first();
  if (!row) return j({ ok: false, error: 'Viaje no existe: ' + numero }, 404);
  const t = crParts();
  let v = {}; try { v = JSON.parse(row.payload) || {}; } catch (e) {}
  if (body.viaje && typeof body.viaje === 'object') {
    v = body.viaje; v.numero = numero;                 // reemplazo completo (la app manda todo)
  } else {
    if (body.estado) {
      v.estado = String(body.estado);
      if (!Array.isArray(v.eventos)) v.eventos = [];
      const ev = (body.evento && typeof body.evento === 'object') ? body.evento : {};
      v.eventos.push({ estado: v.estado, timestamp: ev.timestamp || t.iso, por: ev.por || '', gps: ev.gps || null, foto: ev.foto || null });
    }
    if (body.recepcion && typeof body.recepcion === 'object') v.recepcion = body.recepcion;
    if (body.kmFinal != null) { v.vehiculo = v.vehiculo || {}; v.vehiculo.kmFinal = body.kmFinal; }
  }
  v.ultimaActualizacion = t.iso;
  // v62/v64 — al ENTREGAR con centro de costos, el costo cae solo al CC
  await traEspejarCostoCC(env, numero, v, t);
  const c = traCampos(v);
  await env.DB.prepare(`UPDATE tra_viajes SET estado=?, solicitante=?, email=?, chofer=?, vehiculo=?, placa=?, fecha=?, hora=?, proyecto=?, origen=?, destino=?, bodega_ref=?, payload=?, actualizado_en=? WHERE numero=?`)
    .bind(String(v.estado || 'creado'), c.solicitante, c.email, c.chofer, c.vehiculo, c.placa, c.fecha, c.hora,
      c.proyecto, c.origen, c.destino, c.bodegaRef, JSON.stringify(v), t.iso, numero).run();
  return j({ ok: true, numero, estado: v.estado });
}

// v64 — Espejo del costo del viaje al Centro de Costos (familia TRA).
// Corre cuando el viaje pasa a 'entregado' con centro de costo. Una sola
// vez por viaje (bandera ccEspejado en el payload). Moneda CRC: los
// reportes de CC suman monto directo, así que nunca mezclamos monedas.
// El costo sale de: costoEstimado | costo | costoTotal | costos.total |
// estimacion.costo | (km × costoKm). Devuelve el espejo o null.
async function traEspejarCostoCC(env, numero, v, t) {
  try {
    const cPrev = traCampos(v);
    if (String(v.estado || '') !== 'entregado' || v.ccEspejado || !cPrev.centroCosto) return null;
    const numDe = (x) => { const q = Number(String(x == null ? '' : x).replace(/[^0-9.\-]/g, '')); return isFinite(q) ? q : 0; };
    let costo = numDe(v.costoEstimado) || numDe(v.costo) || numDe(v.costoTotal) ||
      (v.costos ? numDe(v.costos.total) : 0) || (v.estimacion ? numDe(v.estimacion.costo) : 0);
    if (!costo) { const km = numDe(v.km) || numDe(v.distanciaKm); const cKm = numDe(v.costoKm) || numDe(v.costoPorKm); if (km && cKm) costo = finR2(km * cKm); }
    if (!(costo > 0)) return null;
    const esp = await ccEspejo(env, String(cPrev.centroCosto).trim(), { tipo: 'gasto', familia: 'TRA',
      pista: 'transporte', origen: 'transporte',
      descripcion: 'Viaje ' + numero + ' entregado — ' + (cPrev.origen || '') + ' → ' + (cPrev.destino || '') +
        (cPrev.chofer ? ' · Chofer: ' + cPrev.chofer : ''),
      referencia: numero, moneda: 'CRC', monto: costo, usuario: cPrev.chofer || 'transportes' });
    if (esp) v.ccEspejado = { mov_id: esp.mov_id, monto: costo, en: t.iso };
    return esp;
  } catch (e) { return null; }
}

// POST {accion:'verificarConflicto', chofer, fecha, hora}
// Mismo chofer, misma fecha, hora a menos de 90 min, viaje aún no entregado/cancelado.
async function traVerificarConflicto(env, body) {
  const chofer = String(body.chofer || '').trim();
  const fecha = String(body.fecha || '').trim();
  const hora = String(body.hora || '').trim();
  if (!chofer || !fecha || !hora) return j({ ok: true, conflicto: false });
  const aMin = h => { const p = String(h || '').split(':'); return (parseInt(p[0], 10) || 0) * 60 + (parseInt(p[1], 10) || 0); };
  const objetivo = aMin(hora);
  const rows = (await env.DB.prepare(`SELECT numero,estado,hora,solicitante,destino,fecha FROM tra_viajes
    WHERE chofer=? AND fecha=? AND estado NOT IN ('entregado','cancelado')`).bind(chofer, fecha).all()).results || [];
  let peor = null, menorDif = 91;
  rows.forEach(r => { const d = Math.abs(aMin(r.hora) - objetivo); if (d < menorDif) { menorDif = d; peor = r; } });
  if (!peor) return j({ ok: true, conflicto: false });
  return j({ ok: true, conflicto: true, viajeConflicto: {
    numero: peor.numero, fecha: peor.fecha, hora: peor.hora, estado: peor.estado,
    solicitante: peor.solicitante || '', destino: peor.destino || '' } });
}

// POST {accion:'subirDocumento', numero, nombreArchivo, tipoMime, base64} → R2 transportes/
async function traSubirDocumento(env, body) {
  if (!env.ARCHIVOS) return j({ ok: false, error: 'R2 no configurado (binding ARCHIVOS)' }, 400);
  const numero = String(body.numero || '').trim();
  const nombre = String(body.nombreArchivo || 'documento.pdf').replace(/[^a-zA-Z0-9_.\-]/g, '_');
  const b64 = String(body.base64 || '');
  if (!numero || !b64) return j({ ok: false, error: 'numero y base64 requeridos' }, 400);
  const extDoc = nombre.split('.').pop().toLowerCase();
  if (!SEG_EXT_OK.has(extDoc)) return j({ ok: false, error: 'Tipo de archivo no permitido: .' + extDoc }, 400);   // v63
  const bin = traB64(b64);
  if (!bin) return j({ ok: false, error: 'base64 inválido' }, 400);
  if (bin.length > 8 * 1024 * 1024) return j({ ok: false, error: 'Archivo demasiado grande (máx 8 MB)' }, 400);   // v144
  // v144 — sello de tiempo en la clave: dos archivos con el mismo nombre ya no se pisan
  const key = 'transportes/' + numero.replace(/[^a-zA-Z0-9_-]/g, '_') + '/' + Date.now().toString(36) + '_' + nombre;
  await env.ARCHIVOS.put(key, bin, { httpMetadata: { contentType: SEG_MIME_POR_EXT[extDoc] || 'application/octet-stream' } });   // v63: MIME por extensión
  const urlDoc = '/archivo/' + key;
  const row = await env.DB.prepare(`SELECT payload FROM tra_viajes WHERE numero=?`).bind(numero).first();
  let total = 1;
  if (row) {
    const t = crParts();
    let v = {}; try { v = JSON.parse(row.payload) || {}; } catch (e) {}
    // v144 — ADJUNTOS MÚLTIPLES: se acumulan, ya NO se pisan
    if (!Array.isArray(v.documentos)) v.documentos = [];
    // el documento único de versiones viejas pasa a ser el primero de la lista
    if (v.documento && v.documento.url && !v.documentos.some(d => d && d.url === v.documento.url))
      v.documentos.unshift(v.documento);
    let quien = '';
    if (body.pin) { const uu = await traAuthUsuario(env, body.pin); if (uu) quien = ((uu.nombre || '') + (uu.apellido ? ' ' + uu.apellido : '')).trim(); }
    const nuevo = { nombre, url: urlDoc, tipo: traTipoArchivo(nombre),
      categoria: String(body.categoria || '').slice(0, 40), subidoEn: t.iso, por: quien };
    v.documentos.push(nuevo);
    v.documento = nuevo;   // compatibilidad: "el documento" sigue siendo el último
    total = v.documentos.filter(d => d && d.url && !d.eliminado).length;
    await env.DB.prepare(`UPDATE tra_viajes SET doc_url=?, payload=?, actualizado_en=? WHERE numero=?`)
      .bind(urlDoc, JSON.stringify(v), t.iso, numero).run();
  }
  return j({ ok: true, url: urlDoc, nombre, tipo: traTipoArchivo(nombre), total });
}

// POST {accion:'dashboard', adminPin, desde, hasta} → tarjetas + tabla + km/tiempos
async function traDashboard(env, body) {
  if (!(await bodAuth(env, body.adminPin, ['dueno', 'admin', 'compras']))) return j({ ok: false, error: 'PIN sin permiso' }, 403);
  let sql = `SELECT * FROM tra_viajes WHERE 1=1`; const binds = [];
  if (body.desde) { sql += ` AND fecha>=?`; binds.push(String(body.desde)); }
  if (body.hasta) { sql += ` AND fecha<=?`; binds.push(String(body.hasta)); }
  sql += ` ORDER BY fecha DESC, hora DESC LIMIT 800`;
  const rows = (await env.DB.prepare(sql).bind(...binds).all()).results || [];
  const porEstado = {}, kmPorChofer = {}, kmPorVehiculo = {};
  let kmTotal = 0, kmCount = 0, minTotal = 0, minCount = 0;
  const viajes = rows.map(r => {
    let v = {}; try { v = JSON.parse(r.payload) || {}; } catch (e) {}
    const est = r.estado || 'creado';
    porEstado[est] = (porEstado[est] || 0) + 1;
    const km = traKm(v);
    if (km != null) {
      kmTotal += km; kmCount++;
      if (r.chofer) kmPorChofer[r.chofer] = Math.round(((kmPorChofer[r.chofer] || 0) + km) * 10) / 10;
      const veh = ((r.vehiculo || '') + (r.placa ? ' ' + r.placa : '')).trim();
      if (veh) kmPorVehiculo[veh] = Math.round(((kmPorVehiculo[veh] || 0) + km) * 10) / 10;
    }
    const mins = traMinutos(v);
    if (mins != null) { minTotal += mins; minCount++; }
    return { numero: r.numero, estado: est, chofer: r.chofer || '', destino: r.destino || '',
      km, fechaNecesario: r.fecha || '', fecha: r.fecha || '', bodegaRef: r.bodega_ref || '' };
  });
  return j({ ok: true, total: rows.length, porEstado, viajes,
    kmTotal: Math.round(kmTotal * 10) / 10, kmCount,
    tiempoPromMin: minCount ? Math.round(minTotal / minCount) : null,
    kmPorChofer, kmPorVehiculo });
}

// ============================================================
//  v25 · ACCIONES DE LA APP DE CHOFERES (auth de SERVIDOR)
//  Cada acción exige un PIN de usuario ACTIVO del núcleo. El PIN
//  identifica quién ejecutó la acción y queda en el historial.
// ============================================================

// PIN válido → fila de usuario · PIN inválido → null
async function traAuthUsuario(env, pin) {
  const p = String(pin || '').trim();
  if (!p) return null;
  try {
    return await env.DB.prepare('SELECT id,nombre,apellido,rol FROM usuarios WHERE pin=? AND activo=1').bind(p).first();
  } catch (e) { return null; }
}

// base64 (con o sin prefijo dataURL) → Uint8Array, o null si viene corrupto
function traB64(b64) {
  try {
    return Uint8Array.from(atob(String(b64 || '').replace(/^data:[^,]*,/, '')), ch => ch.charCodeAt(0));
  } catch (e) { return null; }
}

// Lista blanca de MIME por tipo de subida (revisión de bóveda: Alto 4)
const TRA_MIME_IMG = ['image/jpeg', 'image/png', 'image/webp'];
// v144 — clasifica un adjunto por su extensión para que la app sepa qué ícono pintar
function traTipoArchivo(nombreOUrl) {
  const ext = String(nombreOUrl || '').split('?')[0].split('.').pop().toLowerCase();
  if (['jpg', 'jpeg', 'png', 'webp', 'gif', 'heic'].indexOf(ext) !== -1) return 'imagen';
  if (ext === 'pdf') return 'pdf';
  if (['xlsx', 'xls', 'csv'].indexOf(ext) !== -1) return 'excel';
  if (['docx', 'doc'].indexOf(ext) !== -1) return 'word';
  return 'otro';
}
// v144 — ¿este usuario manda sobre los adjuntos de cualquiera?
function traEsGerencia(u) {
  return ['dueno', 'dueño', 'admin', 'compras', 'gerencia'].indexOf(String((u && u.rol) || '').toLowerCase()) !== -1;
}
const TRA_MIME_DOC = ['image/jpeg', 'image/png', 'image/webp', 'application/pdf'];

// Guarda el payload de un viaje refrescando las columnas planas
async function traGuardar(env, numero, v) {
  const t = crParts();
  v.ultimaActualizacion = t.iso;
  const c = traCampos(v);
  await env.DB.prepare(`UPDATE tra_viajes SET estado=?, solicitante=?, email=?, chofer=?, vehiculo=?, placa=?, fecha=?, hora=?, proyecto=?, origen=?, destino=?, bodega_ref=?, payload=?, actualizado_en=? WHERE numero=?`)
    .bind(String(v.estado || 'creado'), c.solicitante, c.email, c.chofer, c.vehiculo, c.placa, c.fecha, c.hora,
      c.proyecto, c.origen, c.destino, c.bodegaRef, JSON.stringify(v), t.iso, numero).run();
  return t;
}

async function traCargar(env, numero) {
  const row = await env.DB.prepare(`SELECT payload FROM tra_viajes WHERE numero=?`).bind(numero).first();
  if (!row) return null;
  let v = {}; try { v = JSON.parse(row.payload) || {}; } catch (e) {}
  return v;
}

// POST {accion:'obtenerViaje', pin, numero} → payload completo de UN viaje
// v135 · POST {accion:'adjuntosViaje', pin, numero}
// Devuelve TODOS los adjuntos visibles para el chofer de un viaje:
//  · documento subido en la app de Transportes (v.documento / v.documentoAdjunto)
//  · PDF de la solicitud de bodega ligada (bod_solicitudes.pdf_url)
//  · fotos de esa solicitud (externalizadas a R2 al primer uso)
// v144 · POST {accion:'eliminarAdjunto', pin, numero, url}
// Borra un adjunto del viaje dejando lápida (queda el rastro).
// Candados: solo quien lo subió o gerencia; los archivos de la solicitud
// de bodega NO se pueden borrar desde acá; las firmas tampoco se tocan.
async function traEliminarAdjunto(env, body) {
  const u = await traAuthUsuario(env, body.pin);
  if (!u) return j({ ok: false, error: 'PIN inválido' }, 403);
  const numero = String(body.numero || '').trim();
  const url = String(body.url || '').trim();
  if (!numero || !url) return j({ ok: false, error: 'numero y url requeridos' }, 400);
  const v = await traCargar(env, numero);
  if (!v) return j({ ok: false, error: 'Viaje no existe: ' + numero }, 404);
  const quien = ((u.nombre || '') + (u.apellido ? ' ' + u.apellido : '')).trim();
  const mandaSobreTodo = traEsGerencia(u);
  // Se busca SOLO entre los documentos del viaje y las fotos del chofer:
  // así, lo que viene de la solicitud de bodega queda fuera de alcance.
  let item = null, lista = '';
  if (Array.isArray(v.documentos)) { const f = v.documentos.find(d => d && d.url === url && !d.eliminado); if (f) { item = f; lista = 'documento'; } }
  if (!item && Array.isArray(v.fotos)) { const f = v.fotos.find(d => d && d.url === url && !d.eliminado); if (f) { item = f; lista = 'foto'; } }
  if (!item && v.documento && v.documento.url === url && !v.documento.eliminado) { item = v.documento; lista = 'documento'; }
  if (!item) return j({ ok: false, error: 'Ese archivo no se puede eliminar desde aquí (viene de la solicitud de bodega o ya fue eliminado)' }, 403);
  if (item.por && item.por !== quien && !mandaSobreTodo)
    return j({ ok: false, error: 'Ese archivo lo subió ' + item.por + '. Solo esa persona o gerencia puede eliminarlo.' }, 403);
  if (!item.por && !mandaSobreTodo)
    return j({ ok: false, error: 'Ese archivo es de la oficina. Pedile a gerencia que lo elimine.' }, 403);
  const t = crParts();
  item.eliminado = { por: quien, en: t.iso };
  // El "documento único" (compatibilidad) pasa a ser el último que sigue vivo
  const vivos = Array.isArray(v.documentos) ? v.documentos.filter(d => d && d.url && !d.eliminado) : [];
  v.documento = vivos.length ? vivos[vivos.length - 1] : null;
  if (!Array.isArray(v.eventos)) v.eventos = [];
  v.eventos.push({ estado: 'adjunto eliminado', timestamp: t.iso, por: quien,
    notas: 'Eliminó ' + (lista === 'foto' ? 'la foto' : 'el archivo') + ' ' + (item.nombre || item.tipo || '') });
  await env.DB.prepare(`UPDATE tra_viajes SET doc_url=?, payload=?, actualizado_en=? WHERE numero=?`)
    .bind(v.documento ? String(v.documento.url || '') : '', JSON.stringify(v), t.iso, numero).run();
  return j({ ok: true, url, restantes: vivos.length });
}

async function traAdjuntosViaje(env, body) {
  const u = await traAuthUsuario(env, body.pin);
  if (!u) return j({ ok: false, error: 'PIN inválido' }, 403);
  const numero = String(body.numero || '').trim();
  if (!numero) return j({ ok: false, error: 'numero requerido' }, 400);
  const v = await traCargar(env, numero);
  if (!v) return j({ ok: false, error: 'Viaje no existe: ' + numero }, 404);
  const adjuntos = [];
  const vistos = {};
  const sumar = (o) => { if (o && o.url && !vistos[o.url]) { vistos[o.url] = 1; adjuntos.push(o); } };
  // 1) v144 — TODOS los documentos del viaje (factura, OC, proforma, Excel...)
  if (Array.isArray(v.documentos)) {
    for (const d of v.documentos) {
      if (!d || !d.url || d.eliminado) continue;   // los borrados no se listan
      sumar({ tipo: d.tipo || traTipoArchivo(d.nombre || d.url), nombre: String(d.nombre || 'Documento'),
        url: String(d.url), origen: 'transportes', categoria: d.categoria || '',
        por: d.por || '', en: d.subidoEn || '', borrable: true });
    }
  }
  // Compatibilidad con viajes viejos (documento único y formato anterior)
  if (v.documento && v.documento.url && !v.documento.eliminado)
    sumar({ tipo: v.documento.tipo || traTipoArchivo(v.documento.nombre || v.documento.url),
      nombre: String(v.documento.nombre || 'Documento del viaje'), url: String(v.documento.url),
      origen: 'transportes', borrable: true });
  if (v.documentoAdjunto && v.documentoAdjunto.url)
    sumar({ tipo: traTipoArchivo(v.documentoAdjunto.nombre || v.documentoAdjunto.url),
      nombre: String(v.documentoAdjunto.nombre || 'Documento del viaje'), url: String(v.documentoAdjunto.url),
      origen: 'transportes', borrable: true });
  // 1b) v144 — fotos de evidencia que tomó el chofer (puede borrar la que salió mala)
  if (Array.isArray(v.fotos)) {
    for (const f of v.fotos) {
      if (!f || !f.url || f.eliminado) continue;
      sumar({ tipo: 'imagen', nombre: 'Foto ' + String(f.tipo || 'evidencia').replace(/_/g, ' '),
        url: String(f.url), origen: 'chofer', por: f.por || '', en: f.en || '', borrable: true });
    }
  }
  // 2) Solicitud de bodega ligada
  const ref = String(v.bodegaRef || '').trim().toUpperCase();
  if (ref) {
    try {
      const fila = await env.DB.prepare('SELECT payload, pdf_url FROM bod_solicitudes WHERE UPPER(numero)=?').bind(ref).first();
      if (fila) {
        if (fila.pdf_url) sumar({ tipo: 'pdf', nombre: 'Solicitud ' + ref + ' (PDF)', url: String(fila.pdf_url), origen: 'bodega', borrable: false });
        let p = {}; try { p = JSON.parse(fila.payload) || {}; } catch (e) {}
        if (Array.isArray(p.fotos) && p.fotos.length) {
          let cambio = false;
          for (let i = 0; i < p.fotos.length; i++) {
            const f = p.fotos[i];
            if (typeof f !== 'string' || !f) continue;
            if (f.indexOf('data:') === 0) {
              // Externalizar a R2 (una sola vez); si falla, se conserva y no se lista
              if (!env.ARCHIVOS) continue;
              const bin = traB64(f);
              if (!bin || !bin.length || bin.length > 8 * 1024 * 1024) continue;
              const m = f.match(/^data:([^;,]+)[;,]/);
              const mime = (m && TRA_MIME_IMG.indexOf(String(m[1]).toLowerCase()) !== -1) ? String(m[1]).toLowerCase() : 'image/jpeg';
              const ext = mime === 'image/png' ? 'png' : (mime === 'image/webp' ? 'webp' : 'jpg');
              const key = 'bodega/' + ref.replace(/[^a-zA-Z0-9_-]/g, '_') + '/foto_' + i + '.' + ext;
              try {
                await env.ARCHIVOS.put(key, bin, { httpMetadata: { contentType: mime } });
                p.fotos[i] = '/archivo/' + key;
                cambio = true;
              } catch (e) { continue; }
            }
            if (typeof p.fotos[i] === 'string' && (p.fotos[i].indexOf('/') === 0 || p.fotos[i].indexOf('http') === 0))
              sumar({ tipo: 'imagen', nombre: 'Foto de bodega ' + (i + 1), url: p.fotos[i], origen: 'bodega', borrable: false });
          }
          if (cambio) {
            const t = crParts();
            await env.DB.prepare('UPDATE bod_solicitudes SET payload=?, actualizado_en=? WHERE UPPER(numero)=?')
              .bind(JSON.stringify(p), t.iso, ref).run();
          }
        }
      }
    } catch (e) { /* bodega no disponible: se devuelven los del viaje igual */ }
  }
  return j({ ok: true, numero, bodegaRef: ref || '', adjuntos });
}

async function traObtenerViaje(env, body) {
  const u = await traAuthUsuario(env, body.pin);
  if (!u) return j({ ok: false, error: 'PIN inválido' }, 403);
  const numero = String(body.numero || '').trim();
  if (!numero) return j({ ok: false, error: 'numero requerido' }, 400);
  const v = await traCargar(env, numero);
  if (!v) return j({ ok: false, error: 'Viaje no existe: ' + numero }, 404);
  return j({ ok: true, viaje: v });
}

// POST {accion:'tomarViaje', pin, numero, nuevoChofer, choferAnterior, externo}
// Reasigna el viaje al chofer que lo toma y deja rastro en el historial.
async function traTomarViaje(env, body) {
  const u = await traAuthUsuario(env, body.pin);
  if (!u) return j({ ok: false, error: 'PIN inválido' }, 403);
  const numero = String(body.numero || '').trim();
  const nuevo = String(body.nuevoChofer || '').trim();
  if (!numero || !nuevo) return j({ ok: false, error: 'numero y nuevoChofer requeridos' }, 400);
  const v = await traCargar(env, numero);
  if (!v) return j({ ok: false, error: 'Viaje no existe: ' + numero }, 404);
  if (String(v.estado || '').toLowerCase() === 'entregado') return j({ ok: false, error: 'El viaje ya fue entregado' }, 400);
  const anterior = (v.chofer && typeof v.chofer === 'object') ? String(v.chofer.nombre || '') : String(v.chofer || '');
  if (v.chofer && typeof v.chofer === 'object') { v.chofer.nombre = nuevo; }
  else { v.chofer = { nombre: nuevo }; }
  if (body.externo && typeof body.externo === 'object') v.chofer.externo = body.externo;
  if (!Array.isArray(v.eventos)) v.eventos = [];
  const t = crParts();
  v.eventos.push({ estado: 'reasignado', timestamp: t.iso,
    por: ((u.nombre || '') + (u.apellido ? ' ' + u.apellido : '')).trim() || nuevo,
    notas: 'Tomó el viaje ' + (anterior ? 'que estaba asignado a ' + anterior : 'que no tenía chofer asignado') });
  await traGuardar(env, numero, v);
  return j({ ok: true, numero, chofer: nuevo });
}

// POST {accion:'actualizarEstado', pin, numero, nuevoEstado, evento:{por,gps,foto,notas,externo}}
async function traActualizarEstado(env, body) {
  const u = await traAuthUsuario(env, body.pin);
  if (!u) return j({ ok: false, error: 'PIN inválido' }, 403);
  const numero = String(body.numero || '').trim();
  const nuevoEstado = String(body.nuevoEstado || '').trim().toLowerCase();
  if (!numero || !nuevoEstado) return j({ ok: false, error: 'numero y nuevoEstado requeridos' }, 400);
  if (['creado', 'asignado', 'recogido', 'entregado', 'cancelado'].indexOf(nuevoEstado) === -1)
    return j({ ok: false, error: 'Estado no permitido: ' + nuevoEstado }, 400);
  const v = await traCargar(env, numero);
  if (!v) return j({ ok: false, error: 'Viaje no existe: ' + numero }, 404);
  const t = crParts();
  const ev = (body.evento && typeof body.evento === 'object') ? body.evento : {};
  v.estado = nuevoEstado;
  if (!Array.isArray(v.eventos)) v.eventos = [];
  v.eventos.push({ estado: nuevoEstado, timestamp: ev.timestamp || t.iso,
    por: String(ev.por || ((u.nombre || '') + (u.apellido ? ' ' + u.apellido : '')).trim()),
    gps: ev.gps || null, foto: ev.foto || null, notas: String(ev.notas || ''),
    externo: (ev.externo && typeof ev.externo === 'object') ? ev.externo : null });
  // v64 — la app de choferes puede mandar el costo del recorrido
  const numOk = (x) => { const q = Number(x); return isFinite(q) && q > 0 ? q : null; };
  if (numOk(body.km)) v.km = numOk(body.km);
  if (numOk(body.costoKm)) v.costoKm = numOk(body.costoKm);
  if (numOk(body.costoEstimado)) v.costoEstimado = numOk(body.costoEstimado);
  // v64 — si el CHOFER entrega un viaje con centro de costo, el gasto cae al CC
  await traEspejarCostoCC(env, numero, v, t);
  await traGuardar(env, numero, v);
  // WhatsApp: aviso al solicitante en recogido/entregado (plantillas)
  try {
    if (nuevoEstado === 'recogido' || nuevoEstado === 'entregado') {
      const cc = traCampos(v);
      const telSol = await waTelPara(env, { email: cc.email, nombre: cc.solicitante });
      if (telSol) await enviarPlantilla(env, telSol,
        nuevoEstado === 'recogido' ? WA_TPL.viaje_recogido : WA_TPL.viaje_entregado,
        { '1': numero }, 'viaje_' + nuevoEstado);
    }
  } catch (e) { console.log('wa traEstado', e.message); }
  return j({ ok: true, numero, estado: nuevoEstado });
}

// Subida genérica a R2 transportes/<STM>/ con lista blanca de MIME
async function traSubirBinario(env, body, opciones) {
  if (!env.ARCHIVOS) return j({ ok: false, error: 'R2 no configurado (binding ARCHIVOS)' }, 400);
  const u = await traAuthUsuario(env, body.pin);
  if (!u) return j({ ok: false, error: 'PIN inválido' }, 403);
  const numero = String(body.numero || '').trim();
  if (!numero) return j({ ok: false, error: 'numero requerido' }, 400);
  const bin = traB64(body.base64);
  if (!bin || !bin.length) return j({ ok: false, error: 'base64 inválido o vacío' }, 400);
  if (bin.length > 8 * 1024 * 1024) return j({ ok: false, error: 'Archivo demasiado grande (máx 8 MB)' }, 400);
  // MIME: se toma del prefijo dataURL si viene; si no, del body; y se valida
  let mime = String(body.tipoMime || '').toLowerCase();
  const m = String(body.base64 || '').match(/^data:([^;,]+)[;,]/);
  if (m && m[1]) mime = m[1].toLowerCase();
  if (!mime) mime = opciones.mimeDefault;
  if (opciones.mimes.indexOf(mime) === -1) return j({ ok: false, error: 'Tipo de archivo no permitido: ' + mime }, 400);
  const ext = mime === 'application/pdf' ? 'pdf' : (mime === 'image/png' ? 'png' : (mime === 'image/webp' ? 'webp' : 'jpg'));
  const key = 'transportes/' + numero.replace(/[^a-zA-Z0-9_-]/g, '_') + '/' + opciones.prefijo + '_' + Date.now() + '.' + ext;
  await env.ARCHIVOS.put(key, bin, { httpMetadata: { contentType: mime } });
  const v = await traCargar(env, numero);
  const t = crParts();
  const por = ((u.nombre || '') + (u.apellido ? ' ' + u.apellido : '')).trim();
  const url = '/archivo/' + key;
  if (v) { opciones.registrar(v, url, por, t.iso, body); await traGuardar(env, numero, v); }
  return j({ ok: true, url });
}

// POST {accion:'subirFoto', pin, numero, tipoFoto, base64}
async function traSubirFoto(env, body) {
  const tipo = String(body.tipoFoto || 'evidencia').replace(/[^a-z0-9_-]/gi, '_');
  return await traSubirBinario(env, body, {
    mimes: TRA_MIME_IMG, mimeDefault: 'image/jpeg', prefijo: 'foto_' + tipo,
    registrar: (v, url, por, iso) => {
      if (!Array.isArray(v.fotos)) v.fotos = [];
      v.fotos.push({ tipo, url, por, en: iso });
    }
  });
}

// POST {accion:'subirFirma', pin, numero, tipoFirma, base64, nombreFirmante}
async function traSubirFirma(env, body) {
  const tipo = String(body.tipoFirma || 'firma').replace(/[^a-z0-9_-]/gi, '_');
  return await traSubirBinario(env, body, {
    mimes: TRA_MIME_IMG, mimeDefault: 'image/png', prefijo: 'firma_' + tipo,
    registrar: (v, url, por, iso, b) => {
      if (!v.firmas || typeof v.firmas !== 'object') v.firmas = {};
      v.firmas[tipo] = { url, nombreFirmante: String(b.nombreFirmante || por), en: iso };
    }
  });
}

// POST {accion:'subirDocFirmado', pin, numero, base64, nombreFirmante, tipoMime}
async function traSubirDocFirmado(env, body) {
  return await traSubirBinario(env, body, {
    mimes: TRA_MIME_DOC, mimeDefault: 'image/png', prefijo: 'doc_firmado',
    registrar: (v, url, por, iso, b) => {
      v.documentoFirmado = { url, nombreFirmante: String(b.nombreFirmante || por), en: iso };
    }
  });
}

// ---- MIGRACIÓN desde bodegas-marc-ap (clave SETUP_KEY) ----
// POST {accion:'importar', key, filas:[viaje,...]} (máx 800 por tanda)
async function traImportar(env, body) {
  if (String(body.key || '') !== SETUP_KEY) return j({ ok: false, error: 'Clave incorrecta' }, 403);
  const filas = Array.isArray(body.filas) ? body.filas : [];
  if (!filas.length) return j({ ok: false, error: 'filas vacías' }, 400);
  if (filas.length > 800) return j({ ok: false, error: 'Máximo 800 filas por tanda' }, 400);
  const t = crParts(); let n = 0, maxNum = 0;
  for (const v of filas) {
    const numero = String((v && v.numero) || '').trim();
    if (!numero) continue;
    const c = traCampos(v);
    await env.DB.prepare(`INSERT INTO tra_viajes (numero,estado,solicitante,email,chofer,vehiculo,placa,fecha,hora,proyecto,origen,destino,bodega_ref,doc_url,payload,creado_en,actualizado_en)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
      ON CONFLICT(numero) DO UPDATE SET estado=excluded.estado, payload=excluded.payload, actualizado_en=excluded.actualizado_en`)
      .bind(numero, String(v.estado || 'creado'), c.solicitante, c.email, c.chofer, c.vehiculo, c.placa,
        c.fecha, c.hora, c.proyecto, c.origen, c.destino, c.bodegaRef, '', JSON.stringify(v),
        String(v.creadoEn || t.iso), t.iso).run();
    const m = numero.match(/(\d+)\s*$/); if (m) maxNum = Math.max(maxNum, parseInt(m[1], 10) || 0);
    n++;
  }
  // Deja el contador al día automáticamente (nunca hacia atrás)
  if (maxNum > 0) await env.DB.prepare(`UPDATE contadores SET valor=? WHERE nombre='transportes' AND valor<?`).bind(maxNum, maxNum).run();
  return j({ ok: true, importados: n, contadorMinimo: maxNum || null });
}

// POST {accion:'setcounter', key, valor}
async function traSetCounter(env, body) {
  if (String(body.key || '') !== SETUP_KEY) return j({ ok: false, error: 'Clave incorrecta' }, 403);
  const v = parseInt(body.valor, 10);
  if (!v || v < 1) return j({ ok: false, error: 'valor inválido' }, 400);
  await env.DB.prepare(`INSERT INTO contadores (nombre,valor) VALUES ('transportes',?) ON CONFLICT(nombre) DO UPDATE SET valor=excluded.valor`).bind(v).run();
  return j({ ok: true, contador: 'transportes', valor: v, proximo: 'STM-' + (v + 1) });
}

// Despachador de /transportes (usa login y usuarios del NÚCLEO: un solo PIN)
async function traHandle(env, body) {
  const a = String((body && (body.accion || body.action)) || '');
  switch (a) {
    case 'login':              return await login(env, body);
    case 'usuariosListar':     return await bodUsuariosListar(env, body);
    case 'usuariosGuardar':    return await bodUsuariosGuardar(env, body);
    case 'usuariosEliminar':   return await bodUsuariosEliminar(env, body);
    case 'generarPines':       return await bodGenerarPines(env, body);
    case 'dashboard':          return await traDashboard(env, body);
    // v63 — en estricta, TODO lo que lee o escribe viajes exige PIN válido
    case 'crearViaje': case 'listarViajes': case 'actualizarViaje':
    case 'verificarConflicto': case 'subirDocumento': {
      if (segModo(env) === 'estricta' && !await segPinValido(env, body.pin))
        return j({ ok: false, error: 'Transportes exige PIN (modo estricto)' }, 403);
      if (a === 'crearViaje')         return await traCrearViaje(env, body);
      if (a === 'listarViajes')       return await traListarViajes(env);
      if (a === 'actualizarViaje')    return await traActualizarViaje(env, body);
      if (a === 'verificarConflicto') return await traVerificarConflicto(env, body);
      return await traSubirDocumento(env, body);
    }
    // v25 · App de choferes (todas con PIN de servidor)
    case 'obtenerViaje':       return await traObtenerViaje(env, body);
    case 'adjuntosViaje':      return await traAdjuntosViaje(env, body);
    case 'eliminarAdjunto':    return await traEliminarAdjunto(env, body);
    case 'tomarViaje':         return await traTomarViaje(env, body);
    case 'actualizarEstado':   return await traActualizarEstado(env, body);
    case 'subirFoto':          return await traSubirFoto(env, body);
    case 'subirFirma':         return await traSubirFirma(env, body);
    case 'subirDocFirmado':    return await traSubirDocFirmado(env, body);
    case 'importar':           return await traImportar(env, body);
    case 'setcounter':         return await traSetCounter(env, body);
    default: return j({ ok: false, error: 'Acción no reconocida (transportes): ' + a }, 400);
  }
}


// ============================================================
//  MÓDULO 🏭 FABRICACIÓN — Control de Producción Metal MARC (v65)
//  Piezas, estructuras y ductos: avance por CANTIDAD en etapas
//  reales de taller + control de calidad + despacho.
//  Una fabricación nace: (a) sola, desde la app; (b) automática,
//  cuando el CRM gana una cotización de METALMARC; (c) importada
//  desde los proyectos METALMARC que ya viven en proyectos_data.
// ============================================================
const FAB_ETAPAS_DEF = [
  ['corte',     'Corte / Plasma-Láser', 1, 0],
  ['armado',    'Armado',               2, 0],
  ['soldadura', 'Soldadura',            3, 0],
  ['pintura',   'Pintura / Acabado',    4, 0],
  ['qc',        'Control de Calidad',   5, 1],
  ['despacho',  'Despacho',             6, 0],
];

async function fabEnsure(env) {
  if (_yaListo.fabEnsure) return; _yaListo.fabEnsure = true;   // v120 ⚡ una vez por instancia
  await env.DB.batch([
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS fab_fabricaciones (
      id INTEGER PRIMARY KEY AUTOINCREMENT, codigo TEXT UNIQUE, project_id TEXT,
      cc_codigo TEXT, nombre TEXT NOT NULL, cliente TEXT, empresa TEXT DEFAULT 'METALMARC',
      tipo TEXT DEFAULT 'ductos', estado TEXT DEFAULT 'activo', notas TEXT,
      origen TEXT, creado_por TEXT, creado_en TEXT, actualizado_en TEXT,
      trashed INTEGER DEFAULT 0)`),
    env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_fab_proj ON fab_fabricaciones(project_id)`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS fab_items (
      id INTEGER PRIMARY KEY AUTOINCREMENT, fab_id INTEGER NOT NULL,
      descripcion TEXT NOT NULL, tipo TEXT DEFAULT 'pieza', cantidad REAL NOT NULL DEFAULT 1,
      unidad TEXT DEFAULT 'und', notas TEXT, orden INTEGER DEFAULT 99,
      activo INTEGER DEFAULT 1, creado_en TEXT)`),
    env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_fabitem_fab ON fab_items(fab_id)`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS fab_movs (
      id INTEGER PRIMARY KEY AUTOINCREMENT, fab_id INTEGER NOT NULL, item_id INTEGER NOT NULL,
      etapa TEXT NOT NULL, cantidad REAL NOT NULL, resultado TEXT DEFAULT 'ok',
      nota TEXT, usuario TEXT, fecha TEXT, creado_en TEXT)`),
    env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_fabmov_fab ON fab_movs(fab_id)`),
    env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_fabmov_item ON fab_movs(item_id, etapa)`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS fab_etapas (
      clave TEXT PRIMARY KEY, nombre TEXT NOT NULL, orden INTEGER DEFAULT 99,
      qc INTEGER DEFAULT 0, activo INTEGER DEFAULT 1)`),
    env.DB.prepare(`INSERT OR IGNORE INTO contadores (nombre,valor) VALUES ('fabricaciones', 1000)`),
  ]);
  for (const e of FAB_ETAPAS_DEF) {
    await env.DB.prepare(`INSERT OR IGNORE INTO fab_etapas (clave,nombre,orden,qc,activo) VALUES (?,?,?,?,1)`)
      .bind(e[0], e[1], e[2], e[3]).run();
  }
  // v66 — etapas omitidas por fabricación (JSON array de claves)
  try { await env.DB.prepare(`ALTER TABLE fab_fabricaciones ADD COLUMN etapas_omitidas TEXT`).run(); } catch (e) {}
  // v69 — acceso por app: bloqueo SOLO en Producción (no toca usuarios del núcleo)
  try { await env.DB.prepare(`CREATE TABLE IF NOT EXISTS fab_acceso (
    pin TEXT PRIMARY KEY, bloqueado INTEGER DEFAULT 1, por TEXT, actualizado_en TEXT)`).run(); } catch (e) {}
  // v74 — peso de cada etapa sobre el % global (despacho pesa poco: 5)
  try { await env.DB.prepare(`ALTER TABLE fab_etapas ADD COLUMN peso REAL DEFAULT 0`).run(); } catch (e) {}
  const PESOS_DEF = { corte: 20, armado: 25, soldadura: 25, pintura: 15, qc: 10, despacho: 5 };
  for (const k in PESOS_DEF) {
    try { await env.DB.prepare(`UPDATE fab_etapas SET peso=? WHERE clave=? AND (peso IS NULL OR peso=0)`)
      .bind(PESOS_DEF[k], k).run(); } catch (e) {}
  }
  // v68 — rol OPERARIO de taller (idempotente; sin re-correr /setup)
  try { await env.DB.prepare(`INSERT OR IGNORE INTO roles (codigo,nombre,descripcion,activo)
    VALUES ('operario','Operario','Registra avance de fabricación en taller; sin ventas ni facturación',1)`).run(); } catch (e) {}
  try { await env.DB.prepare(`INSERT OR IGNORE INTO permisos (rol,modulo,nivel) VALUES ('operario','taller','operar')`).run(); } catch (e) {}
  try { await env.DB.prepare(`INSERT OR IGNORE INTO permisos (rol,modulo,nivel) VALUES ('operario','proyectos','ver')`).run(); } catch (e) {}
  // v67 — informes de entrega (despacho al cliente)
  try { await env.DB.prepare(`CREATE TABLE IF NOT EXISTS fab_entregas (
    id INTEGER PRIMARY KEY AUTOINCREMENT, fab_id INTEGER NOT NULL, numero TEXT UNIQUE,
    fecha TEXT, recibe TEXT, entrega TEXT, nota TEXT, detalle TEXT,
    usuario TEXT, creado_en TEXT, anulada INTEGER DEFAULT 0)`).run(); } catch (e) {}
  try { await env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_fabent_fab ON fab_entregas(fab_id)`).run(); } catch (e) {}
  try { await env.DB.prepare(`ALTER TABLE fab_movs ADD COLUMN entrega_id INTEGER`).run(); } catch (e) {}
  try { await env.DB.prepare(`INSERT OR IGNORE INTO contadores (nombre,valor) VALUES ('fab_entregas', 100)`).run(); } catch (e) {}
}

// v66 — parsea las etapas que ESTA fabricación no usa
function fabOmitidas(f) {
  try { const a = JSON.parse((f && f.etapas_omitidas) || '[]'); return Array.isArray(a) ? a.map(String) : []; }
  catch (e) { return []; }
}

// Etapas activas ordenadas (catálogo vivo del taller)
async function fabEtapasActivas(env) {
  const r = await env.DB.prepare(`SELECT clave,nombre,orden,qc,peso FROM fab_etapas WHERE activo=1 ORDER BY orden`).all();
  return r.results || [];
}

// Progreso de UNA fabricación: total de piezas + hecho por etapa (solo 'ok')
async function fabProgreso(env, fabId, etapas) {
  const tot = await env.DB.prepare(`SELECT COALESCE(SUM(cantidad),0) AS t FROM fab_items WHERE fab_id=? AND activo=1`).bind(fabId).first();
  const total = Number(tot && tot.t) || 0;
  const movs = (await env.DB.prepare(
    `SELECT etapa, COALESCE(SUM(CASE WHEN resultado='rechazado' THEN 0 ELSE cantidad END),0) AS ok,
            COALESCE(SUM(CASE WHEN resultado='rechazado' THEN cantidad ELSE 0 END),0) AS rech
     FROM fab_movs WHERE fab_id=? GROUP BY etapa`).bind(fabId).all()).results || [];
  const porEtapa = {};
  for (const m of movs) porEtapa[m.etapa] = { ok: Number(m.ok) || 0, rechazado: Number(m.rech) || 0 };
  const ultima = etapas.length ? etapas[etapas.length - 1].clave : null;
  const hechoFinal = ultima && porEtapa[ultima] ? porEtapa[ultima].ok : 0;
  // v74 — % PONDERADO: cada etapa aporta su peso; omitidas redistribuyen solas
  let pct = 0;
  const sumaPesos = etapas.reduce((s, e) => s + (Number(e.peso) > 0 ? Number(e.peso) : 0), 0);
  if (total > 0 && sumaPesos > 0) {
    let acum = 0;
    for (const e of etapas) {
      const peso = Number(e.peso) > 0 ? Number(e.peso) : 0;
      if (!peso) continue;
      const ok = porEtapa[e.clave] ? porEtapa[e.clave].ok : 0;
      acum += Math.min(1, ok / total) * peso;
    }
    pct = Math.min(100, Math.round(acum / sumaPesos * 100));
  } else if (total > 0) {
    pct = Math.min(100, Math.round(hechoFinal / total * 100)); // sin pesos: compatibilidad
  }
  return { total, porEtapa, pct, hechoFinal, sumaPesos };
}

async function fabListar(env, body) {
  const etapas = await fabEtapasActivas(env);
  const where = ['trashed = 0'];
  const binds = [];
  if (body && body.estado) { where.push('estado = ?'); binds.push(String(body.estado)); }
  const res = await env.DB.prepare(
    `SELECT id,codigo,project_id,cc_codigo,nombre,cliente,empresa,tipo,estado,origen,etapas_omitidas,creado_en,actualizado_en
     FROM fab_fabricaciones WHERE ` + where.join(' AND ') + ` ORDER BY actualizado_en DESC`).bind(...binds).all();
  const fabricaciones = [];
  for (const f of (res.results || [])) {
    const om = fabOmitidas(f);
    const efectivas = etapas.filter(e => !om.includes(e.clave));
    const p = await fabProgreso(env, f.id, efectivas);
    fabricaciones.push(Object.assign({}, f, { progreso: p, etapas_omitidas: om }));
  }
  return j({ ok: true, fabricaciones, etapas, total: fabricaciones.length });
}

async function fabDetalle(env, body) {
  const id = Number(body.id) || 0;
  const f = await env.DB.prepare(`SELECT * FROM fab_fabricaciones WHERE id=? AND trashed=0`).bind(id).first();
  if (!f) return j({ ok: false, error: 'Fabricación no encontrada' }, 404);
  const etapas = await fabEtapasActivas(env);
  const items = (await env.DB.prepare(`SELECT * FROM fab_items WHERE fab_id=? AND activo=1 ORDER BY orden, id`).bind(id).all()).results || [];
  const movs = (await env.DB.prepare(`SELECT * FROM fab_movs WHERE fab_id=? ORDER BY id DESC LIMIT 300`).bind(id).all()).results || [];
  // Avance por pieza y etapa (solo ok; los rechazos se informan aparte)
  const porItem = {};
  const agg = (await env.DB.prepare(
    `SELECT item_id, etapa,
            COALESCE(SUM(CASE WHEN resultado='rechazado' THEN 0 ELSE cantidad END),0) AS ok,
            COALESCE(SUM(CASE WHEN resultado='rechazado' THEN cantidad ELSE 0 END),0) AS rech
     FROM fab_movs WHERE fab_id=? GROUP BY item_id, etapa`).bind(id).all()).results || [];
  for (const a of agg) {
    if (!porItem[a.item_id]) porItem[a.item_id] = {};
    porItem[a.item_id][a.etapa] = { ok: Number(a.ok) || 0, rechazado: Number(a.rech) || 0 };
  }
  const om = fabOmitidas(f);
  const efectivas = etapas.filter(e => !om.includes(e.clave));
  const progreso = await fabProgreso(env, id, efectivas);
  return j({ ok: true, fabricacion: f, etapas, etapas_omitidas: om, items, avance: porItem, movs, progreso });
}

async function fabCrear(env, body) {
  const nombre = String(body.nombre || '').trim();
  if (!nombre) return j({ ok: false, error: 'Falta el nombre de la fabricación' });
  const t = crParts();
  const codigo = await siguienteNumero(env, 'fabricaciones', 'FAB-');
  await env.DB.prepare(`INSERT INTO fab_fabricaciones
    (codigo,project_id,cc_codigo,nombre,cliente,empresa,tipo,estado,notas,origen,creado_por,creado_en,actualizado_en)
    VALUES (?,?,?,?,?,?,?, 'activo', ?, ?, ?, ?, ?)`)
    .bind(codigo, body.project_id || null, body.cc_codigo || null, nombre, body.cliente || '',
          body.empresa || 'METALMARC', body.tipo || 'ductos', body.notas || '',
          body.origen || 'manual', body.usuario || '', t.iso, t.iso).run();
  const f = await env.DB.prepare(`SELECT * FROM fab_fabricaciones WHERE codigo=?`).bind(codigo).first();
  return j({ ok: true, fabricacion: f });
}

async function fabEditar(env, body) {
  const id = Number(body.id) || 0;
  const f = await env.DB.prepare(`SELECT id FROM fab_fabricaciones WHERE id=? AND trashed=0`).bind(id).first();
  if (!f) return j({ ok: false, error: 'Fabricación no encontrada' }, 404);
  const t = crParts();
  const campos = ['nombre', 'cliente', 'tipo', 'estado', 'notas', 'cc_codigo', 'project_id'];
  const sets = []; const binds = [];
  for (const c of campos) if (body[c] !== undefined) { sets.push(c + ' = ?'); binds.push(body[c] === null ? null : String(body[c])); }
  // v66 — etapas que esta fabricación NO usa (siempre se guarda como JSON limpio)
  if (body.etapas_omitidas !== undefined) {
    let om = body.etapas_omitidas;
    if (typeof om === 'string') { try { om = JSON.parse(om); } catch (e) { om = []; } }
    if (!Array.isArray(om)) om = [];
    sets.push('etapas_omitidas = ?'); binds.push(JSON.stringify(om.map(String)));
  }
  if (!sets.length) return j({ ok: false, error: 'Nada que actualizar' });
  sets.push('actualizado_en = ?'); binds.push(t.iso); binds.push(id);
  await env.DB.prepare(`UPDATE fab_fabricaciones SET ` + sets.join(', ') + ` WHERE id = ?`).bind(...binds).run();
  return j({ ok: true });
}

async function fabBorrar(env, body) {
  const id = Number(body.id) || 0;
  await env.DB.prepare(`UPDATE fab_fabricaciones SET trashed=1, actualizado_en=? WHERE id=?`).bind(crParts().iso, id).run();
  return j({ ok: true });
}

async function fabItemGuardar(env, body) {
  const fabId = Number(body.fab_id) || 0;
  const f = await env.DB.prepare(`SELECT id FROM fab_fabricaciones WHERE id=? AND trashed=0`).bind(fabId).first();
  if (!f) return j({ ok: false, error: 'Fabricación no encontrada' }, 404);
  const desc = String(body.descripcion || '').trim();
  if (!desc) return j({ ok: false, error: 'Falta la descripción de la pieza' });
  const cant = Number(body.cantidad);
  if (!(cant > 0)) return j({ ok: false, error: 'La cantidad debe ser mayor a cero' });
  const t = crParts();
  if (body.id) {
    await env.DB.prepare(`UPDATE fab_items SET descripcion=?, tipo=?, cantidad=?, unidad=?, notas=?, orden=? WHERE id=? AND fab_id=?`)
      .bind(desc, body.tipo || 'pieza', cant, body.unidad || 'und', body.notas || '',
            Number(body.orden) || 99, Number(body.id), fabId).run();
  } else {
    await env.DB.prepare(`INSERT INTO fab_items (fab_id,descripcion,tipo,cantidad,unidad,notas,orden,creado_en)
      VALUES (?,?,?,?,?,?,?,?)`)
      .bind(fabId, desc, body.tipo || 'pieza', cant, body.unidad || 'und', body.notas || '',
            Number(body.orden) || 99, t.iso).run();
  }
  await env.DB.prepare(`UPDATE fab_fabricaciones SET actualizado_en=? WHERE id=?`).bind(t.iso, fabId).run();
  return j({ ok: true });
}

async function fabItemBorrar(env, body) {
  const id = Number(body.id) || 0;
  await env.DB.prepare(`UPDATE fab_items SET activo=0 WHERE id=?`).bind(id).run();
  return j({ ok: true });
}

// ── Corazón del módulo: registrar avance por CANTIDAD en una etapa ──
async function fabAvance(env, body) {
  const fabId = Number(body.fab_id) || 0;
  const itemId = Number(body.item_id) || 0;
  const etapa = String(body.etapa || '').trim();
  const cant = Number(body.cantidad);
  if (!(cant > 0)) return j({ ok: false, error: 'La cantidad debe ser mayor a cero' });
  const it = await env.DB.prepare(`SELECT id,cantidad,descripcion FROM fab_items WHERE id=? AND fab_id=? AND activo=1`).bind(itemId, fabId).first();
  if (!it) return j({ ok: false, error: 'Pieza no encontrada en esta fabricación' }, 404);
  const et = await env.DB.prepare(`SELECT clave,nombre,qc FROM fab_etapas WHERE clave=? AND activo=1`).bind(etapa).first();
  if (!et) return j({ ok: false, error: 'Etapa no válida: ' + etapa }, 400);
  // v66 — etapa marcada como "No se usa" en esta fabricación
  const fOm = await env.DB.prepare(`SELECT etapas_omitidas FROM fab_fabricaciones WHERE id=? AND trashed=0`).bind(fabId).first();
  if (fOm && fabOmitidas(fOm).includes(etapa)) {
    return j({ ok: false, error: 'La etapa "' + et.nombre + '" está marcada como NO SE USA en esta fabricación' }, 400);
  }
  let resultado = 'ok';
  if (et.qc === 1 && String(body.resultado || '') === 'rechazado') resultado = 'rechazado';
  // Guardia: el acumulado OK de la etapa no puede pasarse del total de la pieza
  if (resultado === 'ok') {
    const acc = await env.DB.prepare(
      `SELECT COALESCE(SUM(CASE WHEN resultado='rechazado' THEN 0 ELSE cantidad END),0) AS ok
       FROM fab_movs WHERE item_id=? AND etapa=?`).bind(itemId, etapa).first();
    const yaOk = Number(acc && acc.ok) || 0;
    if (yaOk + cant > Number(it.cantidad) + 1e-9) {
      return j({ ok: false, error: 'Se pasaría del total: ' + it.descripcion + ' lleva ' + yaOk +
        ' de ' + it.cantidad + ' en esta etapa (intentaste sumar ' + cant + ')' }, 400);
    }
  }
  const t = crParts();
  await env.DB.prepare(`INSERT INTO fab_movs (fab_id,item_id,etapa,cantidad,resultado,nota,usuario,fecha,creado_en)
    VALUES (?,?,?,?,?,?,?,?,?)`)
    .bind(fabId, itemId, etapa, cant, resultado, body.nota || '', body.usuario || '', t.iso, t.iso).run();
  await env.DB.prepare(`UPDATE fab_fabricaciones SET actualizado_en=? WHERE id=?`).bind(t.iso, fabId).run();
  // v67 — regla de oro: si llega a DESPACHO, se crea su informe de entrega
  let entrega = null;
  if (etapa === 'despacho' && resultado === 'ok') {
    try {
      const movId = (await env.DB.prepare(`SELECT last_insert_rowid() AS id`).first()).id;
      const accD = await env.DB.prepare(
        `SELECT COALESCE(SUM(CASE WHEN resultado='rechazado' THEN 0 ELSE cantidad END),0) AS ok
         FROM fab_movs WHERE item_id=? AND etapa='despacho'`).bind(itemId).first();
      entrega = await fabEntregaRegistrar(env, fabId, {
        recibe: body.recibe || '', nota: body.nota || '', usuario: body.usuario || '', fecha: body.fecha || null,
        lineas: [{ item_id: itemId, cantidad: cant, descripcion: it.descripcion,
                   unidad: (await env.DB.prepare(`SELECT unidad FROM fab_items WHERE id=?`).bind(itemId).first() || {}).unidad || 'und',
                   total: Number(it.cantidad),
                   pendiente: Math.max(0, Number(it.cantidad) - (Number(accD && accD.ok) || 0)) }],
      });
      await env.DB.prepare(`UPDATE fab_movs SET entrega_id=? WHERE id=?`).bind(entrega.id, movId).run();
    } catch (e) {}
  }
  return j({ ok: true, resultado, entrega });
}

async function fabMovBorrar(env, body) {
  const id = Number(body.id) || 0;
  const m = await env.DB.prepare(`SELECT fab_id, entrega_id FROM fab_movs WHERE id=?`).bind(id).first();
  if (!m) return j({ ok: false, error: 'Registro no encontrado' }, 404);
  // v67 — si el avance pertenece a un informe de entrega, se anula el informe
  // COMPLETO (con todos sus avances) para que nunca queden informes huérfanos.
  if (m.entrega_id) {
    await env.DB.prepare(`DELETE FROM fab_movs WHERE entrega_id=?`).bind(m.entrega_id).run();
    await env.DB.prepare(`UPDATE fab_entregas SET anulada=1 WHERE id=?`).bind(m.entrega_id).run();
  }
  await env.DB.prepare(`DELETE FROM fab_movs WHERE id=?`).bind(id).run();
  await env.DB.prepare(`UPDATE fab_fabricaciones SET actualizado_en=? WHERE id=?`).bind(crParts().iso, m.fab_id).run();
  return j({ ok: true });
}

async function fabEtapasListar(env) {
  const r = await env.DB.prepare(`SELECT clave,nombre,orden,qc,activo,peso FROM fab_etapas ORDER BY orden`).all();
  return j({ ok: true, etapas: r.results || [] });
}

async function fabEtapaGuardar(env, body) {
  const clave = String(body.clave || '').trim().toLowerCase().replace(/[^a-z0-9_]/g, '');
  const nombre = String(body.nombre || '').trim();
  if (!clave || !nombre) return j({ ok: false, error: 'Falta clave o nombre de la etapa' });
  await env.DB.prepare(`INSERT INTO fab_etapas (clave,nombre,orden,qc,activo,peso) VALUES (?,?,?,?,?,?)
    ON CONFLICT(clave) DO UPDATE SET nombre=excluded.nombre, orden=excluded.orden,
    qc=excluded.qc, activo=excluded.activo, peso=excluded.peso`)
    .bind(clave, nombre, Number(body.orden) || 99, body.qc ? 1 : 0,
          body.activo === 0 || body.activo === false ? 0 : 1,
          Number(body.peso) >= 0 ? Number(body.peso) : 0).run();
  return j({ ok: true });
}

// Crea (si no existe) la fabricación ligada a un proyecto — IDEMPOTENTE por project_id
async function fabDesdeProyecto(env, info) {
  if (info.project_id) {
    const ex = await env.DB.prepare(`SELECT id,codigo FROM fab_fabricaciones WHERE project_id=? AND trashed=0`)
      .bind(String(info.project_id)).first();
    if (ex) return { creada: false, id: ex.id, codigo: ex.codigo };
  }
  const t = crParts();
  const codigo = await siguienteNumero(env, 'fabricaciones', 'FAB-');
  await env.DB.prepare(`INSERT INTO fab_fabricaciones
    (codigo,project_id,cc_codigo,nombre,cliente,empresa,tipo,estado,origen,creado_por,creado_en,actualizado_en)
    VALUES (?,?,?,?,?, 'METALMARC', ?, 'activo', ?, ?, ?, ?)`)
    .bind(codigo, info.project_id || null, info.cc_codigo || null, String(info.nombre || 'Sin nombre'),
          info.cliente || '', info.tipo || 'ductos', info.origen || 'auto', info.usuario || 'orquesta', t.iso, t.iso).run();
  const f = await env.DB.prepare(`SELECT id FROM fab_fabricaciones WHERE codigo=?`).bind(codigo).first();
  return { creada: true, id: f.id, codigo };
}

// Importador de un solo toque: proyectos METALMARC del CRM → fabricaciones (idempotente)
async function fabImportarCRM(env, body) {
  const rows = (await env.DB.prepare(
    `SELECT project_id, project_name, client, payload FROM proyectos_data
     WHERE trashed=0 AND UPPER(REPLACE(COALESCE(empresa,''),' ','')) = 'METALMARC'`).all()).results || [];
  let creadas = 0, existentes = 0;
  const detalle = [];
  for (const r of rows) {
    let cc = null;
    try {
      const p = JSON.parse(r.payload || '{}');
      const cf = (p.project && p.project.customFields) || [];
      const hit = cf.find(c => /centro de costos/i.test(c.label || ''));
      if (hit && hit.value) cc = String(hit.value);
    } catch (e) {}
    if (!cc && /^CRM-/.test(r.project_id || '')) cc = r.project_id.slice(4);
    const res = await fabDesdeProyecto(env, { project_id: r.project_id, nombre: r.project_name,
      cliente: r.client || '', cc_codigo: cc, origen: 'importado:crm', usuario: (body && body.usuario) || 'importador' });
    if (res.creada) creadas++; else existentes++;
    detalle.push({ project_id: r.project_id, codigo: res.codigo, creada: res.creada });
  }
  return j({ ok: true, mensaje: '🏭 Importación lista', creadas, existentes, total: rows.length, detalle });
}

// ── v67 · INFORMES DE ENTREGA (despacho al cliente) ─────────
// Inserta la fila del informe con consecutivo atómico ENT-XXX.
async function fabEntregaRegistrar(env, fabId, info) {
  const t = crParts();
  const numero = await siguienteNumero(env, 'fab_entregas', 'ENT-');
  await env.DB.prepare(`INSERT INTO fab_entregas (fab_id,numero,fecha,recibe,entrega,nota,detalle,usuario,creado_en)
    VALUES (?,?,?,?,?,?,?,?,?)`)
    .bind(fabId, numero, info.fecha || t.iso, info.recibe || '', info.entrega || info.usuario || '',
          info.nota || '', JSON.stringify(info.lineas || []), info.usuario || '', t.iso).run();
  const e = await env.DB.prepare(`SELECT id FROM fab_entregas WHERE numero=?`).bind(numero).first();
  return { id: e.id, numero };
}

// Entrega COMPLETA (varias piezas de un solo golpe) + avances de despacho ligados
async function fabEntregaCrear(env, body) {
  const fabId = Number(body.fab_id) || 0;
  const f = await env.DB.prepare(`SELECT id,etapas_omitidas FROM fab_fabricaciones WHERE id=? AND trashed=0`).bind(fabId).first();
  if (!f) return j({ ok: false, error: 'Fabricación no encontrada' }, 404);
  if (fabOmitidas(f).includes('despacho'))
    return j({ ok: false, error: 'La etapa Despacho está marcada como NO SE USA en esta fabricación' }, 400);
  const lineas = Array.isArray(body.items) ? body.items : [];
  const limpias = [];
  for (const l of lineas) {
    const itemId = Number(l.item_id) || 0;
    const cant = Number(l.cantidad);
    if (!(cant > 0)) continue;
    const it = await env.DB.prepare(`SELECT id,descripcion,unidad,cantidad FROM fab_items WHERE id=? AND fab_id=? AND activo=1`)
      .bind(itemId, fabId).first();
    if (!it) return j({ ok: false, error: 'Pieza no encontrada (#' + itemId + ')' }, 404);
    const acc = await env.DB.prepare(
      `SELECT COALESCE(SUM(CASE WHEN resultado='rechazado' THEN 0 ELSE cantidad END),0) AS ok
       FROM fab_movs WHERE item_id=? AND etapa='despacho'`).bind(itemId).first();
    const yaOk = Number(acc && acc.ok) || 0;
    if (yaOk + cant > Number(it.cantidad) + 1e-9) {
      return j({ ok: false, error: 'Se pasaría del total en despacho: ' + it.descripcion +
        ' lleva ' + yaOk + ' de ' + it.cantidad + ' (intentaste ' + cant + ')' }, 400);
    }
    limpias.push({ item_id: itemId, cantidad: cant, descripcion: it.descripcion, unidad: it.unidad || 'und',
      total: Number(it.cantidad), pendiente: Math.max(0, Number(it.cantidad) - yaOk - cant) });
  }
  if (!limpias.length) return j({ ok: false, error: 'Indicá al menos una pieza con cantidad mayor a cero' });
  const t = crParts();
  const ent = await fabEntregaRegistrar(env, fabId, {
    recibe: body.recibe || '', entrega: body.entrega || body.usuario || '', nota: body.nota || '',
    usuario: body.usuario || '', fecha: body.fecha || null, lineas: limpias });
  for (const l of limpias) {
    await env.DB.prepare(`INSERT INTO fab_movs (fab_id,item_id,etapa,cantidad,resultado,nota,usuario,fecha,creado_en,entrega_id)
      VALUES (?,?, 'despacho', ?, 'ok', ?, ?, ?, ?, ?)`)
      .bind(fabId, l.item_id, l.cantidad, 'Entrega ' + ent.numero, body.usuario || '', t.iso, t.iso, ent.id).run();
  }
  await env.DB.prepare(`UPDATE fab_fabricaciones SET actualizado_en=? WHERE id=?`).bind(t.iso, fabId).run();
  const fila = await env.DB.prepare(`SELECT * FROM fab_entregas WHERE id=?`).bind(ent.id).first();
  return j({ ok: true, entrega: fila });
}

async function fabEntregasListar(env, body) {
  const fabId = Number(body.fab_id) || 0;
  const res = await env.DB.prepare(`SELECT * FROM fab_entregas WHERE fab_id=? AND anulada=0 ORDER BY id DESC`).bind(fabId).all();
  return j({ ok: true, entregas: res.results || [] });
}

// Anula el informe Y deshace los avances de despacho que generó
async function fabEntregaAnular(env, body) {
  const id = Number(body.id) || 0;
  const e = await env.DB.prepare(`SELECT id,fab_id,anulada FROM fab_entregas WHERE id=?`).bind(id).first();
  if (!e) return j({ ok: false, error: 'Entrega no encontrada' }, 404);
  if (e.anulada) return j({ ok: false, error: 'Esta entrega ya está anulada' });
  await env.DB.prepare(`DELETE FROM fab_movs WHERE entrega_id=?`).bind(id).run();
  await env.DB.prepare(`UPDATE fab_entregas SET anulada=1 WHERE id=?`).bind(id).run();
  await env.DB.prepare(`UPDATE fab_fabricaciones SET actualizado_en=? WHERE id=?`).bind(crParts().iso, e.fab_id).run();
  return j({ ok: true });
}

// ── v69 · ACCESO POR APP (Producción) ───────────────────────
// ¿Este PIN está bloqueado SOLO para esta app?
async function fabBloqueado(env, pin) {
  try {
    const r = await env.DB.prepare(`SELECT bloqueado FROM fab_acceso WHERE pin=?`).bind(String(pin)).first();
    return !!(r && r.bloqueado === 1);
  } catch (e) { return false; }
}

async function fabAccesoListar(env, body) {
  if (!(await bodAuth(env, body.adminPin, ['dueno', 'admin']))) return j({ ok: false, error: 'PIN sin permiso' }, 403);
  const res = await env.DB.prepare(`SELECT pin, bloqueado, por, actualizado_en FROM fab_acceso WHERE bloqueado=1`).all();
  return j({ ok: true, bloqueados: (res.results || []).map(r2 => r2.pin) });
}

async function fabAccesoSet(env, body) {
  if (!(await bodAuth(env, body.adminPin, ['dueno', 'admin']))) return j({ ok: false, error: 'PIN sin permiso' }, 403);
  const pin = String(body.pin || '').trim();
  if (!pin) return j({ ok: false, error: 'Falta el PIN' });
  const u = await env.DB.prepare(`SELECT rol FROM usuarios WHERE pin=?`).bind(pin).first();
  if (u && u.rol === 'dueno') return j({ ok: false, error: 'El dueño no se puede bloquear' }, 400);
  const t = crParts();
  const bloq = body.bloqueado ? 1 : 0;
  await env.DB.prepare(`INSERT INTO fab_acceso (pin,bloqueado,por,actualizado_en) VALUES (?,?,?,?)
    ON CONFLICT(pin) DO UPDATE SET bloqueado=excluded.bloqueado, por=excluded.por, actualizado_en=excluded.actualizado_en`)
    .bind(pin, bloq, String(body.usuario || body.adminPin || ''), t.iso).run();
  return j({ ok: true, pin, bloqueado: bloq });
}

// Para el login de la app: ¿puede entrar este PIN a Producción?
async function fabAccesoCheck(env, body) {
  const pin = String(body.pin || '').trim();
  if (!pin) return j({ ok: false, error: 'Falta el PIN' });
  const bloqueado = await fabBloqueado(env, pin);
  return j({ ok: true, permitido: !bloqueado });
}

// v69 — contrato del frontend FB6: ¿estoy bloqueado en ESTA app?
async function fabPuedo(env, body) {
  const pin = String(body.pin || '').trim();
  if (!pin) return j({ ok: false, error: 'Falta el PIN' });
  return j({ ok: true, bloqueado: await fabBloqueado(env, pin) });
}

// v69 — usuarios del núcleo (activos e inactivos) + su acceso a ESTA app
async function fabUsuarios(env, body) {
  if (!(await bodAuth(env, body.adminPin, ['dueno', 'admin']))) return j({ ok: false, error: 'PIN sin permiso' }, 403);
  const res = await env.DB.prepare(`
    SELECT u.pin, u.nombre, u.apellido, u.email, u.rol, u.activo,
           COALESCE(a.bloqueado, 0) AS bloqueado_app
    FROM usuarios u LEFT JOIN fab_acceso a ON a.pin = u.pin
    ORDER BY u.activo DESC, u.nombre`).all();
  const usuarios = (res.results || []).map(u => ({
    pin: u.pin, nombre: ((u.nombre || '') + (u.apellido ? ' ' + u.apellido : '')).trim(),
    email: u.email || '', rol: u.rol, activo: u.activo === 1 ? 1 : 0,
    bloqueado_app: u.bloqueado_app === 1 ? 1 : 0 }));
  return j({ ok: true, usuarios });
}

// v69 — catálogo de roles vivos (para el selector del panel)
async function fabRolesListar(env) {
  try {
    const res = await env.DB.prepare(`SELECT codigo, nombre, activo FROM roles WHERE activo=1 ORDER BY nombre`).all();
    return j({ ok: true, roles: res.results || [] });
  } catch (e) { return j({ ok: true, roles: [] }); }
}

// v70 — LISTA PERMITIDA MASIVA: bloquea en ESTA app a todo el padrón menos
// los PINes permitidos. Dueño/admin exentos; quien aplica no se autobloquea.
// El padrón del núcleo NO se toca (solo fab_acceso).
async function fabAccesoSolo(env, body) {
  if (!(await bodAuth(env, body.adminPin, ['dueno', 'admin']))) return j({ ok: false, error: 'PIN sin permiso' }, 403);
  const permitidos = new Set((Array.isArray(body.permitidos) ? body.permitidos : []).map(x => String(x).trim()));
  permitidos.add(String(body.adminPin || '').trim());
  const us = (await env.DB.prepare(`SELECT pin, rol FROM usuarios`).all()).results || [];
  const t = crParts().iso;
  const por = String(body.usuario || body.adminPin || '');
  let bloqueados = 0, abiertos = 0, exentos = 0;
  for (const u of us) {
    if (u.rol === 'dueno' || u.rol === 'admin') { exentos++; continue; }
    const bloq = permitidos.has(String(u.pin)) ? 0 : 1;
    await env.DB.prepare(`INSERT INTO fab_acceso (pin,bloqueado,por,actualizado_en) VALUES (?,?,?,?)
      ON CONFLICT(pin) DO UPDATE SET bloqueado=excluded.bloqueado, por=excluded.por, actualizado_en=excluded.actualizado_en`)
      .bind(String(u.pin), bloq, por, t).run();
    if (bloq) bloqueados++; else abiertos++;
  }
  return j({ ok: true, mensaje: '🔒 Lista aplicada', bloqueados, permitidos: abiertos, exentos });
}

// v72 — 🗑 PURGA DEFINITIVA: borra la fila del usuario y libera su PIN.
// SOLO el dueño. Nunca contra dueño/admin ni contra uno mismo.
async function fabUsuarioPurgar(env, body) {
  if (!(await bodAuth(env, body.adminPin, ['dueno']))) return j({ ok: false, error: 'Solo el dueño puede purgar usuarios' }, 403);
  const pin = String(body.pin || '').trim();
  if (!pin) return j({ ok: false, error: 'Falta el PIN' }, 400);
  if (pin === String(body.adminPin || '').trim()) return j({ ok: false, error: 'No podés purgarte a vos mismo' }, 400);
  const u = await env.DB.prepare(`SELECT pin, nombre, apellido, rol FROM usuarios WHERE pin=?`).bind(pin).first();
  if (!u) return j({ ok: false, error: 'No existe un usuario con ese PIN' }, 404);
  if (u.rol === 'dueno' || u.rol === 'admin') return j({ ok: false, error: 'El dueño y los administradores no se purgan' }, 400);
  await env.DB.prepare(`DELETE FROM usuarios WHERE pin=?`).bind(pin).run();
  await env.DB.prepare(`DELETE FROM fab_acceso WHERE pin=?`).bind(pin).run();
  const nombre = ((u.nombre || '') + (u.apellido ? ' ' + u.apellido : '')).trim();
  return j({ ok: true, mensaje: '🗑 ' + nombre + ' purgado — el PIN ' + pin + ' quedó libre', pin });
}

// ── v73 · IMPORTACIÓN MASIVA DE PIEZAS ──────────────────────
// N piezas de un solo golpe (Excel, foto o cotización) — validadas
async function fabItemsBulk(env, body) {
  const fabId = Number(body.fab_id) || 0;
  const f = await env.DB.prepare(`SELECT id FROM fab_fabricaciones WHERE id=? AND trashed=0`).bind(fabId).first();
  if (!f) return j({ ok: false, error: 'Fabricación no encontrada' }, 404);
  const items = Array.isArray(body.items) ? body.items : [];
  const t = crParts();
  let creadas = 0; const errores = [];
  for (const it of items) {
    const desc = String(it.descripcion || '').trim();
    const cant = Number(it.cantidad);
    if (!desc) { errores.push('Fila sin descripción'); continue; }
    if (!(cant > 0)) { errores.push(desc + ': cantidad inválida'); continue; }
    await env.DB.prepare(`INSERT INTO fab_items (fab_id,descripcion,tipo,cantidad,unidad,notas,orden,creado_en)
      VALUES (?,?,?,?,?,?,?,?)`)
      .bind(fabId, desc, String(it.tipo || 'ducto'), cant, String(it.unidad || 'und'),
            String(it.notas || ''), Number(it.orden) || 99, t.iso).run();
    creadas++;
  }
  await env.DB.prepare(`UPDATE fab_fabricaciones SET actualizado_en=? WHERE id=?`).bind(t.iso, fabId).run();
  return j({ ok: true, creadas, errores, mensaje: '📥 ' + creadas + ' piezas importadas' + (errores.length ? ' · ' + errores.length + ' con error' : '') });
}

// Cotizaciones GANADAS de METALMARC por nombre/cliente/consecutivo + sus ofertas
async function fabCotBuscar(env, body) {
  const q = '%' + String(body.q || '').trim() + '%';
  if (q === '%%') return j({ ok: false, error: 'Escribí parte del nombre del proyecto' });
  const res = await env.DB.prepare(
    `SELECT consecutivo, cliente, proyecto, monto, cc_codigo, actualizado_en FROM crm_cotizaciones
     WHERE estatus='Aprobado' AND UPPER(REPLACE(COALESCE(empresa,''),' ','')) = 'METALMARC'
       AND (proyecto LIKE ? OR cliente LIKE ? OR consecutivo LIKE ?)
     ORDER BY actualizado_en DESC LIMIT 10`).bind(q, q, q).all();
  const cots = [];
  for (const c of (res.results || [])) {
    const of = (await env.DB.prepare(
      `SELECT id, nombre, version, creado_en FROM crm_ofertas WHERE consecutivo=? ORDER BY version DESC LIMIT 10`)
      .bind(c.consecutivo).all()).results || [];
    cots.push(Object.assign({}, c, { ofertas: of }));
  }
  return j({ ok: true, cotizaciones: cots });
}

// Proxy R2: baja el archivo de la oferta en base64 (el navegador no pelea con CORS)
async function fabOfertaBytes(env, body) {
  const id = Number(body.id) || 0;
  const o = await env.DB.prepare(`SELECT id, nombre, ruta FROM crm_ofertas WHERE id=?`).bind(id).first();
  if (!o) return j({ ok: false, error: 'Oferta no encontrada' }, 404);
  if (!env.ARCHIVOS) return j({ ok: false, error: 'R2 no disponible' }, 500);
  const obj = await env.ARCHIVOS.get(o.ruta);
  if (!obj) return j({ ok: false, error: 'El archivo no está en R2: ' + o.ruta }, 404);
  const buf = await obj.arrayBuffer();
  if (buf.byteLength > 8 * 1024 * 1024) return j({ ok: false, error: 'Archivo muy grande (>8MB)' }, 400);
  let bin = ''; const bytes = new Uint8Array(buf);
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
  return j({ ok: true, nombre: o.nombre, base64: btoa(bin) });
}

// Foto de una tabla de ductos → Claude visión → piezas propuestas
async function fabImportarFoto(env, body) {
  if (!env.ANTHROPIC_API_KEY) {
    return j({ ok: false, error: 'Falta configurar el secreto ANTHROPIC_API_KEY en el worker (Settings → Variables → Add secret). Sin eso la lectura de fotos no funciona; usá Excel o la cotización.' }, 400);
  }
  const img = String(body.imagen || '');
  if (!img) return j({ ok: false, error: 'Falta la imagen' }, 400);
  const media = String(body.media_type || 'image/jpeg');
  try {
    const resp = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01' },
      body: JSON.stringify({
        model: 'claude-sonnet-4-6', max_tokens: 2000,
        messages: [{ role: 'user', content: [
          { type: 'image', source: { type: 'base64', media_type: media, data: img } },
          { type: 'text', text: 'Esta imagen contiene una tabla de piezas/ductos de un taller de fabricación. Extraé cada fila como pieza. Respondé SOLO un JSON (sin backticks ni texto extra) con este formato: [{"descripcion":"...","cantidad":N,"unidad":"und|m|m2|kg|jgo"}]. La descripción debe incluir medidas si aparecen. Si un dato no está, usá cantidad 1 y unidad "und".' },
        ]}],
      }),
    });
    const data = await resp.json();
    if (!resp.ok) return j({ ok: false, error: 'IA: ' + ((data && data.error && data.error.message) || resp.status) }, 500);
    const texto = ((data.content || []).find(b => b.type === 'text') || {}).text || '[]';
    const limpio = texto.replace(/```json|```/g, '').trim();
    let items = [];
    try { items = JSON.parse(limpio); } catch (e) { return j({ ok: false, error: 'La IA no devolvió una tabla legible; probá con una foto más clara' }, 500); }
    if (!Array.isArray(items)) items = [];
    return j({ ok: true, items, total: items.length });
  } catch (e) {
    return j({ ok: false, error: 'No pude hablar con la IA: ' + e.message }, 500);
  }
}

// ============================================================
//  MÓDULO CRONOGRAMAS  (v148)
//  Programación de obra multiusuario. Reutiliza los PIN y el
//  sistema de permisos del núcleo: el módulo se llama
//  'cronogramas' y respeta los niveles ver / operar / aprobar /
//  admin, más asignación por obra.
//
//  Qué puede hacer cada nivel:
//    ver      → consultar el cronograma de sus obras
//    operar   → además, marcar avance y notas (NO mueve fechas)
//    aprobar  → además, mover fechas, crear y borrar actividades
//    admin    → además, crear obras, asignar gente y editar plantillas
// ============================================================
const CRON_NIVEL_FECHAS = 'aprobar';   // mover fechas exige este nivel
const CRON_TIPOS_SEMILLA = [
  { codigo: 'retrofit',   nombre: 'Retrofit HVAC',            empresa: 'MARCAIRE',    orden: 1 },
  { codigo: 'nueva',      nombre: 'Tienda nueva',             empresa: 'MARCAIRE',    orden: 2 },
  { codigo: 'cuartofrio', nombre: 'Cuarto frío',              empresa: 'MARCAIRE',    orden: 3 },
  { codigo: 'ductos',     nombre: 'Ductos y lámina',          empresa: 'METAL MARC',  orden: 4 },
  { codigo: 'mantto',     nombre: 'Mantenimiento preventivo', empresa: 'MARCAIRE',    orden: 5 },
];

async function cronEnsure(env) {
  if (_yaListo.cronEnsure) return; _yaListo.cronEnsure = true;   // v120 ⚡ una vez por instancia
  await env.DB.batch([
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS cron_obras (
      id TEXT PRIMARY KEY, nombre TEXT NOT NULL, cliente TEXT, tipo TEXT,
      empresa TEXT, razon_social TEXT, cc_codigo TEXT,
      estado TEXT DEFAULT 'activo', inicio TEXT, fin TEXT,
      responsable TEXT, notas TEXT, feriados INTEGER DEFAULT 1,
      creado_por TEXT, creado_en TEXT, actualizado_en TEXT)`),
    env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_cron_obras_emp ON cron_obras(empresa)`),
    env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_cron_obras_est ON cron_obras(estado)`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS cron_tareas (
      id TEXT PRIMARY KEY, obra_id TEXT NOT NULL, wbs TEXT, nombre TEXT NOT NULL,
      tipo TEXT DEFAULT 'eje', dur INTEGER DEFAULT 1, cal TEXT DEFAULT 'LV',
      anc TEXT, pred TEXT, avance INTEGER DEFAULT 0, oculta INTEGER DEFAULT 0,
      nota TEXT, orden INTEGER DEFAULT 0,
      ini_calc TEXT, fin_calc TEXT,
      actualizado_por TEXT, actualizado_en TEXT)`),
    env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_cron_tareas_obra ON cron_tareas(obra_id)`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS cron_asignados (
      obra_id TEXT NOT NULL, usuario_id TEXT NOT NULL, nivel TEXT DEFAULT 'ver',
      asignado_en TEXT, PRIMARY KEY (obra_id, usuario_id))`),
    env.DB.prepare(`CREATE INDEX IF NOT EXISTS idx_cron_asig_us ON cron_asignados(usuario_id)`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS cron_tipos (
      codigo TEXT PRIMARY KEY, nombre TEXT NOT NULL, empresa TEXT,
      plantilla TEXT, orden INTEGER DEFAULT 99, activo INTEGER DEFAULT 1)`),
    env.DB.prepare(`CREATE TABLE IF NOT EXISTS cron_borradas (
      id INTEGER PRIMARY KEY AUTOINCREMENT, obra_id TEXT, tarea_id TEXT,
      nombre TEXT, borrado_por TEXT, borrado_en TEXT)`),
  ]);
  // v152 — `grupo` divide una obra en secciones (las tiendas de un paquete).
  // ALTER suelto: si la columna ya está, el error se ignora.
  try { await env.DB.prepare('ALTER TABLE cron_tareas ADD COLUMN grupo TEXT').run(); } catch (e) {}
  // El índice va DESPUÉS del ALTER: en el lote de creación la columna todavía
  // no existe y todo el módulo se caía con "no such column: grupo".
  try { await env.DB.prepare('CREATE INDEX IF NOT EXISTS idx_cron_tareas_grupo ON cron_tareas(obra_id,grupo)').run(); } catch (e) {}
  for (const t of CRON_TIPOS_SEMILLA) {
    await env.DB.prepare('INSERT OR IGNORE INTO cron_tipos (codigo,nombre,empresa,plantilla,orden,activo) VALUES (?,?,?,?,?,1)')
      .bind(t.codigo, t.nombre, t.empresa, '[]', t.orden).run();
  }
  // v154 — registrar el módulo Cronogramas en la tabla `modulos` para que
  // aparezca en Roles y permisos (el módulo ya existía pero nunca se sembró).
  try {
    await env.DB.prepare(`INSERT INTO modulos (codigo,nombre,descripcion,icono,orden,activo)
      VALUES ('cronogramas','Cronogramas','Programación de obras y diagramas de Gantt','📅',72,1)
      ON CONFLICT(codigo) DO UPDATE SET nombre=excluded.nombre, descripcion=excluded.descripcion`).run();
  } catch (e) {}
}

// ── Nivel efectivo de una persona sobre UNA obra ──────────────
// Manda el mayor entre su nivel de módulo y el que le dieron en la obra.
async function cronNivel(env, pin, key, obraId) {
  if (key && segClaveOk(env, key)) return 'admin';
  if (await tienePermiso(env, pin, key, 'cronogramas', 'admin')) return 'admin';
  if (!pin) return 'sin';
  const u = await env.DB.prepare('SELECT id,rol FROM usuarios WHERE pin=? AND activo=1').bind(String(pin)).first();
  if (!u) return 'sin';
  let mejor = 'sin';
  for (const n of ['aprobar', 'operar', 'ver']) {
    if (await tienePermiso(env, pin, key, 'cronogramas', n)) { mejor = n; break; }
  }
  if (obraId) {
    const a = await env.DB.prepare('SELECT nivel FROM cron_asignados WHERE obra_id=? AND usuario_id=?')
      .bind(String(obraId), u.id).first();
    if (a && nivelOrd(a.nivel) > nivelOrd(mejor)) mejor = a.nivel;
  }
  return mejor;
}
async function cronUsuario(env, pin) {
  if (!pin) return null;
  return await env.DB.prepare('SELECT id,nombre,apellido,rol,email FROM usuarios WHERE pin=? AND activo=1')
    .bind(String(pin)).first();
}
function cronNombre(u) { return u ? ((u.nombre || '') + (u.apellido ? ' ' + u.apellido : '')).trim() : 'sistema'; }

// v150 — Deja rastro en la tabla `auditoria` del núcleo. Antes esto llamaba a
// una función audit() que NO existe: el módulo compilaba igual y reventaba en
// caliente al primer guardado. Se escribe directo contra la tabla para no
// depender de la firma de nadie más.
async function cronAudit(env, pin, accion, detalle) {
  try {
    const u = await cronUsuario(env, pin);
    await env.DB.prepare('INSERT INTO auditoria (ts,usuario,rol,modulo,accion,detalle) VALUES (?,?,?,?,?,?)')
      .bind(crParts().iso, cronNombre(u), (u && u.rol) || '', 'cronogramas',
        String(accion || ''), String(detalle || '')).run();
  } catch (e) { /* la auditoría nunca debe tumbar la operación */ }
}

// ── cron_info: lo que el frontend necesita al entrar ──────────
async function cronInfo(env, body) {
  await cronEnsure(env);
  const u = await cronUsuario(env, body.pin);
  if (!u && !segClaveOk(env, body.key)) return j({ ok: false, error: 'PIN no reconocido' }, 403);
  const nivel = await cronNivel(env, body.pin, body.key, null);
  if (nivel === 'sin') return j({ ok: false, error: 'No tenés acceso al módulo de cronogramas. Pedile al dueño que te lo habilite.' }, 403);
  const tipos = (await env.DB.prepare('SELECT codigo,nombre,empresa,orden FROM cron_tipos WHERE activo=1 ORDER BY orden,nombre').all()).results || [];
  return j({
    ok: true, usuario: u ? { id: u.id, nombre: cronNombre(u), rol: u.rol } : { id: 'setup', nombre: 'Administrador', rol: 'dueno' },
    nivel, esAdmin: nivel === 'admin',
    puedeFechas: nivelOrd(nivel) >= nivelOrd(CRON_NIVEL_FECHAS),
    puedeAvance: nivelOrd(nivel) >= nivelOrd('operar'),
    tipos, niveles: NIVELES,
  });
}

// ── cron_listar: obras visibles + resumen de avance ───────────
async function cronListar(env, body) {
  await cronEnsure(env);
  const nivel = await cronNivel(env, body.pin, body.key, null);
  if (nivel === 'sin') return j({ ok: false, error: 'Sin acceso a cronogramas' }, 403);
  const u = await cronUsuario(env, body.pin);
  const esAdmin = nivel === 'admin';

  let sql = `SELECT o.* FROM cron_obras o`;
  const bind = [];
  if (!esAdmin && u) {
    sql += ` WHERE (o.creado_por=? OR EXISTS (SELECT 1 FROM cron_asignados a WHERE a.obra_id=o.id AND a.usuario_id=?))`;
    bind.push(u.id, u.id);
  }
  if (body.empresa) { sql += (bind.length || esAdmin ? (esAdmin ? ' WHERE ' : ' AND ') : ' WHERE ') + 'o.empresa=?'; bind.push(String(body.empresa)); }
  sql += ' ORDER BY o.estado, o.inicio, o.nombre';
  const obras = (await env.DB.prepare(sql).bind(...bind).all()).results || [];

  for (const o of obras) {
    const r = await env.DB.prepare(
      `SELECT COUNT(*) n, SUM(CASE WHEN tipo<>'hito' THEN dur ELSE 0 END) pd,
              SUM(CASE WHEN tipo<>'hito' THEN dur*avance ELSE 0 END) pa,
              MIN(ini_calc) i, MAX(fin_calc) f
       FROM cron_tareas WHERE obra_id=?`).bind(o.id).first();
    o.tareas = (r && r.n) || 0;
    o.avance = (r && r.pd) ? Math.round(r.pa / r.pd) : 0;
    o.inicio_calc = r ? r.i : null;
    o.fin_calc = r ? r.f : null;
    const as = (await env.DB.prepare(
      `SELECT a.usuario_id, a.nivel, u.nombre, u.apellido FROM cron_asignados a
       LEFT JOIN usuarios u ON u.id=a.usuario_id WHERE a.obra_id=?`).bind(o.id).all()).results || [];
    o.asignados = as.map(x => ({ id: x.usuario_id, nivel: x.nivel, nombre: cronNombre(x) }));
  }
  return j({ ok: true, obras, nivel, esAdmin });
}

// ── cron_obraGuardar ─────────────────────────────────────────
async function cronObraGuardar(env, body) {
  await cronEnsure(env);
  const o = body.obra || {};
  const id = String(o.id || '').trim();
  const nivel = await cronNivel(env, body.pin, body.key, id || null);
  const esNueva = !id;
  if (esNueva && nivel !== 'admin') return j({ ok: false, error: 'Crear una obra exige nivel administrador en cronogramas' }, 403);
  if (!esNueva && nivelOrd(nivel) < nivelOrd(CRON_NIVEL_FECHAS)) return j({ ok: false, error: 'Editar la obra exige nivel aprobar' }, 403);
  const nombre = String(o.nombre || '').trim();
  if (!nombre) return j({ ok: false, error: 'La obra necesita un nombre' });
  const u = await cronUsuario(env, body.pin);
  const ahora = crParts().iso;
  // v149 — Date.now() solo NO alcanza: al crear obras en rueda (una migración,
  // un alta masiva) dos caen en el mismo milisegundo y revientan la llave
  // primaria. Se le agrega azar y se comprueba que el id esté libre.
  let nid = id;
  if (!nid) {
    for (let intento = 0; intento < 12; intento++) {
      const cand = 'OBR-' + Date.now().toString(36).toUpperCase() + '-' +
        Math.random().toString(36).slice(2, 6).toUpperCase();
      const choca = await env.DB.prepare('SELECT id FROM cron_obras WHERE id=?').bind(cand).first();
      if (!choca) { nid = cand; break; }
    }
    if (!nid) return j({ ok: false, error: 'No pude generar un identificador libre para la obra' }, 500);
  }

  if (esNueva) {
    await env.DB.prepare(`INSERT INTO cron_obras
      (id,nombre,cliente,tipo,empresa,razon_social,cc_codigo,estado,inicio,fin,responsable,notas,feriados,creado_por,creado_en,actualizado_en)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`)
      .bind(nid, nombre, o.cliente || null, o.tipo || null, o.empresa || null, o.razon_social || null,
        o.cc_codigo || null, o.estado || 'activo', o.inicio || null, o.fin || null,
        o.responsable || null, o.notas || null, o.feriados === 0 ? 0 : 1,
        u ? u.id : 'setup', ahora, ahora).run();
    // El creador queda asignado con nivel aprobar sobre su propia obra
    if (u) await env.DB.prepare('INSERT OR REPLACE INTO cron_asignados (obra_id,usuario_id,nivel,asignado_en) VALUES (?,?,?,?)')
      .bind(nid, u.id, 'aprobar', ahora).run();
    // Si el tipo trae plantilla, se siembran las actividades
    if (o.tipo) {
      const tp = await env.DB.prepare('SELECT plantilla FROM cron_tipos WHERE codigo=?').bind(String(o.tipo)).first();
      let pl = [];
      try { pl = JSON.parse((tp && tp.plantilla) || '[]'); } catch (e) { pl = []; }
      let k = 0;
      for (const t of (Array.isArray(pl) ? pl : [])) {
        k++;
        await env.DB.prepare(`INSERT INTO cron_tareas
          (id,obra_id,wbs,nombre,tipo,dur,cal,anc,pred,avance,oculta,nota,orden,actualizado_por,actualizado_en)
          VALUES (?,?,?,?,?,?,?,?,?,0,0,?,?,?,?)`)
          .bind(nid + '-T' + k, nid, t.wbs || String(k), String(t.nombre || 'Actividad ' + k),
            t.tipo || 'eje', Number(t.dur || 1), t.cal || 'LV', t.anc || null,
            JSON.stringify(t.pred || []), t.nota || null, k, u ? u.id : 'setup', ahora).run();
      }
    }
  } else {
    await env.DB.prepare(`UPDATE cron_obras SET nombre=?,cliente=?,tipo=?,empresa=?,razon_social=?,
      cc_codigo=?,estado=?,inicio=?,fin=?,responsable=?,notas=?,feriados=?,actualizado_en=? WHERE id=?`)
      .bind(nombre, o.cliente || null, o.tipo || null, o.empresa || null, o.razon_social || null,
        o.cc_codigo || null, o.estado || 'activo', o.inicio || null, o.fin || null,
        o.responsable || null, o.notas || null, o.feriados === 0 ? 0 : 1, ahora, id).run();
  }
  await cronAudit(env, body.pin, esNueva ? 'obra_crear' : 'obra_editar', nombre);
  return j({ ok: true, id: nid, creada: esNueva });
}

// ── cron_obraEliminar ────────────────────────────────────────
async function cronObraEliminar(env, body) {
  await cronEnsure(env);
  if (await cronNivel(env, body.pin, body.key, null) !== 'admin')
    return j({ ok: false, error: 'Eliminar una obra exige nivel administrador' }, 403);
  const id = String(body.id || '').trim();
  if (!id) return j({ ok: false, error: 'Falta el id de la obra' });
  const o = await env.DB.prepare('SELECT nombre FROM cron_obras WHERE id=?').bind(id).first();
  if (!o) return j({ ok: false, error: 'No encontré esa obra' });
  const u = await cronUsuario(env, body.pin);
  const ahora = crParts().iso;
  const ts = (await env.DB.prepare('SELECT id,nombre FROM cron_tareas WHERE obra_id=?').bind(id).all()).results || [];
  for (const t of ts) {
    await env.DB.prepare('INSERT INTO cron_borradas (obra_id,tarea_id,nombre,borrado_por,borrado_en) VALUES (?,?,?,?,?)')
      .bind(id, t.id, t.nombre, u ? u.id : 'setup', ahora).run();
  }
  await env.DB.batch([
    env.DB.prepare('DELETE FROM cron_tareas WHERE obra_id=?').bind(id),
    env.DB.prepare('DELETE FROM cron_asignados WHERE obra_id=?').bind(id),
    env.DB.prepare('DELETE FROM cron_obras WHERE id=?').bind(id),
  ]);
  await cronAudit(env, body.pin, 'obra_eliminar', o.nombre + ' (' + ts.length + ' actividades)');
  return j({ ok: true, borradas: ts.length });
}

// ── cron_tareas: el cronograma de una obra ───────────────────
async function cronTareas(env, body) {
  await cronEnsure(env);
  const id = String(body.obra_id || '').trim();
  if (!id) return j({ ok: false, error: 'Falta obra_id' });
  const nivel = await cronNivel(env, body.pin, body.key, id);
  if (nivel === 'sin') return j({ ok: false, error: 'No tenés acceso a esta obra' }, 403);
  const obra = await env.DB.prepare('SELECT * FROM cron_obras WHERE id=?').bind(id).first();
  if (!obra) return j({ ok: false, error: 'No encontré esa obra' });
  const rs = (await env.DB.prepare('SELECT * FROM cron_tareas WHERE obra_id=? ORDER BY orden,wbs').bind(id).all()).results || [];
  const tareas = rs.map(t => {
    let pred = [];
    try { pred = JSON.parse(t.pred || '[]'); } catch (e) { pred = []; }
    return { id: t.id, wbs: t.wbs, nom: t.nombre, tipo: t.tipo, dur: t.dur, cal: t.cal,
      anc: t.anc || null, pred: Array.isArray(pred) ? pred : [], av: t.avance || 0,
      oculta: !!t.oculta, nota: t.nota || null, orden: t.orden,
      grupo: t.grupo || null,                                // v152
      ini: t.ini_calc || null, fin: t.fin_calc || null };   // v151
  });
  return j({ ok: true, obra, tareas, nivel,
    puedeFechas: nivelOrd(nivel) >= nivelOrd(CRON_NIVEL_FECHAS),
    puedeAvance: nivelOrd(nivel) >= nivelOrd('operar') });
}

// ── cron_tareasGuardar: guardado en bloque ───────────────────
//  Borrado quirúrgico (regla de la v63): NADA se borra salvo lo
//  que venga declarado en borradoEn. Un flag genérico de "forzar"
//  ya nos costó datos una vez; acá no existe.
async function cronTareasGuardar(env, body) {
  await cronEnsure(env);
  const id = String(body.obra_id || '').trim();
  if (!id) return j({ ok: false, error: 'Falta obra_id' });
  const nivel = await cronNivel(env, body.pin, body.key, id);
  if (nivelOrd(nivel) < nivelOrd(CRON_NIVEL_FECHAS))
    return j({ ok: false, error: 'Cambiar el cronograma exige nivel aprobar. Con nivel operar podés marcar avance con cron_avance.' }, 403);
  const obra = await env.DB.prepare('SELECT id FROM cron_obras WHERE id=?').bind(id).first();
  if (!obra) return j({ ok: false, error: 'No encontré esa obra' });

  const tareas = Array.isArray(body.tareas) ? body.tareas : [];
  const borradoEn = Array.isArray(body.borradoEn) ? body.borradoEn.map(String) : [];
  const u = await cronUsuario(env, body.pin);
  const uid = u ? u.id : 'setup';
  const ahora = crParts().iso;

  let borradas = 0;
  for (const tid of borradoEn) {
    const t = await env.DB.prepare('SELECT nombre FROM cron_tareas WHERE id=? AND obra_id=?').bind(tid, id).first();
    if (!t) continue;
    await env.DB.prepare('INSERT INTO cron_borradas (obra_id,tarea_id,nombre,borrado_por,borrado_en) VALUES (?,?,?,?,?)')
      .bind(id, tid, t.nombre, uid, ahora).run();
    await env.DB.prepare('DELETE FROM cron_tareas WHERE id=? AND obra_id=?').bind(tid, id).run();
    borradas++;
  }

  let n = 0, k = 0;
  for (const t of tareas) {
    const tid = String(t.id || '').trim();
    if (!tid) continue;
    k++;
    await env.DB.prepare(`INSERT INTO cron_tareas
      (id,obra_id,wbs,nombre,tipo,dur,cal,anc,pred,avance,oculta,nota,orden,grupo,ini_calc,fin_calc,actualizado_por,actualizado_en)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
      ON CONFLICT(id) DO UPDATE SET obra_id=excluded.obra_id,wbs=excluded.wbs,
        nombre=excluded.nombre,tipo=excluded.tipo,
        dur=excluded.dur,cal=excluded.cal,anc=excluded.anc,pred=excluded.pred,
        avance=excluded.avance,oculta=excluded.oculta,nota=excluded.nota,orden=excluded.orden,
        grupo=excluded.grupo,ini_calc=excluded.ini_calc,fin_calc=excluded.fin_calc,
        actualizado_por=excluded.actualizado_por,actualizado_en=excluded.actualizado_en`)
      .bind(tid, id, t.wbs || String(k), String(t.nom || t.nombre || 'Actividad'),
        t.tipo || 'eje', Number(t.dur || 0), t.cal || 'LV', t.anc || null,
        JSON.stringify(t.pred || []), Math.max(0, Math.min(100, Number(t.av || 0))),
        t.oculta ? 1 : 0, t.nota || null, Number(t.orden || k),
        t.grupo || null, t.ini || null, t.fin || null, uid, ahora).run();
    n++;
  }
  await env.DB.prepare('UPDATE cron_obras SET actualizado_en=? WHERE id=?').bind(ahora, id).run();
  await cronAudit(env, body.pin, 'tareas_guardar', id + ': ' + n + ' guardadas, ' + borradas + ' borradas');
  return j({ ok: true, guardadas: n, borradas });
}

// ── cron_avance: nivel operar, solo toca el porcentaje ───────
async function cronAvance(env, body) {
  await cronEnsure(env);
  const tid = String(body.tarea_id || '').trim();
  if (!tid) return j({ ok: false, error: 'Falta tarea_id' });
  const t = await env.DB.prepare('SELECT obra_id,nombre FROM cron_tareas WHERE id=?').bind(tid).first();
  if (!t) return j({ ok: false, error: 'No encontré esa actividad' });
  const nivel = await cronNivel(env, body.pin, body.key, t.obra_id);
  if (nivelOrd(nivel) < nivelOrd('operar')) return j({ ok: false, error: 'Marcar avance exige nivel operar' }, 403);
  const av = Math.max(0, Math.min(100, Number(body.avance || 0)));
  const u = await cronUsuario(env, body.pin);
  const ahora = crParts().iso;
  const sets = ['avance=?', 'actualizado_por=?', 'actualizado_en=?'];
  const bind = [av, u ? u.id : 'setup', ahora];
  if (typeof body.nota === 'string') { sets.splice(1, 0, 'nota=?'); bind.splice(1, 0, body.nota); }
  bind.push(tid);
  await env.DB.prepare('UPDATE cron_tareas SET ' + sets.join(',') + ' WHERE id=?').bind(...bind).run();
  await cronAudit(env, body.pin, 'avance', t.nombre + ' → ' + av + '%');
  return j({ ok: true, avance: av });
}

// ── cron_asignar: quién ve y edita cada obra ─────────────────
async function cronAsignar(env, body) {
  await cronEnsure(env);
  if (await cronNivel(env, body.pin, body.key, null) !== 'admin')
    return j({ ok: false, error: 'Asignar gente exige nivel administrador' }, 403);
  const obra = String(body.obra_id || '').trim();
  const usuario = String(body.usuario_id || '').trim();
  if (!obra || !usuario) return j({ ok: false, error: 'Falta obra_id o usuario_id' });
  const ahora = crParts().iso;
  if (body.quitar) {
    await env.DB.prepare('DELETE FROM cron_asignados WHERE obra_id=? AND usuario_id=?').bind(obra, usuario).run();
    await cronAudit(env, body.pin, 'desasignar', obra + ' / ' + usuario);
    return j({ ok: true, quitado: true });
  }
  const nivel = NIVELES.includes(String(body.nivel)) ? String(body.nivel) : 'ver';
  await env.DB.prepare('INSERT OR REPLACE INTO cron_asignados (obra_id,usuario_id,nivel,asignado_en) VALUES (?,?,?,?)')
    .bind(obra, usuario, nivel, ahora).run();
  await cronAudit(env, body.pin, 'asignar', obra + ' / ' + usuario + ' → ' + nivel);
  return j({ ok: true, nivel });
}

// ── cron_tipoGuardar: tipos de obra y sus plantillas ─────────
async function cronTipoGuardar(env, body) {
  await cronEnsure(env);
  if (await cronNivel(env, body.pin, body.key, null) !== 'admin')
    return j({ ok: false, error: 'Editar los tipos de obra exige nivel administrador' }, 403);
  const t = body.tipo || {};
  const codigo = String(t.codigo || '').trim().toLowerCase().replace(/[^a-z0-9_]/g, '');
  if (!codigo) return j({ ok: false, error: 'El tipo necesita un código' });
  if (t.eliminar) {
    await env.DB.prepare('UPDATE cron_tipos SET activo=0 WHERE codigo=?').bind(codigo).run();
    return j({ ok: true, eliminado: true });
  }
  const nombre = String(t.nombre || '').trim();
  if (!nombre) return j({ ok: false, error: 'El tipo necesita un nombre' });
  const pl = Array.isArray(t.plantilla) ? t.plantilla : [];
  await env.DB.prepare(`INSERT INTO cron_tipos (codigo,nombre,empresa,plantilla,orden,activo)
    VALUES (?,?,?,?,?,1)
    ON CONFLICT(codigo) DO UPDATE SET nombre=excluded.nombre,empresa=excluded.empresa,
      plantilla=excluded.plantilla,orden=excluded.orden,activo=1`)
    .bind(codigo, nombre, t.empresa || null, JSON.stringify(pl), Number(t.orden || 99)).run();
  await cronAudit(env, body.pin, 'tipo_guardar', nombre + ' (' + pl.length + ' actividades)');
  return j({ ok: true, codigo, actividades: pl.length });
}

// ── cron_obrasEliminar: limpieza en lote ─────────────────────
//  Dos modos: `ids` borra las que se digan, o `conservar` borra TODAS
//  menos esa. Nunca deja el módulo sin ninguna obra: si `conservar` no
//  existe, no se borra nada.
async function cronObrasEliminar(env, body) {
  await cronEnsure(env);
  if (await cronNivel(env, body.pin, body.key, null) !== 'admin')
    return j({ ok: false, error: 'Eliminar obras exige nivel administrador' }, 403);

  const conservar = String(body.conservar || '').trim();
  let ids = Array.isArray(body.ids) ? body.ids.map(String) : [];

  if (conservar) {
    const viva = await env.DB.prepare('SELECT id FROM cron_obras WHERE id=?').bind(conservar).first();
    if (!viva) return j({ ok: false, error: 'No encontré la obra que querés conservar; no borré nada' }, 400);
    const todas = (await env.DB.prepare('SELECT id FROM cron_obras').all()).results || [];
    ids = todas.map(o => o.id).filter(id => id !== conservar);
  }
  ids = ids.filter(id => id && id !== conservar);
  if (!ids.length) return j({ ok: false, error: 'No hay nada que borrar' });

  const u = await cronUsuario(env, body.pin);
  const uid = u ? u.id : 'setup';
  const ahora = crParts().iso;
  let obras = 0, tareas = 0;
  const nombres = [];

  for (const id of ids) {
    const o = await env.DB.prepare('SELECT nombre FROM cron_obras WHERE id=?').bind(id).first();
    if (!o) continue;
    const ts = (await env.DB.prepare('SELECT id,nombre FROM cron_tareas WHERE obra_id=?').bind(id).all()).results || [];
    for (const t of ts) {
      await env.DB.prepare('INSERT INTO cron_borradas (obra_id,tarea_id,nombre,borrado_por,borrado_en) VALUES (?,?,?,?,?)')
        .bind(id, t.id, t.nombre, uid, ahora).run();
    }
    await env.DB.batch([
      env.DB.prepare('DELETE FROM cron_tareas WHERE obra_id=?').bind(id),
      env.DB.prepare('DELETE FROM cron_asignados WHERE obra_id=?').bind(id),
      env.DB.prepare('DELETE FROM cron_obras WHERE id=?').bind(id),
    ]);
    obras++; tareas += ts.length;
    if (nombres.length < 20) nombres.push(o.nombre);
  }

  const quedan = await env.DB.prepare('SELECT COUNT(*) c FROM cron_obras').first();
  await cronAudit(env, body.pin, 'obras_eliminar',
    obras + ' obras y ' + tareas + ' actividades: ' + nombres.slice(0, 8).join(', '));
  return j({ ok: true, obras, tareas, quedan: (quedan && quedan.c) || 0, nombres });
}

// ── cron_unificar: varias obras pasan a ser UNA con secciones ──
//  El paquete de Taco Bell no son ocho obras: es una sola con ocho tiendas
//  adentro. Esto las funde conservando el nombre de cada una como grupo.
//  Los identificadores de actividad NO cambian, así que los vínculos que
//  cruzaban de una tienda a otra quedan resueltos dentro de la misma obra.
async function traRescExportar(env, body) {
  // SOLO LECTURA: devuelve TODOS los viajes crudos de la tabla (para respaldar/rescatar)
  if (!segClaveOk(env, body.key)) return j({ ok:false, error:'clave' }, 403);
  const rows = (await env.DB.prepare('SELECT * FROM tra_viajes ORDER BY numero').all()).results || [];
  return j({ ok:true, total: rows.length, viajes: rows });
}

async function traRescImportar(env, body) {
  // Inserta viajes que NO existan (por numero). NO pisa los que ya están.
  if (!segClaveOk(env, body.key)) return j({ ok:false, error:'clave' }, 403);
  const lista = Array.isArray(body.viajes) ? body.viajes : [];
  let insertados = 0, saltados = 0;
  for (const v of lista) {
    if (!v || !v.numero) { saltados++; continue; }
    const existe = await env.DB.prepare('SELECT numero FROM tra_viajes WHERE numero=?').bind(String(v.numero)).first();
    if (existe) { saltados++; continue; }   // ya está, no lo toco
    try {
      await env.DB.prepare(
        `INSERT INTO tra_viajes (numero,estado,solicitante,email,chofer,vehiculo,placa,fecha,hora,proyecto,origen,destino,bodega_ref,doc_url,payload,creado_en,actualizado_en)
         VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`
      ).bind(
        String(v.numero), v.estado||'creado', v.solicitante||null, v.email||null, v.chofer||null,
        v.vehiculo||null, v.placa||null, v.fecha||null, v.hora||null, v.proyecto||null,
        v.origen||null, v.destino||null, v.bodega_ref||null, v.doc_url||null, v.payload||null,
        v.creado_en||null, v.actualizado_en||null
      ).run();
      insertados++;
    } catch(e) { saltados++; }
  }
  return j({ ok:true, insertados, saltados, total: lista.length });
}

async function fotosRescate(env, body) {
  // SOLO LECTURA: lista las fotos que hay en R2, agrupadas por proyecto.
  if (!segClaveOk(env, body.key)) return j({ ok:false, error:'clave' }, 403);
  if (!env.ARCHIVOS) return j({ ok:false, error:'R2 no configurado' }, 400);
  const base = 'https://marc-erp-espejo.mariangel.workers.dev/archivo';
  const porProy = {};
  let cursor = undefined, total = 0;
  try {
    for (let i = 0; i < 20; i++) {
      const opts = { prefix: 'proyectos/', limit: 1000 };
      if (cursor) opts.cursor = cursor;
      const res = await env.ARCHIVOS.list(opts);
      for (const o of (res.objects || [])) {
        // ruta: proyectos/{pid}/{fid}_full.jpg
        const partes = o.key.split('/');
        if (partes.length < 3) continue;
        const pid = partes[1];
        if (!porProy[pid]) porProy[pid] = [];
        // solo contar las "full" para no duplicar con thumb
        if (o.key.includes('_full')) {
          porProy[pid].push({ key: o.key, url: base + '/' + o.key, size: o.size });
          total++;
        }
      }
      if (!res.truncated) break;
      cursor = res.cursor;
    }
  } catch(e) { return j({ ok:false, error:String(e&&e.message||e) }); }
  const resumen = Object.keys(porProy).map(pid => ({ pid, fotos: porProy[pid].length }));
  return j({ ok:true, total, resumen, porProy: (body.detalle ? porProy : undefined) });
}

async function cronRescate(env, body) {
  // SOLO LECTURA: devuelve todas las obras, sus tareas, y la tumba de borradas.
  if (!segClaveOk(env, body.key)) return j({ ok:false, error:'clave' }, 403);
  // Modo snapshots: copias de seguridad de proyectos (con nombres reales anteriores)
  if (body.snapshots) {
    try {
      await snapEnsure(env);
      if (body.snapPayload) {
        const one = await env.DB.prepare('SELECT payload FROM proyectos_snapshots WHERE id=?').bind(Number(body.snapPayload)).first();
        return j({ ok:true, payload: one ? one.payload : null });
      }
      const pid = String(body.projectId||'');
      const rows = (await env.DB.prepare('SELECT id,project_id,ts,motivo,tablas FROM proyectos_snapshots' + (pid?' WHERE project_id=?':'') + ' ORDER BY id DESC LIMIT 200').bind(...(pid?[pid]:[])).all()).results||[];
      return j({ ok:true, snapshots: rows });
    } catch(e){ return j({ ok:false, error:String(e&&e.message||e) }); }
  }
  await cronEnsure(env);
  const obras = (await env.DB.prepare('SELECT id,nombre,actualizado_en FROM cron_obras ORDER BY actualizado_en').all()).results || [];
  const tareas = (await env.DB.prepare('SELECT id,obra_id,wbs,nombre,avance,ini_calc,fin_calc,actualizado_por,actualizado_en FROM cron_tareas ORDER BY obra_id,orden').all()).results || [];
  const borradas = (await env.DB.prepare('SELECT obra_id,tarea_id,nombre,borrado_por,borrado_en FROM cron_borradas ORDER BY borrado_en DESC LIMIT 2000').all()).results || [];
  let audit = [];
  try { audit = (await env.DB.prepare("SELECT ts,pin,accion,detalle FROM auditoria WHERE accion LIKE 'cron%' OR detalle LIKE '%cron%' ORDER BY ts DESC LIMIT 500").all()).results || []; } catch(e){}
  return j({ ok:true, obras, tareas, borradas, audit,
    resumen:{ obras:obras.length, tareas:tareas.length, borradas:borradas.length } });
}

async function cronUnificar(env, body) {
  await cronEnsure(env);
  if (await cronNivel(env, body.pin, body.key, null) !== 'admin')
    return j({ ok: false, error: 'Unificar obras exige nivel administrador' }, 403);
  const ids = Array.isArray(body.obra_ids) ? body.obra_ids.map(String) : [];
  if (ids.length < 2) return j({ ok: false, error: 'Decime al menos dos obras para unir' });

  const obras = [];
  for (const id of ids) {
    const o = await env.DB.prepare('SELECT * FROM cron_obras WHERE id=?').bind(id).first();
    if (o) obras.push(o);
  }
  if (obras.length < 2) return j({ ok: false, error: 'No encontré esas obras' });

  const u = await cronUsuario(env, body.pin);
  const ahora = crParts().iso;
  const base = obras[0];
  const destino = String(body.destino || '').trim() || base.id;
  let obraDestino = obras.filter(o => o.id === destino)[0];

  if (!obraDestino) {
    // el destino es una obra nueva
    const nid = 'OBR-' + Date.now().toString(36).toUpperCase() + '-' +
      Math.random().toString(36).slice(2, 6).toUpperCase();
    await env.DB.prepare(`INSERT INTO cron_obras
      (id,nombre,cliente,tipo,empresa,razon_social,estado,responsable,feriados,creado_por,creado_en,actualizado_en)
      VALUES (?,?,?,?,?,?,?,?,?,?,?,?)`)
      .bind(nid, String(body.nombre || 'Paquete unificado'), base.cliente || null,
        base.tipo || null, base.empresa || null, base.razon_social || null,
        'activo', base.responsable || null, base.feriados == null ? 1 : base.feriados,
        u ? u.id : 'setup', ahora, ahora).run();
    obraDestino = await env.DB.prepare('SELECT * FROM cron_obras WHERE id=?').bind(nid).first();
  } else if (body.nombre) {
    await env.DB.prepare('UPDATE cron_obras SET nombre=?,actualizado_en=? WHERE id=?')
      .bind(String(body.nombre), ahora, obraDestino.id).run();
  }

  // Las actividades se mudan y cada obra de origen se vuelve una sección
  let movidas = 0;
  for (const o of obras) {
    const r = await env.DB.prepare(
      `UPDATE cron_tareas SET obra_id=?, grupo=COALESCE(grupo,?), actualizado_en=? WHERE obra_id=?`)
      .bind(obraDestino.id, o.nombre, ahora, o.id).run();
    const n = await env.DB.prepare('SELECT COUNT(*) c FROM cron_tareas WHERE obra_id=? AND grupo=?')
      .bind(obraDestino.id, o.nombre).first();
    movidas += (n && n.c) || 0;
  }

  // Las asignaciones se heredan y las obras vacías desaparecen
  let cerradas = 0;
  for (const o of obras) {
    if (o.id === obraDestino.id) continue;
    const as = (await env.DB.prepare('SELECT usuario_id,nivel FROM cron_asignados WHERE obra_id=?')
      .bind(o.id).all()).results || [];
    for (const a of as) {
      await env.DB.prepare('INSERT OR IGNORE INTO cron_asignados (obra_id,usuario_id,nivel,asignado_en) VALUES (?,?,?,?)')
        .bind(obraDestino.id, a.usuario_id, a.nivel, ahora).run();
    }
    await env.DB.batch([
      env.DB.prepare('DELETE FROM cron_asignados WHERE obra_id=?').bind(o.id),
      env.DB.prepare('DELETE FROM cron_obras WHERE id=?').bind(o.id),
    ]);
    cerradas++;
  }

  await cronAudit(env, body.pin, 'unificar',
    obras.length + ' obras → «' + obraDestino.nombre + '» (' + movidas + ' actividades)');
  return j({ ok: true, obra_id: obraDestino.id, nombre: obraDestino.nombre,
    secciones: obras.length, actividades: movidas, cerradas });
}

// ── cron_dashboard: el panel de control ──────────────────────
async function cronDashboard(env, body) {
  await cronEnsure(env);
  const nivel = await cronNivel(env, body.pin, body.key, null);
  if (nivel === 'sin') return j({ ok: false, error: 'Sin acceso a cronogramas' }, 403);
  const u = await cronUsuario(env, body.pin);
  const esAdmin = nivel === 'admin';
  const hoy = crParts().fecha;

  let sql = 'SELECT o.* FROM cron_obras o WHERE o.estado=?';
  const bind = ['activo'];
  if (!esAdmin && u) {
    sql += ' AND (o.creado_por=? OR EXISTS (SELECT 1 FROM cron_asignados a WHERE a.obra_id=o.id AND a.usuario_id=?))';
    bind.push(u.id, u.id);
  }
  const obras = (await env.DB.prepare(sql).bind(...bind).all()).results || [];

  const res = [];
  let atrasadasTot = 0, tareasTot = 0, avSum = 0, avPeso = 0;
  for (const o of obras) {
    const r = await env.DB.prepare(
      `SELECT COUNT(*) n, SUM(CASE WHEN tipo<>'hito' THEN dur ELSE 0 END) pd,
              SUM(CASE WHEN tipo<>'hito' THEN dur*avance ELSE 0 END) pa,
              MIN(ini_calc) i, MAX(fin_calc) f,
              SUM(CASE WHEN fin_calc IS NOT NULL AND fin_calc < ? AND avance < 100 AND tipo<>'hito' THEN 1 ELSE 0 END) atr
       FROM cron_tareas WHERE obra_id=?`).bind(hoy, o.id).first();
    const av = (r && r.pd) ? Math.round(r.pa / r.pd) : 0;
    const atr = (r && r.atr) || 0;
    atrasadasTot += atr; tareasTot += (r && r.n) || 0;
    avSum += av * ((r && r.pd) || 0); avPeso += (r && r.pd) || 0;
    const prox = await env.DB.prepare(
      `SELECT nombre,ini_calc FROM cron_tareas WHERE obra_id=? AND tipo='hito' AND ini_calc>=?
       ORDER BY ini_calc LIMIT 1`).bind(o.id, hoy).first();
    res.push({
      id: o.id, nombre: o.nombre, cliente: o.cliente, tipo: o.tipo, empresa: o.empresa,
      responsable: o.responsable, tareas: (r && r.n) || 0, avance: av, atrasadas: atr,
      inicio: r ? r.i : null, fin: r ? r.f : null,
      semaforo: av >= 100 ? 'terminado' : (atr > 0 ? 'atrasado'
        : (av > 0 ? 'enCurso' : (r && r.i && r.i > hoy ? 'porIniciar' : 'enCurso'))),
      proximoHito: prox ? { nombre: prox.nombre, fecha: prox.ini_calc } : null,
    });
  }
  res.sort((a, b) => (b.atrasadas - a.atrasadas) || String(a.fin || '').localeCompare(String(b.fin || '')));
  return j({
    ok: true, hoy, nivel, esAdmin, obras: res,
    kpi: { obras: res.length, tareas: tareasTot, atrasadas: atrasadasTot,
      avance: avPeso ? Math.round(avSum / avPeso) : 0,
      terminadas: res.filter(x => x.semaforo === 'terminado').length },
  });
}



